import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Booking_com.Search_locations import Search_locations
from Tools.Booking_com.Search_hotels import Search_hotels

import traceback
from datetime import date, timedelta



DESTINATION_NAME = "Vinegar Hill"
STAY_NIGHTS = 7
ADULTS_NUMBER = 2
ROOM_NUMBER = 1
FILTER_BY_CURRENCY = "USD"
ORDER_BY = "price"
LOCALE = "en-us"
CHECKIN_DATE = (date.today() + timedelta(days=1)).isoformat()
CHECKOUT_DATE = (date.today() + timedelta(days=1 + STAY_NIGHTS)).isoformat()


def normalize_api_string(value):
    return str(value).strip().lower().replace("®", "").replace("™", "").replace("©", "")


def find_location_identifier(destination_name):
    results = Search_locations(destination_name)

    if not isinstance(results, list):
        raise Exception("Unexpected location search response format.")

    if not results:
        return None, None, None

    normalized_query = normalize_api_string(destination_name)
    partial_match = None

    for item in results:
        name = normalize_api_string(item.get("name", ""))
        label = normalize_api_string(item.get("label", ""))
        city_name = normalize_api_string(item.get("city_name", ""))

        if normalized_query in name or normalized_query in label or normalized_query in city_name:
            return item.get("dest_type"), item.get("dest_id"), item

        if partial_match is None:
            partial_match = item

    chosen = partial_match or results[0]
    return chosen.get("dest_type"), chosen.get("dest_id"), chosen


def search_hotels_for_stay(dest_type, dest_id, checkin_date, checkout_date):
    if not dest_type or dest_id is None:
        return {}

    return Search_hotels(
        checkin_date=checkin_date,
        checkout_date=checkout_date,
        dest_type=dest_type,
        dest_id=dest_id,
        order_by=ORDER_BY,
        room_number=ROOM_NUMBER,
        filter_by_currency=FILTER_BY_CURRENCY,
    )


def extract_total_prices(hotel_results):
    if not isinstance(hotel_results, dict):
        return []

    results = hotel_results.get("result", [])
    prices = []

    for hotel in results:
        price = hotel.get("min_total_price")
        if isinstance(price, (int, float)):
            prices.append(price)
            continue

        breakdown = hotel.get("composite_price_breakdown", {})
        all_inclusive = breakdown.get("all_inclusive_amount", {})
        value = all_inclusive.get("value")
        if isinstance(value, (int, float)):
            prices.append(value)

    return prices


def determine_lowest_total_price(hotel_results):
    prices = extract_total_prices(hotel_results)
    if not prices:
        return None
    return min(prices)


def format_price(price, currency=FILTER_BY_CURRENCY):
    if price is None:
        raise Exception("No hotel prices found.")
    if isinstance(price, float) and price.is_integer():
        price = int(price)
    return (
        f"Lowest total price for {STAY_NIGHTS} nights in {DESTINATION_NAME}: {price:.2f} {currency}"
        if isinstance(price, float)
        else f"Lowest total price for {STAY_NIGHTS} nights in {DESTINATION_NAME}: {price} {currency}"
    )


def main():
    dest_type, dest_id, matched_location = find_location_identifier(DESTINATION_NAME)

    if not dest_type or dest_id is None:
        raise Exception(f"No matching location found for {DESTINATION_NAME}.")

    hotel_results = search_hotels_for_stay(dest_type, dest_id, CHECKIN_DATE, CHECKOUT_DATE)
    lowest_total_price = determine_lowest_total_price(hotel_results)

    print(format_price(lowest_total_price, FILTER_BY_CURRENCY))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Booking_com.Search_locations import Search_locations
from Tools.Booking_com.Search_hotels import Search_hotels

import traceback

LOCATION_QUERY_NAME = "Maspeth"
CHECKIN_DATE = "2026-06-13"
CHECKOUT_DATE = "2026-06-21"
DEST_TYPE_PRIORITY = "district"
ORDER_BY = "price"
ROOM_NUMBER = 1
FILTER_BY_CURRENCY = "USD"
STAY_NIGHTS = 8


def select_best_location(location_results, query_name):
    if not isinstance(location_results, list) or not location_results:
        return None

    q = str(query_name).strip().lower()
    preferred = None
    fallback = None

    for item in location_results:
        if not isinstance(item, dict):
            continue
        name = str(item.get("name", "")).strip().lower()
        label = str(item.get("label", "")).strip().lower()
        dest_type = str(item.get("dest_type", "")).strip().lower()

        if q and (q in name or q in label):
            if preferred is None:
                preferred = item
            if dest_type == DEST_TYPE_PRIORITY:
                return item

        if fallback is None and dest_type == DEST_TYPE_PRIORITY:
            fallback = item

    return preferred or fallback or location_results[0]


def build_search_params(location):
    if not isinstance(location, dict):
        return None

    dest_id = location.get("dest_id")
    dest_type = location.get("dest_type")

    if dest_id is None or dest_type is None:
        return None

    return {
        "checkin_date": CHECKIN_DATE,
        "checkout_date": CHECKOUT_DATE,
        "dest_type": dest_type,
        "dest_id": dest_id,
        "order_by": ORDER_BY,
        "room_number": ROOM_NUMBER,
        "filter_by_currency": FILTER_BY_CURRENCY,
    }


def extract_lowest_total_price(hotel_response):
    if not isinstance(hotel_response, dict):
        return None

    results = hotel_response.get("result", [])
    if not isinstance(results, list) or not results:
        return None

    lowest = None
    lowest_price = None

    for hotel in results:
        if not isinstance(hotel, dict):
            continue

        price = hotel.get("min_total_price")
        if price is None:
            cpr = hotel.get("composite_price_breakdown", {})
            if isinstance(cpr, dict):
                gross = cpr.get("gross_amount", {})
                if isinstance(gross, dict):
                    price = gross.get("value")
                if price is None:
                    all_inclusive = cpr.get("all_inclusive_amount", {})
                    if isinstance(all_inclusive, dict):
                        price = all_inclusive.get("value")

        try:
            numeric_price = float(price)
        except (TypeError, ValueError):
            continue

        if lowest_price is None or numeric_price < lowest_price:
            lowest_price = numeric_price
            lowest = hotel

    return lowest_price, lowest


def compute_total_minimum_price():
    location_results = Search_locations(LOCATION_QUERY_NAME)
    best_location = select_best_location(location_results, LOCATION_QUERY_NAME)

    if not best_location:
        return "No matching location found for Maspeth."

    params = build_search_params(best_location)
    if not params:
        return "Location found, but required destination fields are missing."

    hotel_response = Search_hotels(
        params["checkin_date"],
        params["checkout_date"],
        params["dest_type"],
        params["dest_id"],
        params["order_by"],
        params["room_number"],
        params["filter_by_currency"],
    )

    lowest_price, lowest_hotel = extract_lowest_total_price(hotel_response)
    if lowest_price is None:
        return "No hotel pricing data available for the selected stay."

    hotel_name = ""
    if isinstance(lowest_hotel, dict):
        hotel_name = lowest_hotel.get("hotel_name") or lowest_hotel.get("hotel_name_trans") or ""

    if hotel_name:
        return f"The lowest total price for 8 nights in Maspeth is {lowest_price:.2f} {FILTER_BY_CURRENCY} at {hotel_name}."
    return f"The lowest total price for 8 nights in Maspeth is {lowest_price:.2f} {FILTER_BY_CURRENCY}."


def main():
    result = compute_total_minimum_price()
    print(result)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
