from Tools.Local_Business_Data.Search import Search
from Tools.Local_Business_Data.Search import Search

import traceback

BRONXDALE_AREA_NAME = "Bronxdale"
HOTEL_CATEGORY_KEY = "hotel"
SEARCH_QUERY_TEMPLATE = "Hotels in {}"


def build_search_query(area_name):
    if not isinstance(area_name, str):
        raise TypeError("area_name must be a string")
    return SEARCH_QUERY_TEMPLATE.format(area_name.strip())


def search_hotels_in_area(area_name):
    query = build_search_query(area_name)
    return Search(query)


def extract_data_items(search_results):
    if not isinstance(search_results, dict):
        return []
    data = search_results.get("data", [])
    if data is None:
        return []
    if not isinstance(data, list):
        return []
    return data


def is_hotel_item(item):
    if not isinstance(item, dict):
        return False

    type_value = item.get("type")
    subtypes = item.get("subtypes", [])

    type_matches = isinstance(type_value, str) and HOTEL_CATEGORY_KEY.lower() in type_value.lower()
    subtype_matches = False

    if isinstance(subtypes, list):
        for subtype in subtypes:
            if isinstance(subtype, str) and HOTEL_CATEGORY_KEY.lower() in subtype.lower():
                subtype_matches = True
                break

    return type_matches or subtype_matches


def count_hotels(search_results):
    items = extract_data_items(search_results)
    hotel_items = [item for item in items if is_hotel_item(item)]
    return len(hotel_items)


def format_result(area_name, hotel_count):
    return f"How many hotels are there in {area_name}? {hotel_count}"


def main():
    bronxdale_results = search_hotels_in_area(BRONXDALE_AREA_NAME)
    total_hotels = count_hotels(bronxdale_results)
    print(format_result(BRONXDALE_AREA_NAME, total_hotels))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

