        return f"No hotel count data found for {PORT_RICHMOND_QUERY}."
    return f"Number of hotels in {PORT_RICHMOND_QUERY}: {hotel_count}"


def main():
    total_hotels = resolve_port_richmond_hotel_count()
    print(format_result(total_hotels))


if __name__ == "__main__":
