import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Booking_com.Search_locations import Search_locations
from Tools.Booking_com.Search_hotels_by_coordinates import Search_hotels_by_coordinates

import traceback

LOCATION_QUERY = "East Morrisania"
CHECKIN_DATE = "2026-06-13"
CHECKOUT_DATE = "2026-06-14"
ROOM_NUMBER = 1
ORDER_BY = "price"
FILTER_BY_CURRENCY = "USD"
ADULTS_NUMBER = 2


def safe_get(d, key, default=None):
    if isinstance(d, dict):
        return d.get(key, default)
    return default


def normalize_to_number(value):
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        cleaned = "".join(ch for ch in value if (ch.isdigit() or ch in ".-"))
        try:
            return float(cleaned) if cleaned else None
        except ValueError:
            return None
    return None


def search_location(location_query):
    try:
        return Search_locations(location_query)
    except Exception:
        raise


def select_target_location(location_results):
    if not isinstance(location_results, list):
        return None

    query = LOCATION_QUERY.lower()
    best_match = None

    for item in location_results:
        if not isinstance(item, dict):
            continue
        label = str(item.get("label", "")).lower()
        name = str(item.get("name", "")).lower()
        region = str(item.get("region", "")).lower()
        city_name = str(item.get("city_name", "")).lower()
        dest_type = str(item.get("dest_type", "")).lower()

        if query in label or query in name or query in region or query in city_name:
            best_match = item
            if "district" in dest_type:
                return best_match

    return best_match if best_match is not None else (location_results[0] if location_results else None)


def search_hotels_by_coordinates(location_coordinates):
    latitude, longitude = location_coordinates
    try:
        return Search_hotels_by_coordinates(
            CHECKOUT_DATE,
            CHECKIN_DATE,
            latitude,
            ROOM_NUMBER,
            ORDER_BY,
            longitude,
            FILTER_BY_CURRENCY,
        )
    except Exception:
        raise


def extract_average_price(hotel_results):
    if not isinstance(hotel_results, dict):
        return None, 0

    result_list = hotel_results.get("result", [])
    if not isinstance(result_list, list) or not result_list:
        return None, 0

    prices = []
    for hotel in result_list:
        if not isinstance(hotel, dict):
            continue

        price = None
        composite = hotel.get("composite_price_breakdown")
        if isinstance(composite, dict):
            all_inclusive = composite.get("all_inclusive_amount")
            if isinstance(all_inclusive, dict):
                price = normalize_to_number(all_inclusive.get("value"))

            if price is None:
                gross_amount = composite.get("gross_amount")
                if isinstance(gross_amount, dict):
                    price = normalize_to_number(gross_amount.get("value"))

            if price is None:
                gross_per_night = composite.get("gross_amount_per_night")
                if isinstance(gross_per_night, dict):
                    price = normalize_to_number(gross_per_night.get("value"))

        if price is None:
            min_total_price = hotel.get("min_total_price")
            price = normalize_to_number(min_total_price)

        if price is not None:
            prices.append(price)

    if not prices:
        return None, 0

    return sum(prices) / len(prices), len(prices)


def main():
    location_results = search_location(LOCATION_QUERY)
    target_location = select_target_location(location_results)

    if not target_location:
        print(f"No location found for '{LOCATION_QUERY}'.")
        return

    latitude = safe_get(target_location, "latitude")
    longitude = safe_get(target_location, "longitude")

    if latitude is None or longitude is None:
        print(f"Location found for '{LOCATION_QUERY}', but coordinates are unavailable.")
        return

    hotel_results = search_hotels_by_coordinates((latitude, longitude))
    average_price, price_count = extract_average_price(hotel_results)

    if average_price is None:
        print(f"No hotel prices found for East Morrisania.")
        return

    print(f"Average hotel price in East Morrisania based on {price_count} hotels: {average_price:.2f} {FILTER_BY_CURRENCY}")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Booking_com.Search_locations import Search_locations
from Tools.Booking_com.Search_hotels import Search_hotels
from Tools.Booking_com.Search_hotels import Search_hotels

import traceback
from datetime import date, timedelta

# Module-level pinned constants derived from the user requirement and API schema.
TARGET_LOCATION_QUERY = "Stuyvesant Town"
TARGET_LOCATION_HINT = "Stuyvesant Town"
LOCALE = "en-us"
ADULTS_NUMBER = 2
UNITS = "metric"
ROOM_NUMBER = 1
FILTER_BY_CURRENCY = "USD"
ORDER_BY = "price"

# Relevant dates must be future/present; use hardcoded future dates.
CHECKIN_DATE = "2026-06-15"
CHECKOUT_DATE = "2026-06-17"


def _safe_get(dct, *keys, default=None):
    current = dct
    for key in keys:
        if not isinstance(current, dict) or key not in current:
            return default
        current = current[key]
    return current


def _normalize_text(value):
    return str(value).strip().lower() if value is not None else ""


def find_best_matching_location(location_results, target_hint):
    if not isinstance(location_results, list):
        return None

    target_norm = _normalize_text(target_hint)
    best = None

    for item in location_results:
        if not isinstance(item, dict):
            continue
        name = _normalize_text(item.get("name"))
        label = _normalize_text(item.get("label"))
        city_name = _normalize_text(item.get("city_name"))
        region = _normalize_text(item.get("region"))
        combined = " ".join([name, label, city_name, region])

        if target_norm in combined:
            return item

        if best is None and name:
            best = item

    return best if best is not None else (location_results[0] if location_results else None)


def search_destination_location():
    location_results = Search_locations(TARGET_LOCATION_QUERY)
    selected_location = find_best_matching_location(location_results, TARGET_LOCATION_HINT)
    return selected_location


def search_hotels_for_location(location):
    if not isinstance(location, dict):
        return {}

    dest_type = location.get("dest_type")
    dest_id = location.get("dest_id")

    if dest_type is None or dest_id is None:
        return {}

    hotel_results = Search_hotels(
        CHECKIN_DATE,
        CHECKOUT_DATE,
        dest_type,
        dest_id,
        ORDER_BY,
        ROOM_NUMBER,
        FILTER_BY_CURRENCY,
    )
    return hotel_results


def extract_prices_from_hotel_results(hotel_results):
    if not isinstance(hotel_results, dict):
        return []

    results = hotel_results.get("result", [])
    if not isinstance(results, list):
        return []

    prices = []
    for hotel in results:
        if not isinstance(hotel, dict):
            continue

        price = _safe_get(hotel, "min_total_price", default=None)
        if price is None:
            price = _safe_get(hotel, "composite_price_breakdown", "gross_amount", "value", default=None)
        if price is None:
            price = _safe_get(hotel, "composite_price_breakdown", "all_inclusive_amount", "value", default=None)

        if isinstance(price, (int, float)):
            prices.append(float(price))
        else:
            try:
                prices.append(float(price))
            except (TypeError, ValueError):
                continue

    return prices


def compute_average_price(prices):
    if not prices:
        return None
    return sum(prices) / len(prices)


def format_average_price_output(location, average_price, count):
    location_name = None
    if isinstance(location, dict):
        location_name = location.get("name") or location.get("label") or location.get("city_name") or location.get("region")

    if average_price is None:
        return f"No hotel prices were found for {location_name or TARGET_LOCATION_HINT}."

    return (
        f"Average hotel price in {location_name or TARGET_LOCATION_HINT}: "
        f"{average_price:.2f} USD across {count} hotel listing(s)."
    )


def main():
    location = search_destination_location()
    hotel_results = search_hotels_for_location(location)
    prices = extract_prices_from_hotel_results(hotel_results)
    average_price = compute_average_price(prices)
    output = format_average_price_output(location, average_price, len(prices))
    print(output)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Booking_com.Search_locations import Search_locations
from Tools.Booking_com.Search_hotels import Search_hotels
from Tools.Booking_com.Search_hotels import Search_hotels

import traceback
from datetime import date, timedelta

# Module-level pinned constants
AREA_NAME = "Howland Hook"
LOCALE = "en-us"
ADULTS_NUMBER = 2
UNITS = "metric"
ROOM_NUMBER = 1
ORDER_BY = "price"
FILTER_BY_CURRENCY = "USD"
CHECKIN_DATE = (date.today() + timedelta(days=1)).isoformat()
CHECKOUT_DATE = (date.today() + timedelta(days=2)).isoformat()
PRICE_FIELD_PRIMARY = "min_total_price"
PRICE_FIELD_FALLBACKS = (
    "min_total_price",
    "price",
)
RESULT_LIST_KEY = "result"


def find_best_location(area_name):
    try:
        locations = Search_locations(area_name)
    except Exception:
        raise

    if not isinstance(locations, list):
        return None

    # Explicit schema-grounded key usage from response_schema:
    # name, dest_type, dest_id, nr_hotels, hotels, label
    def score_location(loc):
        score = 0
        name = str(loc.get("name", "")).lower()
        label = str(loc.get("label", "")).lower()
        dest_type = str(loc.get("dest_type", "")).lower()
        nr_hotels = loc.get("nr_hotels", loc.get("hotels", 0)) or 0

        if area_name.lower() in name or area_name.lower() in label:
            score += 100
        if dest_type:
            score += 10
        try:
            score += min(int(nr_hotels), 50)
        except Exception:
            pass
        return score

    if not locations:
        return None

    return max(locations, key=score_location)


def search_hotels_for_location(location):
    if not location:
        return {"result": []}

    dest_type = location.get("dest_type")
    dest_id = location.get("dest_id")

    if not dest_type or not dest_id:
        return {"result": []}

    try:
        return Search_hotels(
            CHECKIN_DATE,
            CHECKOUT_DATE,
            dest_type,
            dest_id,
            ORDER_BY,
            ROOM_NUMBER,
            FILTER_BY_CURRENCY,
        )
    except Exception:
        raise


def extract_prices(hotel_search_response):
    if not isinstance(hotel_search_response, dict):
        return []

    hotels = hotel_search_response.get(RESULT_LIST_KEY, [])
    if not isinstance(hotels, list):
        return []

    prices = []
    for hotel in hotels:
        if not isinstance(hotel, dict):
            continue

        price = None

        # Grounded by response_schema keys:
        # result[].min_total_price
        for key in PRICE_FIELD_FALLBACKS:
            value = hotel.get(key)
            if isinstance(value, (int, float)):
                price = float(value)
                break

        if price is None:
            composite = hotel.get("composite_price_breakdown", {})
            if isinstance(composite, dict):
                all_inclusive = composite.get("all_inclusive_amount", {})
                if isinstance(all_inclusive, dict):
                    value = all_inclusive.get("value")
                    if isinstance(value, (int, float)):
                        price = float(value)

        if price is not None:
            prices.append(price)

    return prices


def calculate_average(prices):
    if not prices:
        return None
    return sum(prices) / len(prices)


def format_output(area_name, average_price, count):
    if average_price is None:
        return f"No hotel price data found for {area_name}."
    return (
        f"Average hotel price in {area_name}: {average_price:.2f} "
        f"(based on {count} hotels)"
    )


def main():
    location = find_best_location(AREA_NAME)
    hotels = search_hotels_for_location(location)
    prices = extract_prices(hotels)
    average_price = calculate_average(prices)
    print(format_output(AREA_NAME, average_price, len(prices)))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

