COUNTRY_CODE = "us"


def extract_first_location(search_response):
    if not isinstance(search_response, dict):
        return None

    data = search_response.get("data", [])
    if not isinstance(data, list) or not data:
        return None

    return data[0]


def find_target_location(target_query):
    response = Search(target_query)
    return extract_first_location(response)


def find_nearby_businesses(target_location, radius_miles):
    if not isinstance(target_location, dict):
        return []

    lat = target_location.get("latitude")
    lng = target_location.get("longitude")
    if lat is None or lng is None:
        return []

    response = Search_Nearby(NEARBY_QUERY, lat, lng)

    if not isinstance(response, dict):
        return []

    data = response.get("data", [])
    if not isinstance(data, list):
        return []

    return data


def get_review_rate_from_business(business):
    if not isinstance(business, dict):
        return None

    business_id = business.get("business_id")
    if not business_id:
        return None

    review_response = Place_reviews(business_id, COUNTRY_CODE)
    if not isinstance(review_response, dict):
        return None

    data = review_response.get("data", {})
    if not isinstance(data, dict):
        return None

    reviews = data.get("reviews", [])
    if not isinstance(reviews, list) or not reviews:
        return None

    rates = []
    for review in reviews:
        if isinstance(review, dict):
            rate = review.get("review_rate")
            if isinstance(rate, (int, float)):
                rates.append(float(rate))

    if not rates:
        return None

    return sum(rates) / len(rates)


def compute_average(values):
    numeric_values = [float(v) for v in values if isinstance(v, (int, float))]
    if not numeric_values:
        return None
    return sum(numeric_values) / len(numeric_values)


def main():
    target_location = find_target_location(TARGET_QUERY)
    nearby_businesses = find_nearby_businesses(target_location, NEARBY_RADIUS_MILES)

    review_rates = []
    for business in nearby_businesses:
        rate = get_review_rate_from_business(business)
        if rate is not None:
            review_rates.append(rate)

    average_review_rate = compute_average(review_rates)

    if average_review_rate is None:
        print("No review rate data found for nearby businesses.")
    else:
        print(f"Average review rate within {NEARBY_RADIUS_MILES} miles of '{TARGET_QUERY}': {average_review_rate:.2f}")


if __name__ == "__main__":
