from Tools.Forward_and_Reverse_Geocoding.GeocodingSearch import GeocodingSearch
from Tools.Maps_Data.What_is_here import What_is_here
from Tools.Maps_Data.Place_reviews import Place_reviews
from Tools.Maps_Data.Search import Search

import traceback

# Module-level pinned constants
TARGET_PLACE = "Heart of Park Slope"
TARGET_AREA = "Park Slope"
SEARCH_QUERY = f"{TARGET_PLACE}, {TARGET_AREA}"
NEARBY_RADIUS_MILES = 5
NEARBY_RADIUS_METERS = int(NEARBY_RADIUS_MILES * 1609.34)
SEARCH_LIMIT = "5"
SEARCH_LANGUAGE = "en"
COUNTRY_CODE = "us"
MAPS_LANGUAGE = "en"

def safe_get(dct, path, default=None):
    current = dct
    for key in path:
        if not isinstance(current, dict) or key not in current:
            return default
        current = current[key]
    return current

def resolve_location(target_place, target_area):
    query = f"{target_place}, {target_area}"
    result = GeocodingSearch(q=query, limit=SEARCH_LIMIT, accept_language=SEARCH_LANGUAGE)
    if not isinstance(result, list):
        return None
    for item in result:
        lat = item.get("lat")
        lon = item.get("lon")
        if lat is not None and lon is not None:
            try:
                return {"lat": float(lat), "lng": float(lon), "raw": item}
            except (TypeError, ValueError):
                continue
    return None

def find_nearby_businesses(coordinates, radius_meters):
    if not coordinates:
        return []
    result = What_is_here(
        lat=str(coordinates["lat"]),
        lng=str(coordinates["lng"]),
        lang=MAPS_LANGUAGE,
        country=COUNTRY_CODE,
    )
    places = safe_get(result, ["data", "places"], [])
    if not isinstance(places, list):
        return []
    return places

def collect_business_ids(place_list):
    business_ids = []
    for place in place_list:
        business_id = place.get("business_id")
        if business_id:
            business_ids.append(business_id)
    return business_ids

def get_review_ratings(place_list):
    ratings = []
    for place in place_list:
        business_id = place.get("business_id")
        if not business_id:
            continue
        try:
            review_result = Place_reviews(business_id=business_id, country=COUNTRY_CODE)
        except Exception:
            continue
        review_data = safe_get(review_result, ["data"], {})
        rating = review_data.get("rating")
        if rating is not None:
            try:
                ratings.append(float(rating))
            except (TypeError, ValueError):
                continue
    return ratings

def compute_average(values):
    valid = []
    for value in values:
        try:
            valid.append(float(value))
        except (TypeError, ValueError):
            continue
    if not valid:
        return None
    return sum(valid) / len(valid)

def format_output(average_rating, total_places, rated_places):
    print(f"Search area: {TARGET_PLACE} in {TARGET_AREA}")
    print(f"Radius: {NEARBY_RADIUS_MILES} miles")
    print(f"Nearby places found: {total_places}")
    print(f"Places with review ratings: {rated_places}")
    if average_rating is None:
        print("Average review rate: no valid ratings found")
    else:
        print(f"Average review rate: {average_rating:.2f}")

def main():
    coordinates = resolve_location(TARGET_PLACE, TARGET_AREA)
    nearby_places = find_nearby_businesses(coordinates, NEARBY_RADIUS_METERS)
    ratings = get_review_ratings(nearby_places)
    average_rating = compute_average(ratings)
    format_output(average_rating, len(nearby_places), len(ratings))

if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
