if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Local_Business_Data.Search_Nearby import Search_Nearby
from Tools.Local_Business_Data.Search_In_Area import Search_In_Area
from Tools.Local_Business_Data.Business_Details import Business_Details
from Tools.Local_Business_Data.Business_Reviews import Business_Reviews

import traceback

RICHMOND_HILL_QUERY = "Richmond Hill JFK LGA hospitals malls bus train #4"
SEARCH_IN_AREA_QUERY = "Richmond Hill JFK LGA hospitals malls bus train #4"
SEARCH_LAT = 40.6945
SEARCH_LNG = -73.8250
SEARCH_ZOOM = 14
REGION = "us"
MAX_BUSINESSES_TO_PROCESS = 10
MIN_REVIEWS_THRESHOLD = 1


def safe_get(data, *keys, default=None):
    current = data
    for key in keys:
        if isinstance(current, dict) and key in current:
            current = current[key]
        else:
            return default
    return current


def extract_business_items(response):
    if isinstance(response, dict):
        data = response.get("data", [])
        if isinstance(data, list):
            return data
    return []


def search_target_area():
    nearby = Search_Nearby(RICHMOND_HILL_QUERY, SEARCH_LAT, SEARCH_LNG)
    in_area = Search_In_Area(SEARCH_IN_AREA_QUERY, SEARCH_LAT, SEARCH_LNG, SEARCH_ZOOM)
    return nearby, in_area


def combine_candidates(nearby_response, in_area_response):
    candidates = []
    seen = set()

    for response in (nearby_response, in_area_response):
        for item in extract_business_items(response):
            business_id = item.get("business_id")
            if business_id and business_id not in seen:
                seen.add(business_id)
                candidates.append(item)

    return candidates


def fetch_business_details_for_candidates(candidates):
    detailed = []
    for item in candidates[:MAX_BUSINESSES_TO_PROCESS]:
        business_id = item.get("business_id")
        if not business_id:
            continue
        details_response = Business_Details(business_id, REGION)
        details_items = extract_business_items(details_response)
        if details_items:
            detailed.append(details_items[0])
    return detailed


def fetch_reviews_for_businesses(businesses):
    review_sets = []
    for business in businesses:
        business_id = business.get("business_id")
        if not business_id:
            continue
        reviews_response = Business_Reviews(business_id)
        reviews = extract_business_items(reviews_response)
        review_sets.append(reviews)
    return review_sets


def compute_average_review_rate(review_sets):
    total_rating = 0.0
    rating_count = 0

    for reviews in review_sets:
        for review in reviews:
            rating = review.get("rating")
            if isinstance(rating, (int, float)):
                total_rating += float(rating)
                rating_count += 1

    if rating_count < MIN_REVIEWS_THRESHOLD:
        return None, 0

    return total_rating / rating_count, rating_count


def format_output(average_rating, rating_count, businesses_count):
    if average_rating is None:
        return (
            "No review ratings were available for the selected Richmond Hill area "
            "based on the nearby business data returned by the APIs."
        )

    return (
        f"Average review rating for businesses found near Richmond Hill "
        f"(around JFK/LGA/hospitals/malls/bus/train #4, ~5 miles / ~10 mins): "
        f"{average_rating:.2f} based on {rating_count} reviews across {businesses_count} businesses."
    )


def main():
    nearby_response, in_area_response = search_target_area()
    candidates = combine_candidates(nearby_response, in_area_response)
    business_details = fetch_business_details_for_candidates(candidates)
    review_sets = fetch_reviews_for_businesses(business_details)
    average_rating, rating_count = compute_average_review_rate(review_sets)
    output = format_output(average_rating, rating_count, len(business_details))
    print(output)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
