from Tools.Booking_com.Search_locations import Search_locations
from Tools.Booking_com.Search_hotels import Search_hotels
from Tools.Booking_com.Get_Policies_of_the_hotel import Get_Policies_of_the_hotel
from Tools.Local_Business_Data.Business_Details import Business_Details

import traceback
from datetime import date, timedelta

TARGET_AREA = "East Elmhurst"
CHECKIN_DATE = (date.today() + timedelta(days=1)).isoformat()
CHECKOUT_DATE = (date.today() + timedelta(days=2)).isoformat()
ORDER_BY = "popularity"
ROOM_NUMBER = 1
FILTER_BY_CURRENCY = "USD"
SEARCH_LOCALE_REGION = "us"


def find_location_match(locations, target_name):
    if not isinstance(locations, list):
        return None

    target_lower = str(target_name).lower()
    for loc in locations:
        if not isinstance(loc, dict):
            continue
        name = str(loc.get("name", "")).lower()
        label = str(loc.get("label", "")).lower()
        city_name = str(loc.get("city_name", "")).lower()
        if target_lower in name or target_lower in label or target_lower in city_name:
            return loc
    return locations[0] if locations else None


def extract_hotels(search_response):
    if not isinstance(search_response, dict):
        return []
    result = search_response.get("result", [])
    if isinstance(result, list):
        return result
    return []


def policy_indicates_flexible_cancellation(policy_response):
    if not isinstance(policy_response, dict):
        return False

    policy_groups = policy_response.get("policy", [])
    if not isinstance(policy_groups, list):
        return False

    flexible_keywords = [
        "free cancellation",
        "flexible cancellation",
        "cancel free of charge",
        "free to cancel",
        "no cancellation fee",
        "cancel any time",
        "can cancel",
    ]

    for group in policy_groups:
        if not isinstance(group, dict):
            continue
        contents = group.get("content", [])
        if not isinstance(contents, list):
            continue
        for content in contents:
            if not isinstance(content, dict):
                continue
            for text_key in ("name", "type"):
                text_value = str(content.get(text_key, "")).lower()
                if any(keyword in text_value for keyword in flexible_keywords):
                    return True

            rulesets = content.get("ruleset", [])
            if isinstance(rulesets, list):
                for ruleset in rulesets:
                    if not isinstance(ruleset, dict):
                        continue
                    for rule in ruleset.get("rule", []):
                        if not isinstance(rule, dict):
                            continue
                        rule_text = str(rule.get("content", "")).lower()
                        if any(keyword in rule_text for keyword in flexible_keywords):
                            return True

            for interval in content.get("age_intervals", []) if isinstance(content.get("age_intervals", []), list) else []:
                if not isinstance(interval, dict):
                    continue
                extra_bed = interval.get("extra_bed", {})
                if isinstance(extra_bed, dict):
                    price_mode = str(extra_bed.get("price_mode", "")).lower()
                    if "free" in price_mode:
                        return True
                crib = interval.get("crib", {})
                if isinstance(crib, dict):
                    price_mode = str(crib.get("price_mode", "")).lower()
                    if "free" in price_mode:
                        return True

    return False


def compute_flexible_cancellation_proportion(hotels):
    total_hotels = len(hotels)
    if total_hotels == 0:
        return None, 0, 0

    flexible_hotels = 0
    for hotel in hotels:
        if not isinstance(hotel, dict):
            continue
        hotel_id = hotel.get("hotel_id")
        if hotel_id is None:
            continue
        try:
            policy_response = Get_Policies_of_the_hotel(hotel_id)
        except Exception:
            continue
        if policy_indicates_flexible_cancellation(policy_response):
            flexible_hotels += 1

    proportion = flexible_hotels / total_hotels
    return proportion, flexible_hotels, total_hotels


def get_target_location(target_area):
    locations = Search_locations(target_area)
    location = find_location_match(locations, target_area)
    if not location:
        return None
    return location


def search_hotels_for_location(location):
    if not isinstance(location, dict):
        return []
    dest_id = location.get("dest_id")
    dest_type = location.get("dest_type")
    if dest_id is None or dest_type is None:
        return []
    search_response = Search_hotels(
        CHECKIN_DATE,
        CHECKOUT_DATE,
        dest_type,
        dest_id,
        ORDER_BY,
        ROOM_NUMBER,
        FILTER_BY_CURRENCY,
    )
    return extract_hotels(search_response)


def main():
    location = get_target_location(TARGET_AREA)
    if not location:
        print(f"No matching location found for {TARGET_AREA}.")
        return

    hotels = search_hotels_for_location(location)
    proportion, flexible_hotels, total_hotels = compute_flexible_cancellation_proportion(hotels)

    if proportion is None:
        print(f"No hotels found in {TARGET_AREA}.")
        return

    percentage = proportion * 100
    print(f"Location: {location.get('name', TARGET_AREA)}")
    print(f"Hotels checked: {total_hotels}")
    print(f"Hotels with flexible cancellation: {flexible_hotels}")
    print(f"Proportion with flexible cancellation: {proportion:.2f} ({percentage:.1f}%)")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Booking_com.Search_locations import Search_locations
from Tools.Booking_com.Search_hotels import Search_hotels
from Tools.Booking_com.Get_Policies_of_the_hotel import Get_Policies_of_the_hotel
from Tools.Booking_com.Search_hotels import Search_hotels

import traceback
from datetime import date, timedelta

# Module-level pinned constants
LOCATION_QUERY = "Ditmars Steinway"
LOCALE = "en-us"
UNITS = "metric"
ADULTS_NUMBER = 2
ROOM_NUMBER = 1
FILTER_BY_CURRENCY = "USD"
ORDER_BY = "popularity"
FLEXIBLE_TERMS = [
    "free cancellation",
    "flexible cancellation",
    "cancellable",
    "cancel free",
    "no cancellation fee",
]
CHECKIN_DATE = (date.today() + timedelta(days=1)).isoformat()
CHECKOUT_DATE = (date.today() + timedelta(days=2)).isoformat()


def find_best_location(location_results):
    if not isinstance(location_results, list):
        return None

    best_match = None
    best_score = -1

    for item in location_results:
        if not isinstance(item, dict):
            continue

        name = str(item.get("name", ""))
        label = str(item.get("label", ""))
        dest_type = item.get("dest_type")
        dest_id = item.get("dest_id")

        combined = f"{name} {label}".lower()
        score = 0

        if "ditmars" in combined:
            score += 2
        if "steinway" in combined:
            score += 2
        if "district" in str(dest_type).lower():
            score += 1
        if dest_id is not None:
            score += 1

        if score > best_score:
            best_score = score
            best_match = item

    return best_match


def search_location_destination():
    location_results = Search_locations(LOCATION_QUERY)
    best_match = find_best_location(location_results)

    if not best_match:
        return None, None

    return best_match.get("dest_id"), best_match.get("dest_type")


def search_hotels_in_destination(dest_id, dest_type):
    if dest_id is None or dest_type is None:
        return {}

    return Search_hotels(
        CHECKIN_DATE,
        CHECKOUT_DATE,
        dest_type,
        dest_id,
        ORDER_BY,
        ROOM_NUMBER,
        FILTER_BY_CURRENCY,
    )


def get_hotel_identifier(hotel):
    if not isinstance(hotel, dict):
        return None
    return hotel.get("hotel_id")


def policy_text_mentions_flexible_cancellation(text):
    lowered = str(text).lower()
    return any(term in lowered for term in FLEXIBLE_TERMS)


def evaluate_policy_for_flexible_cancellation(policy_details):
    if not isinstance(policy_details, dict):
        return False

    policy = policy_details.get("policy", [])
    if not isinstance(policy, list):
        return False

    for policy_item in policy:
        if not isinstance(policy_item, dict):
            continue

        content_list = policy_item.get("content", [])
        if not isinstance(content_list, list):
            continue

        for content_item in content_list:
            if not isinstance(content_item, dict):
                continue

            # Grounded from schema: content -> ruleset -> rule -> content
            ruleset_list = content_item.get("ruleset", [])
            if isinstance(ruleset_list, list):
                for ruleset_item in ruleset_list:
                    if not isinstance(ruleset_item, dict):
                        continue
                    rule_list = ruleset_item.get("rule", [])
                    if not isinstance(rule_list, list):
                        continue
                    for rule_item in rule_list:
                        if not isinstance(rule_item, dict):
                            continue
                        rule_content = rule_item.get("content", "")
                        if policy_text_mentions_flexible_cancellation(rule_content):
                            return True

            # Also inspect any direct textual fields present in schema
            for key in ("name", "type"):
                if policy_text_mentions_flexible_cancellation(content_item.get(key, "")):
                    return True

            for key in ("children_at_the_property", "cribs_and_extra_beds"):
                nested = content_item.get(key, [])
                if isinstance(nested, list):
                    for nested_item in nested:
                        if not isinstance(nested_item, dict):
                            continue
                        if policy_text_mentions_flexible_cancellation(nested_item.get("text", "")):
                            return True

    return False


def analyze_hotels_for_flexible_cancellation(hotel_results):
    hotels = []
    if isinstance(hotel_results, dict):
        hotels = hotel_results.get("result", [])
    elif isinstance(hotel_results, list):
        hotels = hotel_results

    if not isinstance(hotels, list):
        hotels = []

    total_hotels = len(hotels)
    flexible_count = 0
    checked_count = 0

    for hotel in hotels:
        hotel_id = get_hotel_identifier(hotel)
        if hotel_id is None:
            continue

        checked_count += 1
        try:
            policy_details = Get_Policies_of_the_hotel(hotel_id)
            if evaluate_policy_for_flexible_cancellation(policy_details):
                flexible_count += 1
        except Exception:
            continue

    return flexible_count, total_hotels, checked_count


def calculate_proportion(flexible_count, total_hotels):
    if total_hotels <= 0:
        return 0.0
    return flexible_count / total_hotels


def format_percentage(proportion):
    return f"{proportion:.2%}"


def build_result_message(location_name, flexible_count, total_hotels, proportion, checked_count):
    return (
        f"Location: {location_name}\n"
        f"Hotels evaluated: {checked_count}/{total_hotels}\n"
        f"Hotels with flexible cancellation: {flexible_count}\n"
        f"Proportion with flexible cancellation: {proportion:.4f} ({format_percentage(proportion)})"
    )


def main():
    dest_id, dest_type = search_location_destination()
    hotel_results = search_hotels_in_destination(dest_id, dest_type)
    flexible_count, total_hotels, checked_count = analyze_hotels_for_flexible_cancellation(hotel_results)
    proportion = calculate_proportion(flexible_count, total_hotels)
    message = build_result_message(LOCATION_QUERY, flexible_count, total_hotels, proportion, checked_count)
    print(message)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
