from Tools.Booking_com.Search_locations import Search_locations
from Tools.Booking_com.Get_Policies_of_the_hotel import Get_Policies_of_the_hotel
from Tools.Booking_com.Search_hotels import Search_hotels

import traceback

# Module-level pinned constants
LOCATION_QUERY = "Co-op City"
LOCALE = "en-us"
CHECKIN_DATE = "2026-06-13"
CHECKOUT_DATE = "2026-06-14"
ADULTS_NUMBER = 2
UNITS = "metric"
ORDER_BY = "popularity"
ROOM_NUMBER = 1
FILTER_BY_CURRENCY = "USD"
MAX_HOTELS_TO_CHECK = 10

def find_best_location(locations, query):
    if not isinstance(locations, list):
        return None
    query_l = str(query).lower()
    for loc in locations:
        if not isinstance(loc, dict):
            continue
        name = str(loc.get("name", "")).lower()
        label = str(loc.get("label", "")).lower()
        if query_l in name or query_l in label:
            return loc
    return locations[0] if locations else None

def extract_hotels(search_response):
    if not isinstance(search_response, dict):
        return []
    result = search_response.get("result", [])
    if isinstance(result, list):
        return result
    return []

def hotel_is_flexible_cancellable(hotel):
    if not isinstance(hotel, dict):
        return False

    if hotel.get("is_free_cancellable"):
        return True

    if hotel.get("free_cancellation"):
        return True

    hotel_id = hotel.get("hotel_id")
    if hotel_id is None:
        return False

    try:
        policies = Get_Policies_of_the_hotel(hotel_id)
    except Exception:
        return False

    if not isinstance(policies, dict):
        return False

    policy_groups = policies.get("policy", [])
    if not isinstance(policy_groups, list):
        return False

    for policy_group in policy_groups:
        if not isinstance(policy_group, dict):
            continue
        content_list = policy_group.get("content", [])
        if not isinstance(content_list, list):
            continue
        for content in content_list:
            if not isinstance(content, dict):
                continue
            rulesets = content.get("ruleset", [])
            if not isinstance(rulesets, list):
                continue
            for ruleset in rulesets:
                if not isinstance(ruleset, dict):
                    continue
                rules = ruleset.get("rule", [])
                if not isinstance(rules, list):
                    continue
                for rule in rules:
                    if not isinstance(rule, dict):
                        continue
                    text = str(rule.get("content", "")).lower()
                    if "cancellation" in text and ("flex" in text or "free" in text or "allowed" in text):
                        return True
    return False

def compute_flexible_cancellation_proportion(hotels):
    if not hotels:
        return 0.0, 0, 0

    checked_hotels = hotels[:MAX_HOTELS_TO_CHECK]
    total_hotels = len(checked_hotels)
    flexible_count = 0

    for hotel in checked_hotels:
        if hotel_is_flexible_cancellable(hotel):
            flexible_count += 1

    proportion = flexible_count / total_hotels if total_hotels else 0.0
    return proportion, flexible_count, total_hotels

def search_co_op_city_hotels():
    locations = Search_locations(LOCATION_QUERY)
    best_location = find_best_location(locations, LOCATION_QUERY)
    if not best_location:
        return []

    dest_type = best_location.get("dest_type")
    dest_id = best_location.get("dest_id")
    if dest_type is None or dest_id is None:
        return []

    search_response = Search_hotels(
        CHECKIN_DATE,
        CHECKOUT_DATE,
        dest_type,
        dest_id,
        ORDER_BY,
        ROOM_NUMBER,
        FILTER_BY_CURRENCY
    )
    return extract_hotels(search_response)

def format_output(proportion, flexible_count, total_hotels):
    percentage = proportion * 100
    print(f"Hotels checked: {total_hotels}")
    print(f"Hotels with flexible cancellation: {flexible_count}")
    print(f"Proportion of hotels with flexible cancellation policy in Co-op City: {proportion:.2f} ({percentage:.1f}%)")

def main():
    hotels = search_co_op_city_hotels()
    proportion, flexible_count, total_hotels = compute_flexible_cancellation_proportion(hotels)
    format_output(proportion, flexible_count, total_hotels)

if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Booking_com.Search_locations import Search_locations
from Tools.Booking_com.Search_hotels import Search_hotels
from Tools.Booking_com.Get_Hotel_data import Get_Hotel_data

import traceback
from datetime import datetime, timedelta

EASTCHESTER_QUERY = "Eastchester"
LOCALE = "en-us"
ADULTS_NUMBER = 2
UNITS = "metric"
ROOM_NUMBER = 1
FILTER_BY_CURRENCY = "USD"
ORDER_BY = "price"
TARGET_PROPERTY_TYPE_HINTS = ("entire home", "entire apartment", "apartment", "home", "apt", "entire home/apt")


def safe_get(data, *keys, default=None):
    current = data
    for key in keys:
        if not isinstance(current, dict) or key not in current:
            return default
        current = current[key]
    return current


def get_future_dates(days_ahead=30, stay_length=1):
    today = datetime.now().date()
    checkin = today + timedelta(days=days_ahead)
    checkout = checkin + timedelta(days=stay_length)
    return checkin.isoformat(), checkout.isoformat()


def search_destination(location_name):
    return Search_locations(location_name)


def pick_best_location(location_results, query):
    if not isinstance(location_results, list) or not location_results:
        return None

    query_lower = query.lower()
    exact_label_match = None
    exact_name_match = None
    fallback = None

    for item in location_results:
        if not isinstance(item, dict):
            continue
        name = str(safe_get(item, "name", default="")).lower()
        label = str(safe_get(item, "label", default="")).lower()
        dest_type = safe_get(item, "dest_type", default="")
        if fallback is None and safe_get(item, "dest_id") is not None and dest_type is not None:
            fallback = item
        if query_lower == name or query_lower == label:
            exact_name_match = exact_name_match or item
        if query_lower in label or query_lower in name:
            exact_label_match = exact_label_match or item

    return exact_name_match or exact_label_match or fallback


def search_hotels_in_location(location_details):
    if not isinstance(location_details, dict):
        return {}
    dest_type = safe_get(location_details, "dest_type")
    dest_id = safe_get(location_details, "dest_id")
    if dest_type is None or dest_id is None:
        return {}
    checkin_date, checkout_date = get_future_dates()
    return Search_hotels(
        checkin_date=checkin_date,
        checkout_date=checkout_date,
        dest_type=dest_type,
        dest_id=dest_id,
        order_by=ORDER_BY,
        room_number=ROOM_NUMBER,
        filter_by_currency=FILTER_BY_CURRENCY,
    )


def is_entire_home_apt(listing):
    if not isinstance(listing, dict):
        return False

    accommodation_type_name = str(safe_get(listing, "accommodation_type_name", default="")).lower()
    hotel_name = str(safe_get(listing, "hotel_name", default="")).lower()
    type_value = str(safe_get(listing, "type", default="")).lower()
    booking_home_is_vacation = safe_get(listing, "booking_home", "is_vacation_rental", default=0)

    combined = " ".join([accommodation_type_name, hotel_name, type_value])

    if booking_home_is_vacation:
        return True

    return any(hint in combined for hint in TARGET_PROPERTY_TYPE_HINTS)


def filter_entire_home_apt_listings(hotel_listings):
    results = safe_get(hotel_listings, "result", default=[])
    if not isinstance(results, list):
        return []
    return [listing for listing in results if is_entire_home_apt(listing)]


def extract_nightly_price_from_listing(listing):
    if not isinstance(listing, dict):
        return None

    composite = safe_get(listing, "composite_price_breakdown", default={})
    if isinstance(composite, dict):
        nightly = safe_get(composite, "gross_amount_per_night", "value")
        if nightly is not None:
            return nightly
        nightly = safe_get(composite, "gross_amount", "value")
        if nightly is not None:
            total = nightly
            try:
                total_float = float(total)
                return total_float
            except Exception:
                return total

    min_total_price = safe_get(listing, "min_total_price")
    if min_total_price is not None:
        try:
            return float(min_total_price)
        except Exception:
            return min_total_price

    return None


def select_most_expensive_listing(listings):
    highest_price = None
    selected_listing = None

    for listing in listings:
        price = extract_nightly_price_from_listing(listing)
        if price is None:
            continue
        try:
            numeric_price = float(price)
        except Exception:
            continue

        if highest_price is None or numeric_price > highest_price:
            highest_price = numeric_price
            selected_listing = listing

    return selected_listing, highest_price


def format_price(price, currency=FILTER_BY_CURRENCY):
    if price is None:
        return "Price unavailable"
    try:
        if float(price).is_integer():
            price_text = f"{int(float(price))}"
        else:
            price_text = f"{float(price):.2f}"
    except Exception:
        price_text = str(price)
    return f"{price_text} {currency} per night"


def main():
    location_results = search_destination(EASTCHESTER_QUERY)
    best_location = pick_best_location(location_results, EASTCHESTER_QUERY)

    if not best_location:
        print("No matching Eastchester location found.")
        return

    hotels = search_hotels_in_location(best_location)
    entire_home_apt_listings = filter_entire_home_apt_listings(hotels)

    if not entire_home_apt_listings:
        print("No entire home/apt listings were found for Eastchester.")
        return

    most_expensive_listing, highest_price = select_most_expensive_listing(entire_home_apt_listings)

    if most_expensive_listing is None:
        print("Could not determine a price for the available entire home/apt listings in Eastchester.")
        return

    hotel_name = safe_get(most_expensive_listing, "hotel_name", default="Unknown property")
    print(f"Most expensive entire home/apt in Eastchester: {hotel_name}")
    print(f"Cost per night: {format_price(highest_price)}")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Booking_com.Search_locations import Search_locations
from Tools.Booking_com.Search_hotels import Search_hotels
from Tools.Booking_com.Search_hotels import Search_hotels

import traceback
from datetime import date, timedelta

Kew_Gardens = "Kew Gardens"
LOCALE = "en-us"
ADULTS_NUMBER = 2
UNITS = "metric"
ROOM_NUMBER = 1
FILTER_BY_CURRENCY = "USD"
ORDER_BY = "price"
TARGET_PROPERTY_TYPE = "entire home/apt"

# Hardcoded dates: must be present/future; choose a safe future range.
CHECKIN_DATE = (date.today() + timedelta(days=30)).isoformat()
CHECKOUT_DATE = (date.today() + timedelta(days=31)).isoformat()


def get_locations(query_name):
    try:
        locations = Search_locations(query_name)
        if not isinstance(locations, list):
            return []
        return locations
    except Exception:
        return []


def choose_kew_gardens_location(location_results):
    if not location_results:
        return None

    # Use schema-grounded keys: name, label, dest_type, dest_id
    preferred = None
    for item in location_results:
        if not isinstance(item, dict):
            continue
        name = str(item.get("name", ""))
        label = str(item.get("label", ""))
        dest_type = str(item.get("dest_type", ""))
        if "Kew Gardens" in name or "Kew Gardens" in label or "district" in dest_type.lower():
            preferred = item
            break

    return preferred if preferred is not None else location_results[0]


def get_hotels_for_location(location):
    if not isinstance(location, dict):
        return {}

    dest_type = location.get("dest_type")
    dest_id = location.get("dest_id")

    if dest_type is None or dest_id is None:
        return {}

    try:
        hotels = Search_hotels(
            CHECKIN_DATE,
            CHECKOUT_DATE,
            dest_type,
            dest_id,
            ORDER_BY,
            ROOM_NUMBER,
            FILTER_BY_CURRENCY,
        )
        if not isinstance(hotels, dict):
            return {}
        return hotels
    except Exception:
        return {}


def extract_results(hotels_response):
    if not isinstance(hotels_response, dict):
        return []
    results = hotels_response.get("result", [])
    if not isinstance(results, list):
        return []
    return results


def is_entire_home_apt(listing):
    if not isinstance(listing, dict):
        return False

    candidates = [
        listing.get("accommodation_type_name"),
        listing.get("room_type"),
        listing.get("property_type"),
        listing.get("type"),
    ]
    combined = " | ".join(str(x).lower() for x in candidates if x is not None)
    return "entire home/apt" in combined or "entire home" in combined or "apt" in combined


def nightly_price_from_listing(listing):
    if not isinstance(listing, dict):
        return None

    cpb = listing.get("composite_price_breakdown", {})
    if isinstance(cpb, dict):
        nightly = cpb.get("gross_amount_per_night")
        if isinstance(nightly, dict) and nightly.get("value") is not None:
            return nightly.get("value")

        all_inclusive = cpb.get("all_inclusive_amount")
        if isinstance(all_inclusive, dict) and all_inclusive.get("value") is not None:
            return all_inclusive.get("value")

    # Fallbacks from top-level fields
    for key in ("min_total_price",):
        if listing.get(key) is not None:
            return listing.get(key)

    return None


def select_most_expensive_entire_home_apt(listings):
    filtered = [item for item in listings if is_entire_home_apt(item)]

    if not filtered:
        return None

    def price_key(item):
        price = nightly_price_from_listing(item)
        try:
            return float(price)
        except Exception:
            return float("-inf")

    return max(filtered, key=price_key)


def format_price_output(location, listing, price):
    location_label = "Kew Gardens"
    if isinstance(location, dict):
        location_label = location.get("label") or location.get("name") or location_label

    if listing is None:
        return f"No entire home/apt listings were found for {location_label}."

    hotel_name = listing.get("hotel_name") or listing.get("hotel_name_trans") or "Unknown listing"
    currency = None
    cpb = listing.get("composite_price_breakdown", {})
    if isinstance(cpb, dict):
        nightly = cpb.get("gross_amount_per_night", {})
        if isinstance(nightly, dict):
            currency = nightly.get("currency")
        if currency is None:
            all_inclusive = cpb.get("all_inclusive_amount", {})
            if isinstance(all_inclusive, dict):
                currency = all_inclusive.get("currency")

    if price is None:
        return f"The most expensive entire home/apt in {location_label} is {hotel_name}, but the nightly price could not be determined."

    if currency:
        return f"The most expensive entire home/apt in {location_label} costs {price} {currency} per night."
    return f"The most expensive entire home/apt in {location_label} costs {price} per night."


def main():
    locations = get_locations(Kew_Gardens)
    selected_location = choose_kew_gardens_location(locations)
    hotels_response = get_hotels_for_location(selected_location)
    listings = extract_results(hotels_response)
    most_expensive = select_most_expensive_entire_home_apt(listings)
    nightly_price = nightly_price_from_listing(most_expensive)
    return format_price_output(selected_location, most_expensive, nightly_price)


if __name__ == "__main__":
    try:
        print(main())
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Booking_com.Search_locations import Search_locations
from Tools.Booking_com.Search_hotels import Search_hotels
from Tools.Booking_com.Get_Hotel_data import Get_Hotel_data

import traceback

LOCATION_QUERY = "Emerson Hill"
DEST_TYPE_KEY = "dest_type"
DEST_ID_KEY = "dest_id"
HOTEL_ID_KEY = "hotel_id"
SEARCH_ORDER_BY = "price"
ROOM_NUMBER = 1
FILTER_BY_CURRENCY = "USD"
CHECKIN_DATE = "2026-06-15"
CHECKOUT_DATE = "2026-06-16"
TARGET_ACCOMMODATION_TYPE_NAME = "Apartment"
TARGET_ACCOMMODATION_TYPE_ID = 201
TARGET_NAME_LOWER = "emerson hill"


def safe_get(obj, path, default=None):
    cur = obj
    for key in path:
        if isinstance(cur, dict):
            cur = cur.get(key, default)
        else:
            return default
    return cur


def find_location_identifier(location_query):
    results = Search_locations(location_query)
    return results if isinstance(results, list) else []


def pick_destination(location_results):
    mapping = {
        "dest_type": DEST_TYPE_KEY,
        "dest_id": DEST_ID_KEY,
    }
    best = None
    for item in location_results:
        name = str(item.get("name", "")).lower()
        label = str(item.get("label", "")).lower()
        if TARGET_NAME_LOWER in name or TARGET_NAME_LOWER in label:
            best = item
            break
    if best is None and location_results:
        best = location_results[0]
    if not best:
        return None, None
    return best.get(mapping["dest_type"]), best.get(mapping["dest_id"])


def search_accommodations(dest_type, dest_id):
    if dest_type is None or dest_id is None:
        return {}
    return Search_hotels(
        CHECKIN_DATE,
        CHECKOUT_DATE,
        dest_type,
        dest_id,
        SEARCH_ORDER_BY,
        ROOM_NUMBER,
        FILTER_BY_CURRENCY,
    )


def is_entire_home_or_apt(item):
    accommodation_name = str(item.get("accommodation_type_name", "")).lower()
    hotel_name = str(item.get("hotel_name", "")).lower()
    hotel_name_trans = str(item.get("hotel_name_trans", "")).lower()
    booking_home = item.get("booking_home")
    is_vacation_rental = item.get("is_vacation_rental", 0)

    if "apartment" in accommodation_name or "vacation rental" in accommodation_name:
        return True
    if "apt" in hotel_name or "apartment" in hotel_name or "home" in hotel_name:
        return True
    if "apt" in hotel_name_trans or "apartment" in hotel_name_trans or "home" in hotel_name_trans:
        return True
    if isinstance(booking_home, dict):
        if booking_home.get("is_vacation_rental") == 1 or booking_home.get("is_single_unit_property") == 1:
            return True
    return bool(is_vacation_rental == 1)


def extract_nightly_price(item):
    composite = item.get("composite_price_breakdown", {})
    gross_nightly = safe_get(composite, ["gross_amount_per_night", "value"])
    if gross_nightly is not None:
        return gross_nightly
    all_inclusive = safe_get(composite, ["all_inclusive_amount", "value"])
    if all_inclusive is not None:
        return all_inclusive
    min_total_price = item.get("min_total_price")
    if min_total_price is not None:
        return min_total_price
    return None


def select_most_expensive_entire_home_or_apartment(accommodations_results):
    results = accommodations_results.get("result", [])
    filtered = [item for item in results if is_entire_home_or_apt(item)]
    if not filtered:
        filtered = results

    best_item = None
    best_price = None
    for item in filtered:
        price = extract_nightly_price(item)
        if price is None:
            continue
        if best_price is None or price > best_price:
            best_price = price
            best_item = item

    return best_item


def get_hotel_data(listing_identifier):
    if listing_identifier is None:
        return {}
    hotel_id = listing_identifier.get(HOTEL_ID_KEY)
    if hotel_id is None:
        hotel_id = listing_identifier.get("id")
    if hotel_id is None:
        return {}
    return Get_Hotel_data(hotel_id)


def format_price_output(price, currency=None, hotel_name=None):
    if price is None:
        return "No nightly price data was available for the selected property."
    parts = []
    if hotel_name:
        parts.append(f"Property: {hotel_name}")
    if currency:
        parts.append(f"Currency: {currency}")
    parts.append(f"Nightly price: {price}")
    return "\n".join(parts)


def main():
    location_results = find_location_identifier(LOCATION_QUERY)
    dest_type, dest_id = pick_destination(location_results)

    accommodations_results = search_accommodations(dest_type, dest_id)
    selected_listing = select_most_expensive_entire_home_or_apartment(accommodations_results)

    if selected_listing is None:
        print("No matching entire home/apt listing was found in Emerson Hill.")
        return

    hotel_data = get_hotel_data(selected_listing)
    nightly_price = extract_nightly_price(selected_listing)
    currency = selected_listing.get("currency_code") or selected_listing.get("currencycode")
    hotel_name = selected_listing.get("hotel_name") or selected_listing.get("hotel_name_trans") or hotel_data.get("name")

    if nightly_price is None and isinstance(hotel_data, dict):
        nightly_price = safe_get(hotel_data, ["composite_price_breakdown", "gross_amount_per_night", "value"])
        if currency is None:
            currency = hotel_data.get("currencycode")

    print(format_price_output(nightly_price, currency, hotel_name))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Booking_com.Search_locations import Search_locations
from Tools.Booking_com.Get_Hotel_data import Get_Hotel_data
from Tools.Booking_com.Get_Review_scores_of_the_hotel import Get_Review_scores_of_the_hotel

import os
import traceback

# Module-level pinned constants
AREA_NAME = "Financial District"
REVIEW_THRESHOLD = 4.0
LOCALE = "en-us"


def search_hotels_in_area(area_name):
    try:
        results = Search_locations(area_name)
        return results if isinstance(results, list) else []
    except Exception:
        raise


def extract_hotel_candidates(location_results):
    candidates = []
    for item in location_results or []:
        if not isinstance(item, dict):
            continue
        dest_type = item.get("dest_type")
        hotels = item.get("hotels")
        dest_id = item.get("dest_id")
        if isinstance(hotels, int) and hotels > 0 and dest_id is not None:
            candidates.append(item)
        elif isinstance(dest_type, str) and "district" in dest_type.lower() and dest_id is not None:
            candidates.append(item)
    return candidates


def get_hotel_details_for_candidates(candidate_hotels):
    hotel_details_list = []
    for hotel in candidate_hotels:
        hotel_id = hotel.get("dest_id")
        if hotel_id is None:
            continue
        try:
            details = Get_Hotel_data(hotel_id)
            if isinstance(details, dict):
                hotel_details_list.append(details)
        except Exception:
            continue
    return hotel_details_list


def extract_review_score(hotel_review_data):
    if not isinstance(hotel_review_data, dict):
        return None

    # Schema grounded keys: score_breakdown, score_distribution, score_percentage
    score_percentage = hotel_review_data.get("score_percentage", [])
    if isinstance(score_percentage, list):
        for item in score_percentage:
            if not isinstance(item, dict):
                continue
            score_word = item.get("score_word")
            percent = item.get("percent")
            count = item.get("count")
            if score_word is not None or percent is not None or count is not None:
                # Prefer average/overall score if present in the response? Not in schema.
                # Use count-weighted interpretation not possible here, so prefer strongest numeric evidence.
                pass

    score_breakdown = hotel_review_data.get("score_breakdown", [])
    if isinstance(score_breakdown, list):
        for breakdown in score_breakdown:
            if not isinstance(breakdown, dict):
                continue
            questions = breakdown.get("question", [])
            if isinstance(questions, list):
                for q in questions:
                    if not isinstance(q, dict):
                        continue
                    localized_question = str(q.get("localized_question", "")).lower()
                    if "overall" in localized_question or "review score" in localized_question:
                        score = q.get("score")
                        try:
                            return float(score)
                        except Exception:
                            continue

    score_distribution = hotel_review_data.get("score_distribution", [])
    if isinstance(score_distribution, list) and score_distribution:
        total = 0
        weighted = 0.0
        for item in score_distribution:
            if not isinstance(item, dict):
                continue
            score = item.get("score")
            count = item.get("count")
            try:
                score_num = float(score)
                count_num = int(count)
                weighted += score_num * count_num
                total += count_num
            except Exception:
                continue
        if total > 0:
            return weighted / total

    return None


def filter_hotels_by_review_rate(hotel_details_list, threshold):
    qualifying_hotels = []
    for hotel_data in hotel_details_list:
        hotel_id = hotel_data.get("hotel_id")
        if hotel_id is None:
            continue
        try:
            review_data = Get_Review_scores_of_the_hotel(hotel_id)
            score = extract_review_score(review_data)
            if score is not None and score > threshold:
                qualifying_hotels.append(hotel_data)
        except Exception:
            continue
    return qualifying_hotels


def count_hotels(hotel_list):
    return len(hotel_list or [])


def main():
    location_results = search_hotels_in_area(AREA_NAME)
    candidates = extract_hotel_candidates(location_results)
    hotel_details_list = get_hotel_details_for_candidates(candidates)
    qualifying_hotels = filter_hotels_by_review_rate(hotel_details_list, REVIEW_THRESHOLD)
    result = count_hotels(qualifying_hotels)
    print(result)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

