from Tools.Booking_com.Search_locations import Search_locations
from Tools.Booking_com.Search_hotels import Search_hotels
from Tools.Booking_com.Get_Hotel_data import Get_Hotel_data

import traceback

# Module-level constants pinned from user requirement and API schema
DESTINATION_NAME = "Springfield Gardens"
REVIEW_THRESHOLD = 4
LOCALE = "en-us"
ADULTS_NUMBER = 2
UNITS = "metric"
ROOM_NUMBER = 1
FILTER_BY_CURRENCY = "USD"
ORDER_BY = "popularity"
CHECKIN_DATE = "2026-06-13"
CHECKOUT_DATE = "2026-06-14"


def find_matching_location(location_results, destination_name):
    """
    Select the best matching location result using schema keys from Search_locations.
    Expected keys used: 'name', 'dest_type', 'dest_id', 'hotels', 'nr_hotels', 'label'
    """
    if not isinstance(location_results, list):
        return None

    normalized_target = destination_name.strip().lower()
    for item in location_results:
        if not isinstance(item, dict):
            continue
        name = str(item.get("name", "")).strip().lower()
        label = str(item.get("label", "")).strip().lower()
        if normalized_target in name or normalized_target in label:
            return item

    return location_results[0] if location_results else None


def search_destination(destination_name):
    try:
        location_results = Search_locations(destination_name)
    except Exception:
        raise

    selected_location = find_matching_location(location_results, destination_name)
    return selected_location


def retrieve_hotels(location_details):
    if not isinstance(location_details, dict):
        return {}

    dest_type = location_details.get("dest_type")
    dest_id = location_details.get("dest_id")

    if dest_type is None or dest_id is None:
        return {}

    try:
        hotel_results = Search_hotels(
            CHECKIN_DATE,
            CHECKOUT_DATE,
            dest_type,
            dest_id,
            ORDER_BY,
            ROOM_NUMBER,
            FILTER_BY_CURRENCY,
        )
        return hotel_results if isinstance(hotel_results, dict) else {}
    except Exception:
        raise


def extract_hotel_items(hotel_results):
    """
    From Search_hotels response schema, the hotel list lives under key:
    'result'
    """
    if not isinstance(hotel_results, dict):
        return []
    result = hotel_results.get("result", [])
    return result if isinstance(result, list) else []


def extract_review_score_from_hotel_data(hotel_data):
    """
    From Get_Hotel_data response schema, review score key:
    'review_score'
    """
    if not isinstance(hotel_data, dict):
        return None

    score = hotel_data.get("review_score")
    try:
        if score is None:
            return None
        return float(score)
    except (TypeError, ValueError):
        return None


def get_hotel_review_rate(hotel_item):
    """
    Get review score for a hotel item.
    Prefer using Search_hotels result field 'hotel_id' per schema.
    """
    if not isinstance(hotel_item, dict):
        return None

    hotel_id = hotel_item.get("hotel_id")
    if hotel_id is None:
        return None

    try:
        hotel_data = Get_Hotel_data(hotel_id)
    except Exception:
        raise

    return extract_review_score_from_hotel_data(hotel_data)


def count_hotels_above_threshold(hotel_list, threshold_value):
    count = 0
    for hotel_item in hotel_list:
        review_rate = get_hotel_review_rate(hotel_item)
        if review_rate is not None and review_rate > threshold_value:
            count += 1
    return count


def main():
    location_details = search_destination(DESTINATION_NAME)
    if not location_details:
        print(f"No matching destination found for {DESTINATION_NAME}.")
        return

    hotel_results = retrieve_hotels(location_details)
    hotel_list = extract_hotel_items(hotel_results)

    result_count = count_hotels_above_threshold(hotel_list, REVIEW_THRESHOLD)
    print(
        f"Hotels in {DESTINATION_NAME} with review score higher than {REVIEW_THRESHOLD}: {result_count}"
    )


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

