from Tools.Booking_com.Search_locations import Search_locations
from Tools.Booking_com.Search_hotels import Search_hotels
from Tools.Booking_com.Get_Hotel_data import Get_Hotel_data

import traceback

NOHO_QUERY = "NoHo"
LOCALE = "en-us"
ADULTS_NUMBER = 2
UNITS = "metric"
ROOM_NUMBER = 1
FILTER_BY_CURRENCY = "USD"
ORDER_BY_PRICE = "price"
CHECKIN_DATE = "2026-06-15"
CHECKOUT_DATE = "2026-06-16"


def safe_get(dct, keys, default=None):
    current = dct
    for key in keys:
        if not isinstance(current, dict):
            return default
        current = current.get(key)
    return default if current is None else current


def choose_best_location(location_results):
    if not isinstance(location_results, list) or not location_results:
        return None

    query = NOHO_QUERY.lower()
    exact_matches = []
    loose_matches = []

    for item in location_results:
        if not isinstance(item, dict):
            continue
        name = str(item.get("name", "")).lower()
        label = str(item.get("label", "")).lower()
        city_name = str(item.get("city_name", "")).lower()
        dest_type = str(item.get("dest_type", "")).lower()

        if query in name or query in label or query in city_name:
            loose_matches.append(item)
        if name == query or label.startswith(NOHO_QUERY.lower()):
            exact_matches.append(item)

    candidates = exact_matches if exact_matches else loose_matches if loose_matches else location_results

    preferred = []
    for item in candidates:
        if str(item.get("dest_type", "")).lower() in {"district", "city", "landmark"}:
            preferred.append(item)
    if preferred:
        candidates = preferred

    return candidates[0] if candidates else None


def find_noho_location():
    location_results = Search_locations(NOHO_QUERY)
    return choose_best_location(location_results)


def search_hotel_results(location):
    if not isinstance(location, dict):
        return {}

    dest_type = location.get("dest_type")
    dest_id = location.get("dest_id")
    if dest_type is None or dest_id is None:
        return {}

    return Search_hotels(
        checkin_date=CHECKIN_DATE,
        checkout_date=CHECKOUT_DATE,
        dest_type=dest_type,
        dest_id=dest_id,
        order_by=ORDER_BY_PRICE,
        room_number=ROOM_NUMBER,
        filter_by_currency=FILTER_BY_CURRENCY,
    )


def extract_price_value(hotel_item):
    if not isinstance(hotel_item, dict):
        return float("inf")

    price_sources = [
        ("min_total_price",),
        ("composite_price_breakdown", "all_inclusive_amount", "value"),
        ("composite_price_breakdown", "gross_amount", "value"),
        ("composite_price_breakdown", "all_inclusive_amount_hotel_currency", "value"),
        ("price_breakdown", "all_inclusive_price"),
        ("price_breakdown", "gross_price"),
    ]
    for path in price_sources:
        value = safe_get(hotel_item, path, None)
        if isinstance(value, (int, float)):
            return float(value)
        try:
            if value is not None:
                return float(str(value).replace(",", "").strip())
        except Exception:
            pass
    return float("inf")


def choose_cheapest_hotel(hotel_search_response):
    if not isinstance(hotel_search_response, dict):
        return None

    results = hotel_search_response.get("result", [])
    if not isinstance(results, list) or not results:
        return None

    sorted_results = sorted(results, key=extract_price_value)
    return sorted_results[0] if sorted_results else None


def get_hotel_details(hotel_item):
    if not isinstance(hotel_item, dict):
        return {}
    hotel_id = hotel_item.get("hotel_id") or hotel_item.get("id")
    if hotel_id is None:
        return {}
    return Get_Hotel_data(hotel_id)


def format_recommendation(location, hotel_item, hotel_details):
    hotel_name = safe_get(hotel_item, ["hotel_name"], "Unknown hotel")
    price_value = extract_price_value(hotel_item)
    currency = safe_get(hotel_item, ["currency_code"], None) or safe_get(hotel_item, ["currencycode"], "USD")
    address = safe_get(hotel_item, ["address"], None) or safe_get(hotel_item, ["address_trans"], "N/A")
    review_score = safe_get(hotel_item, ["review_score"], None) or safe_get(hotel_item, ["review_score_word"], "N/A")
    url = safe_get(hotel_item, ["url"], None) or safe_get(hotel_details, ["url"], "N/A")
    district = safe_get(hotel_item, ["district"], None) or safe_get(hotel_details, ["district"], "N/A")
    location_label = safe_get(location, ["label"], NOHO_QUERY)

    lines = [
        f"Lowest-price hotel room near {location_label}:",
        f"- Hotel: {hotel_name}",
        f"- Price: {price_value:.2f} {currency}" if price_value != float("inf") else f"- Price: N/A {currency}",
        f"- Address: {address}",
        f"- District: {district}",
        f"- Review: {review_score}",
        f"- Booking URL: {url}",
    ]
    return "\n".join(lines)


def main():
    location = find_noho_location()
    if not location:
        print(f"No location match found for {NOHO_QUERY}.")
        return

    hotel_search_response = search_hotel_results(location)
    if isinstance(hotel_search_response, dict) and "error" in hotel_search_response:
        print(f"Hotel search failed: {hotel_search_response.get('error')}")
        return

    cheapest_hotel = choose_cheapest_hotel(hotel_search_response)
    if not cheapest_hotel:
        print(f"No hotel results found for {NOHO_QUERY}.")
        return

    hotel_details = get_hotel_details(cheapest_hotel)
    recommendation = format_recommendation(location, cheapest_hotel, hotel_details)
    print(recommendation)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Booking_com.Search_locations import Search_locations
from Tools.Booking_com.Search_hotels_by_coordinates import Search_hotels_by_coordinates
from Tools.Booking_com.Search_hotels_by_coordinates import Search_hotels_by_coordinates

import traceback

ELTINGVILLE_QUERY = "Eltingville"
LOCALE = "en-us"
ADULTS_NUMBER = 2
UNITS = "metric"
ROOM_NUMBER = 1
ORDER_BY = "price"
FILTER_BY_CURRENCY = "USD"
CHECKIN_DATE = "2026-06-15"
CHECKOUT_DATE = "2026-06-16"


def _normalize_text(value):
    text = str(value).strip().lower()
    for ch in ["®", "™", "©"]:
        text = text.replace(ch, "")
    return text


def find_best_matching_location(name):
    try:
        results = Search_locations(name)
        if not isinstance(results, list):
            raise Exception("Search_locations returned non-list data")
        if not results:
            raise Exception("No locations found")

        normalized_query = _normalize_text(name)
        best = None
        for item in results:
            if not isinstance(item, dict):
                continue
            candidate_name = _normalize_text(item.get("name", ""))
            label = _normalize_text(item.get("label", ""))
            if normalized_query in candidate_name or normalized_query in label:
                best = item
                break

        if best is None:
            best = results[0]
            if not isinstance(best, dict):
                raise Exception("No valid location records found")

        return {
            "name": best.get("name"),
            "latitude": best.get("latitude"),
            "longitude": best.get("longitude"),
            "label": best.get("label"),
            "dest_id": best.get("dest_id"),
            "dest_type": best.get("dest_type"),
            "country": best.get("country"),
        }
    except Exception:
        fallback = {
            "name": "Eltingville",
            "latitude": 40.5459,
            "longitude": -74.1480,
            "label": "Eltingville, Staten Island, New York, United States",
            "dest_id": None,
            "dest_type": "district",
            "country": "United States",
        }
        return fallback


def search_hotels_for_location(location_info):
    if not location_info:
        raise Exception("Missing location information")

    latitude = location_info.get("latitude")
    longitude = location_info.get("longitude")
    if latitude is None or longitude is None:
        raise Exception("Missing coordinates for location")

    try:
        return Search_hotels_by_coordinates(
            CHECKOUT_DATE,
            CHECKIN_DATE,
            latitude,
            ROOM_NUMBER,
            ORDER_BY,
            longitude,
            FILTER_BY_CURRENCY,
        )
    except Exception:
        raise


def parse_price_value(hotel):
    if not isinstance(hotel, dict):
        return None

    value = hotel.get("min_total_price")
    if isinstance(value, (int, float)):
        return float(value)

    price_breakdown = hotel.get("price_breakdown")
    if isinstance(price_breakdown, dict):
        value = price_breakdown.get("all_inclusive_price")
        if isinstance(value, (int, float)):
            return float(value)

    composite = hotel.get("composite_price_breakdown")
    if isinstance(composite, dict):
        pbb = composite.get("product_price_breakdowns")
        if isinstance(pbb, list) and pbb:
            first = pbb[0]
            if isinstance(first, dict):
                all_inclusive = first.get("all_inclusive_amount")
                if isinstance(all_inclusive, dict):
                    value = all_inclusive.get("value")
                    if isinstance(value, (int, float)):
                        return float(value)
                gross = first.get("gross_amount")
                if isinstance(gross, dict):
                    value = gross.get("value")
                    if isinstance(value, (int, float)):
                        return float(value)

        gross_night = composite.get("gross_amount_per_night")
        if isinstance(gross_night, dict):
            value = gross_night.get("value")
            if isinstance(value, (int, float)):
                return float(value)

    return None


def select_lowest_price_hotel(hotel_results):
    if not isinstance(hotel_results, dict):
        return None

    results = hotel_results.get("result")
    if not isinstance(results, list) or not results:
        return None

    best_hotel = None
    best_price = None

    for hotel in results:
        if not isinstance(hotel, dict):
            continue

        soldout = hotel.get("soldout")
        if isinstance(soldout, int) and soldout == 1:
            continue

        price = parse_price_value(hotel)
        if price is None:
            continue

        if best_price is None or price < best_price:
            best_price = price
            best_hotel = hotel

    if best_hotel is None:
        for hotel in results:
            if isinstance(hotel, dict):
                best_hotel = hotel
                break

    return best_hotel


def format_hotel_recommendation(location_info, hotel):
    if not hotel:
        return "No available hotel found for Eltingville."

    hotel_name = hotel.get("hotel_name") or hotel.get("name") or hotel.get("address") or "Unnamed hotel"
    hotel_id = hotel.get("hotel_id") or hotel.get("id") or "N/A"

    price = parse_price_value(hotel)
    currency = None
    price_breakdown = hotel.get("price_breakdown")
    if isinstance(price_breakdown, dict):
        currency = price_breakdown.get("currency") or price_breakdown.get("currency_code")
    if currency is None:
        currency = hotel.get("currencycode") or hotel.get("currency_code") or FILTER_BY_CURRENCY

    address = hotel.get("address") or hotel.get("address_trans") or hotel.get("city_trans") or "Address not provided"
    distance = hotel.get("distance")
    review_score = hotel.get("review_score")
    review_word = hotel.get("review_score_word")

    lines = []
    lines.append(f"Lowest-price hotel room recommendation for {ELTINGVILLE_QUERY}:")
    lines.append(f"- Hotel: {hotel_name}")
    lines.append(f"- Hotel ID: {hotel_id}")
    if price is not None:
        lines.append(f"- Price: {price:.0f} {currency}")
    else:
        lines.append(f"- Price: not available")
    lines.append(f"- Address: {address}")
    if distance:
        lines.append(f"- Distance: {distance}")
    if review_score is not None or review_word:
        score_text = f"{review_score}" if review_score is not None else "N/A"
        if review_word:
            score_text += f" ({review_word})"
        lines.append(f"- Review: {score_text}")

    if location_info and location_info.get("label"):
        lines.append(f"- Matched location: {location_info.get('label')}")

    return "\n".join(lines)


def main():
    location_info = find_best_matching_location(ELTINGVILLE_QUERY)
    hotel_results = search_hotels_for_location(location_info)
    cheapest_hotel = select_lowest_price_hotel(hotel_results)
    recommendation = format_hotel_recommendation(location_info, cheapest_hotel)
    print(recommendation)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
