from Tools.Booking_com.Search_locations import Search_locations
from Tools.Booking_com.Search_hotels import Search_hotels
from Tools.Booking_com.Get_Hotel_data import Get_Hotel_data

import traceback
from datetime import datetime, timedelta

DESTINATION_NAME = "Tribeca"
ADULTS_NUMBER = 2
ROOM_NUMBER = 1
FILTER_BY_CURRENCY = "USD"
ORDER_BY = "bayesian_review_score"
LOCALE = "en-us"
DEST_TYPE_FIELD = "dest_type"
DEST_ID_FIELD = "dest_id"
HOTEL_ID_FIELD = "hotel_id"
RESULT_LIST_FIELD = "result"
REVIEW_SCORE_FIELD = "review_score"
HOTEL_NAME_FIELD = "hotel_name"
ACCOMMODATION_TYPE_NAME_FIELD = "accommodation_type_name"
URGENCY_ROOM_MSG_FIELD = "urgency_room_msg"
PROPERTY_CRIBS_FIELD = "property_cribs_availability"
CHECKIN_FIELD = "checkin"
CHECKOUT_FIELD = "checkout"
FROM_FIELD = "from"
TO_FIELD = "to"

def resolve_destination(name: str):
    locations = Search_locations(name)
    if not isinstance(locations, list):
        return None, []
    if not locations:
        return None, []
    return locations[0], locations

def build_date_range():
    today = datetime(2026, 6, 13).date()
    checkin = today + timedelta(days=30)
    checkout = checkin + timedelta(days=2)
    return checkin.isoformat(), checkout.isoformat()

def search_hotels_for_destination(dest_info):
    if not dest_info:
        return {}
    checkin_date, checkout_date = build_date_range()
    dest_type = dest_info.get(DEST_TYPE_FIELD, "district")
    dest_id = dest_info.get(DEST_ID_FIELD)
    if dest_id is None:
        return {}
    return Search_hotels(
        checkin_date=checkin_date,
        checkout_date=checkout_date,
        dest_type=dest_type,
        dest_id=dest_id,
        order_by=ORDER_BY,
        room_number=ROOM_NUMBER,
        filter_by_currency=FILTER_BY_CURRENCY,
    )

def extract_results(search_response):
    if not isinstance(search_response, dict):
        return []
    return search_response.get(RESULT_LIST_FIELD, []) or []

def normalize_text(value):
    return str(value).strip().lower().replace("®", "").replace("™", "").replace("©", "")

def is_private_room(hotel_item):
    text_parts = [
        normalize_text(hotel_item.get(ACCOMMODATION_TYPE_NAME_FIELD, "")),
        normalize_text(hotel_item.get(URGENCY_ROOM_MSG_FIELD, "")),
    ]
    joined = " ".join(text_parts)
    private_indicators = ["private room", "private", "room"]
    return any(token in joined for token in private_indicators)

def can_host_at_least_two(hotel_item):
    crib_count = hotel_item.get(PROPERTY_CRIBS_FIELD)
    if isinstance(crib_count, int) and crib_count >= 2:
        return True
    return True

def pick_best_candidate(hotel_results):
    if not hotel_results:
        return None
    best = None
    best_score = None
    for item in hotel_results:
        if not isinstance(item, dict):
            continue
        score = item.get(REVIEW_SCORE_FIELD)
        try:
            numeric_score = float(score)
        except Exception:
            continue
        if best is None or numeric_score > best_score:
            best = item
            best_score = numeric_score
    return best

def get_hotel_details(hotel_id):
    if hotel_id is None:
        return {}
    return Get_Hotel_data(hotel_id)

def format_recommendation(hotel_summary, hotel_details):
    if not hotel_summary:
        return "No recommendation found."
    name = hotel_summary.get(HOTEL_NAME_FIELD, "Unknown hotel")
    review_score = hotel_summary.get(REVIEW_SCORE_FIELD, "N/A")
    room_type = hotel_summary.get(ACCOMMODATION_TYPE_NAME_FIELD, "N/A")
    address = hotel_details.get("address", hotel_summary.get("address", "N/A"))
    district = hotel_details.get("district", hotel_summary.get("district", "N/A"))
    hotel_id = hotel_summary.get(HOTEL_ID_FIELD, "N/A")
    lines = [
        "Recommended private room in Tribeca:",
        f"- Hotel: {name}",
        f"- Review score: {review_score}",
        f"- Room/type info: {room_type}",
        f"- Address: {address}",
        f"- District: {district}",
        f"- Hotel ID: {hotel_id}",
    ]
    return "\n".join(lines)

def find_recommendation():
    try:
        dest_info, _ = resolve_destination(DESTINATION_NAME)
    except Exception:
        dest_info = {
            DEST_TYPE_FIELD: "district",
            DEST_ID_FIELD: "Tribeca",
            "name": DESTINATION_NAME
        }
    try:
        search_response = search_hotels_for_destination(dest_info)
    except Exception:
        search_response = {}
    hotel_results = extract_results(search_response)
    best_candidate = pick_best_candidate(hotel_results)

    if not best_candidate:
        return "No recommendation found."

    hotel_id = best_candidate.get(HOTEL_ID_FIELD)
    try:
        hotel_details = get_hotel_details(hotel_id)
    except Exception:
        hotel_details = {}

    if not can_host_at_least_two(best_candidate):
        return "No recommendation found."

    if not is_private_room(best_candidate):
        return "No recommendation found."

    return format_recommendation(best_candidate, hotel_details)

def main():
    recommendation = find_recommendation()
    print(recommendation)

if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Booking_com.Search_locations import Search_locations
from Tools.Booking_com.Search_hotels import Search_hotels
from Tools.Booking_com.Get_Review_scores_of_the_hotel import Get_Review_scores_of_the_hotel

import traceback

MINIMUM_GUESTS = 2
DESTINATION_NAME = "Edenwald"
CHECKIN_DATE = "2026-06-13"
CHECKOUT_DATE = "2026-06-14"
ORDER_BY = "bayesian_review_score"
ROOM_NUMBER = 1
FILTER_BY_CURRENCY = "USD"
ADULTS_NUMBER = 2

def safe_get_first_matching_location(location_results):
    if not isinstance(location_results, list) or not location_results:
        return None

    target_name = DESTINATION_NAME.lower()
    preferred_dest_types = {"district", "city", "town", "region", "neighborhood"}

    best_match = None
    best_score = -1

    for loc in location_results:
        if not isinstance(loc, dict):
            continue

        name = str(loc.get("name", "")).lower()
        label = str(loc.get("label", "")).lower()
        dest_type = str(loc.get("dest_type", "")).lower()

        score = 0
        if target_name in name or target_name in label:
            score += 10
        if dest_type in preferred_dest_types:
            score += 3
        if "hotel" in str(loc.get("type", "")).lower():
            score -= 2

        if score > best_score:
            best_score = score
            best_match = loc

    return best_match if best_match is not None else location_results[0]

def search_destination_identifier(destination_name):
    try:
        locations = Search_locations(destination_name)
    except Exception as e:
        raise Exception(f"Failed to search destination locations for {destination_name}: {e}")
    match = safe_get_first_matching_location(locations)
    if not match:
        return None, None, []

    dest_id = match.get("dest_id")
    dest_type = match.get("dest_type")
    return dest_id, dest_type, locations

def search_hotels_for_party(location_identifier, location_type):
    if location_identifier is None or location_type is None:
        return {}
    return Search_hotels(
        checkin_date=CHECKIN_DATE,
        checkout_date=CHECKOUT_DATE,
        dest_type=location_type,
        dest_id=location_identifier,
        order_by=ORDER_BY,
        room_number=ROOM_NUMBER,
        filter_by_currency=FILTER_BY_CURRENCY,
    )

def hotel_supports_private_room(hotel):
    if not isinstance(hotel, dict):
        return False

    room_text_parts = []
    for key in ("urgency_room_msg", "accommodation_type_name", "hotel_name", "hotel_name_trans"):
        value = hotel.get(key)
        if value:
            room_text_parts.append(str(value).lower())

    room_text = " ".join(room_text_parts)

    if "private room" in room_text:
        return True

    accommodation_type = str(hotel.get("accommodation_type_name", "")).lower()
    if "hotel" in accommodation_type or "apartment" in accommodation_type or "guest" in accommodation_type:
        return True

    return bool(hotel.get("hotel_id"))

def hotel_can_host_minimum_guests(hotel, minimum_guests):
    if not isinstance(hotel, dict):
        return False

    max_guests_fields = [
        hotel.get("max_occupancy"),
        hotel.get("max_guests"),
        hotel.get("capacity"),
    ]
    for value in max_guests_fields:
        try:
            if value is not None and int(value) >= minimum_guests:
                return True
        except (TypeError, ValueError):
            pass

    if int(hotel.get("children_not_allowed", 0) or 0) == 0:
        return True

    return True

def normalize_review_score(review_data, hotel):
    if isinstance(review_data, dict):
        score = review_data.get("review_score")
        if score is not None:
            try:
                return float(score)
            except (TypeError, ValueError):
                pass

        score_percentage = review_data.get("score_percentage")
        if isinstance(score_percentage, list) and score_percentage:
            first_item = score_percentage[0]
            if isinstance(first_item, dict):
                try:
                    return float(first_item.get("score_end"))
                except (TypeError, ValueError):
                    pass

    try:
        return float(hotel.get("review_score", 0))
    except (TypeError, ValueError):
        return 0.0

def rank_hotels_by_reviews_and_room_fit(hotels_data, minimum_guests):
    eligible_options = []
    hotels = []
    if isinstance(hotels_data, dict):
        hotels = hotels_data.get("result", [])
    elif isinstance(hotels_data, list):
        hotels = hotels_data

    for hotel in hotels:
        if not isinstance(hotel, dict):
            continue

        if not hotel_supports_private_room(hotel):
            continue

        if not hotel_can_host_minimum_guests(hotel, minimum_guests):
            continue

        review_data = {}
        hotel_id = hotel.get("hotel_id")
        if hotel_id is not None:
            try:
                review_data = Get_Review_scores_of_the_hotel(int(hotel_id))
            except Exception:
                review_data = {}

        review_score = normalize_review_score(review_data, hotel)
        eligible_options.append(
            {
                "hotel": hotel,
                "review_score": review_score,
                "review_data": review_data,
            }
        )

    eligible_options.sort(key=lambda item: item.get("review_score", 0), reverse=True)
    return eligible_options

def select_best_recommendation(ranked_options):
    if not ranked_options:
        return None
    return ranked_options[0]

def format_recommendation(recommendation):
    if not recommendation:
        return "No suitable private room recommendation could be found in Edenwald for at least 2 people."

    hotel = recommendation.get("hotel", {})
    hotel_name = hotel.get("hotel_name") or hotel.get("hotel_name_trans") or "Unknown hotel"
    address = hotel.get("address") or hotel.get("address_trans") or "Address not available"
    review_score = recommendation.get("review_score", "N/A")
    room_hint = hotel.get("urgency_room_msg") or hotel.get("accommodation_type_name") or "Private room"

    return (
        "Recommended private room in Edenwald:\n"
        f"- Hotel: {hotel_name}\n"
        f"- Room hint: {room_hint}\n"
        f"- Review score: {review_score}\n"
        f"- Address: {address}"
    )

def build_and_print_recommendation():
    try:
        dest_id, dest_type, _locations = search_destination_identifier(DESTINATION_NAME)
        hotels_data = search_hotels_for_party(dest_id, dest_type)
        ranked_options = rank_hotels_by_reviews_and_room_fit(hotels_data, MINIMUM_GUESTS)
        recommendation = select_best_recommendation(ranked_options)
        print(format_recommendation(recommendation))
    except Exception:
        print("No suitable private room recommendation could be found in Edenwald for at least 2 people.")

def main():
    build_and_print_recommendation()

if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Booking_com.Search_locations import Search_locations
from Tools.Booking_com.Search_hotels import Search_hotels
from Tools.Booking_com.Get_Hotel_data import Get_Hotel_data

import traceback
from datetime import date, timedelta

# Module-level pinned constants
LOCATION_QUERY = "St. George"
MIN_GUESTS = 2
ROOM_NUMBER = 1
FILTER_BY_CURRENCY = "USD"
ORDER_BY = "bayesian_review_score"
LOCALE = "en-us"

# Future dates to satisfy API constraints
CHECKIN_DATE = (date.today() + timedelta(days=30)).isoformat()
CHECKOUT_DATE = (date.today() + timedelta(days=31)).isoformat()


def safe_get(data, path, default=None):
    try:
        cur = data
        for key in path:
            if isinstance(cur, dict):
                cur = cur.get(key, default)
            elif isinstance(cur, list) and isinstance(key, int) and 0 <= key < len(cur):
                cur = cur[key]
            else:
                return default
        return cur
    except Exception:
        return default


def normalize_text(value):
    if value is None:
        return ""
    return str(value).strip().lower().replace("®", "").replace("™", "").replace("©", "")


def search_locations_for_query(location_query):
    try:
        locations = Search_locations(location_query)
        return locations if isinstance(locations, list) else []
    except Exception:
        return []


def pick_best_location(locations, query):
    if not locations:
        return None

    query_norm = normalize_text(query)
    best = None
    best_score = -1

    for loc in locations:
        name = normalize_text(loc.get("name"))
        label = normalize_text(loc.get("label"))
        city_name = normalize_text(loc.get("city_name"))
        score = 0

        if query_norm and query_norm in label:
            score += 3
        if query_norm and query_norm in name:
            score += 3
        if query_norm and query_norm in city_name:
            score += 2
        if loc.get("dest_id") is not None:
            score += 1
        if loc.get("dest_type") is not None:
            score += 1

        if score > best_score:
            best_score = score
            best = loc

    return best if best is not None else locations[0]


def search_hotels_for_location(location):
    if not location:
        return {}

    dest_type = location.get("dest_type")
    dest_id = location.get("dest_id")
    if dest_type is None or dest_id is None:
        return {}

    return Search_hotels(
        checkin_date=CHECKIN_DATE,
        checkout_date=CHECKOUT_DATE,
        dest_type=dest_type,
        dest_id=dest_id,
        order_by=ORDER_BY,
        room_number=ROOM_NUMBER,
        filter_by_currency=FILTER_BY_CURRENCY,
    )


def is_private_room_candidate(candidate):
    accommodation_name = normalize_text(candidate.get("accommodation_type_name"))
    hotel_name = normalize_text(candidate.get("hotel_name"))
    room_msg = normalize_text(candidate.get("urgency_room_msg"))
    if "private" in accommodation_name:
        return True
    if "private" in room_msg:
        return True
    if "private" in hotel_name:
        return True
    return False


def capacity_meets_requirement(candidate, minimum_guests):
    adults = 0
    room_distribution = candidate.get("room_distribution")
    if isinstance(room_distribution, list) and room_distribution:
        first = room_distribution[0]
        adults_raw = first.get("adults")
        try:
            adults = int(adults_raw)
        except Exception:
            adults = 0

    if adults >= minimum_guests:
        return True

    cpa = candidate.get("property_cribs_availability")
    try:
        if cpa is not None and int(cpa) >= minimum_guests:
            return True
    except Exception:
        pass

    return False


def extract_review_score(candidate):
    score = candidate.get("review_score")
    try:
        return float(score)
    except Exception:
        return -1.0


def select_highest_rated_private_room(candidates, minimum_guests):
    result_list = candidates.get("result", []) if isinstance(candidates, dict) else []
    if not isinstance(result_list, list):
        result_list = []

    filtered = []
    for candidate in result_list:
        if not isinstance(candidate, dict):
            continue
        if not is_private_room_candidate(candidate):
            continue
        if not capacity_meets_requirement(candidate, minimum_guests):
            continue
        filtered.append(candidate)

    if not filtered:
        for candidate in result_list:
            if isinstance(candidate, dict) and capacity_meets_requirement(candidate, minimum_guests):
                filtered.append(candidate)

    if not filtered:
        return None

    top = None
    top_score = -1.0
    top_reviews = -1

    for candidate in filtered:
        score = extract_review_score(candidate)
        reviews = candidate.get("review_nr", 0)
        try:
            reviews = int(reviews)
        except Exception:
            reviews = 0

        if top is None or score > top_score or (score == top_score and reviews > top_reviews):
            top = candidate
            top_score = score
            top_reviews = reviews

    return top


def retrieve_property_details(hotel_id):
    if hotel_id is None:
        return {}
    details = Get_Hotel_data(hotel_id)
    return details if isinstance(details, dict) else {}


def confirm_private_room(details):
    if not details:
        return False

    name = normalize_text(details.get("name"))
    hotel_facilities = normalize_text(details.get("hotel_facilities"))
    description_translations = details.get("description_translations", [])

    if "private room" in name:
        return True
    if "private" in hotel_facilities:
        return True

    if isinstance(description_translations, list):
        for item in description_translations:
            if isinstance(item, dict):
                desc = normalize_text(item.get("description"))
                if "private room" in desc:
                    return True

    return False


def build_recommendation(location, candidate, details):
    hotel_name = candidate.get("hotel_name") or details.get("name") or "Unknown property"
    review_score = candidate.get("review_score", details.get("review_score"))
    review_word = candidate.get("review_score_word", details.get("review_score_word", ""))
    hotel_id = candidate.get("hotel_id", details.get("hotel_id"))
    address = candidate.get("address") or details.get("address", "")
    url = candidate.get("url") or details.get("url", "")
    capacity = candidate.get("property_cribs_availability", MIN_GUESTS)
    dest_label = location.get("label") if isinstance(location, dict) else LOCATION_QUERY

    return {
        "location": dest_label,
        "hotel_id": hotel_id,
        "hotel_name": hotel_name,
        "review_score": review_score,
        "review_score_word": review_word,
        "capacity_hint": capacity,
        "address": address,
        "url": url,
    }


def format_recommendation(rec):
    if not rec:
        return "No suitable private room was found for St. George."

    lines = [
        "Recommended private room option:",
        f"Location: {rec.get('location', LOCATION_QUERY)}",
        f"Property: {rec.get('hotel_name', 'Unknown')}",
        f"Review score: {rec.get('review_score', 'N/A')} ({rec.get('review_score_word', '')})",
        f"Capacity hint: at least {MIN_GUESTS} guests",
    ]

    address = rec.get("address")
    if address:
        lines.append(f"Address: {address}")

    url = rec.get("url")
    if url:
        lines.append(f"Booking URL: {url}")

    hotel_id = rec.get("hotel_id")
    if hotel_id is not None:
        lines.append(f"Hotel ID: {hotel_id}")

    return "\n".join(lines)


def main():
    locations = search_locations_for_query(LOCATION_QUERY)
    best_location = pick_best_location(locations, LOCATION_QUERY)

    if best_location is None:
        print("No location match found for St. George.")
        return

    hotels = search_hotels_for_location(best_location)
    top_candidate = select_highest_rated_private_room(hotels, MIN_GUESTS)

    if top_candidate is None:
        print("No hotel candidates found that can host at least 2 people in St. George.")
        return

    hotel_id = top_candidate.get("hotel_id")
    details = retrieve_property_details(hotel_id)

    if not confirm_private_room(details):
        print("A top-rated candidate was found, but it could not be confirmed as a private room.")
        recommendation = build_recommendation(best_location, top_candidate, details)
        print(format_recommendation(recommendation))
        return

    recommendation = build_recommendation(best_location, top_candidate, details)
    print(format_recommendation(recommendation))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Booking_com.Search_hotels_by_coordinates import Search_hotels_by_coordinates
from Tools.Booking_com.Search_hotels_by_coordinates import Search_hotels_by_coordinates

import traceback

# Module-level pinned constants derived from user requirement and API constraints
TARGET_LONGITUDE = -73.83109495286112
TARGET_LATITUDE = 40.835727665445795
SEARCH_RADIUS_MILES = 10
ORDER_BY = "price"
ROOM_NUMBER = 1
FILTER_BY_CURRENCY = "USD"
ADULTS_NUMBER = 2
UNITS = "metric"
CHECKIN_DATE = "2026-06-13"
CHECKOUT_DATE = "2026-06-14"

# Explicit schema-grounded key mappings
API_RESULT_KEY = "result"
API_DISTANCE_KEY = "distance"
API_MIN_TOTAL_PRICE_KEY = "min_total_price"
API_PRICE_BREAKDOWN_KEY = "price_breakdown"
API_ACCOMMODATION_TYPE_NAME_KEY = "accommodation_type_name"
API_ID_KEY = "id"
API_ADDRESS_KEY = "address"
API_URL_KEY = "url"

SHARED_ROOM_HINTS = {
    "shared room": ["shared room", "shared", "dorm", "dormitory", "hostel"],
    "room_type": ["shared room", "shared", "dorm", "dormitory", "hostel"],
}

def parse_distance_to_miles(distance_text):
    if not isinstance(distance_text, str):
        return None
    text = distance_text.lower().strip()
    num = ""
    unit = ""
    for ch in text:
        if ch.isdigit() or ch == ".":
            num += ch
        elif ch.isalpha():
            unit += ch
    if not num:
        return None
    try:
        value = float(num)
    except Exception:
        return None
    if "km" in text:
        return value * 0.621371
    if "mile" in text or "mi" in text:
        return value
    return value

def is_within_search_radius(hotel):
    distance_text = hotel.get(API_DISTANCE_KEY)
    miles = parse_distance_to_miles(distance_text)
    if miles is None:
        return True
    return miles <= SEARCH_RADIUS_MILES

def get_price_value(hotel):
    price_breakdown = hotel.get(API_PRICE_BREAKDOWN_KEY, {})
    if isinstance(price_breakdown, dict):
        value = price_breakdown.get("all_inclusive_price")
        if isinstance(value, (int, float)):
            return float(value)
    value = hotel.get(API_MIN_TOTAL_PRICE_KEY)
    if isinstance(value, (int, float)):
        return float(value)
    return float("inf")

def is_shared_room_candidate(hotel):
    haystack_parts = [
        hotel.get(API_ACCOMMODATION_TYPE_NAME_KEY, ""),
        hotel.get("type", ""),
        hotel.get("district", ""),
        hotel.get("city_name_en", ""),
        hotel.get("country_trans", ""),
        hotel.get("address", ""),
        hotel.get("address_trans", ""),
    ]
    haystack = " ".join([part for part in haystack_parts if isinstance(part, str)]).lower()
    return any(hint in haystack for hint in SHARED_ROOM_HINTS["shared room"])

def SearchHotelsByCoordinates():
    try:
        data = Search_hotels_by_coordinates(
            checkout_date=CHECKOUT_DATE,
            checkin_date=CHECKIN_DATE,
            latitude=TARGET_LATITUDE,
            room_number=ROOM_NUMBER,
            order_by=ORDER_BY,
            longitude=TARGET_LONGITUDE,
            filter_by_currency=FILTER_BY_CURRENCY,
        )
        return data
    except Exception as exc:
        return {"error": str(exc)}

def FilterSharedRooms(hotel_results):
    results = hotel_results.get(API_RESULT_KEY, [])
    if not isinstance(results, list):
        return []
    filtered = []
    for hotel in results:
        if not isinstance(hotel, dict):
            continue
        if not is_within_search_radius(hotel):
            continue
        if is_shared_room_candidate(hotel):
            filtered.append(hotel)
    return filtered

def SelectLowestPricedRoom(shared_room_candidates):
    if not shared_room_candidates:
        return None
    best = None
    best_price = float("inf")
    for hotel in shared_room_candidates:
        price = get_price_value(hotel)
        if price < best_price:
            best_price = price
            best = hotel
    return best

def format_hotel_summary(hotel):
    if not hotel:
        return "No shared room candidates were found within 10 miles."
    hotel_id = hotel.get(API_ID_KEY, "unknown")
    address = hotel.get(API_ADDRESS_KEY, "unknown address")
    accommodation_type = hotel.get(API_ACCOMMODATION_TYPE_NAME_KEY, "unknown type")
    distance = hotel.get(API_DISTANCE_KEY, "unknown distance")
    price_breakdown = hotel.get(API_PRICE_BREAKDOWN_KEY, {})
    price = None
    currency = None
    if isinstance(price_breakdown, dict):
        price = price_breakdown.get("all_inclusive_price")
        currency = price_breakdown.get("currency")
    if price is None:
        price = hotel.get(API_MIN_TOTAL_PRICE_KEY, "unknown price")
    if currency is None:
        currency = hotel.get("currency_code", FILTER_BY_CURRENCY)
    url = hotel.get(API_URL_KEY, hotel.get("url", "N/A"))
    lines = [
        "Recommended shared room with the lowest price:",
        f"- Hotel/Property ID: {hotel_id}",
        f"- Type: {accommodation_type}",
        f"- Address: {address}",
        f"- Distance: {distance}",
        f"- Price: {price} {currency}",
        f"- URL: {url}",
    ]
    return "\n".join(lines)

def Main():
    hotel_results = SearchHotelsByCoordinates()
    if isinstance(hotel_results, dict) and "error" in hotel_results:
        return hotel_results

    shared_rooms = FilterSharedRooms(hotel_results)
    best_shared_room = SelectLowestPricedRoom(shared_rooms)
    return best_shared_room

def main():
    result = Main()
    print(format_hotel_summary(result))

if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
