from Tools.Flights_Data_API.Get_Flight_status import Get_Flight_status
from Tools.Flights_Data_API.Get_Flight_history_and_Schedule import Get_Flight_history_and_Schedule

import traceback
from datetime import datetime

FLIGHT_NUMBER = "WN2361"
FLIGHT_DATE = "2025-06-16"
DEPARTURE_AIRPORT_IATA = "AUS"
ARRIVAL_AIRPORT_IATA = "FLL"


def parse_utc_time_to_datetime(time_str):
    if not time_str:
        return None
    for fmt in ("%Y-%m-%d %H:%MZ", "%Y-%m-%d %H:%M%z", "%Y-%m-%d %H:%M:%SZ"):
        try:
            return datetime.strptime(time_str, fmt)
        except ValueError:
            pass
    try:
        cleaned = time_str.replace("Z", "+0000")
        return datetime.strptime(cleaned, "%Y-%m-%d %H:%M%z")
    except ValueError:
        return None


def minutes_between(start_dt, end_dt):
    if start_dt is None or end_dt is None:
        return None
    delta = end_dt - start_dt
    return int(round(delta.total_seconds() / 60))


def extract_matching_flight_record(history_records, departure_iata, arrival_iata):
    if not isinstance(history_records, list):
        return None

    for record in history_records:
        if not isinstance(record, dict):
            continue
        departure = record.get("departure", {})
        arrival = record.get("arrival", {})
        dep_airport = departure.get("airport", {})
        arr_airport = arrival.get("airport", {})

        dep_iata = dep_airport.get("iata", "")
        arr_iata = arr_airport.get("iata", "")

        if (
            str(dep_iata).upper() == departure_iata.upper()
            and str(arr_iata).upper() == arrival_iata.upper()
        ):
            return record
    return None


def extract_planned_and_actual_timings(flight_record):
    departure = flight_record.get("departure", {}) if isinstance(flight_record, dict) else {}
    arrival = flight_record.get("arrival", {}) if isinstance(flight_record, dict) else {}

    planned_departure = departure.get("scheduledTime", {}).get("utc")
    planned_arrival = arrival.get("scheduledTime", {}).get("utc")

    actual_departure = (
        departure.get("runwayTime", {}).get("utc")
        or departure.get("revisedTime", {}).get("utc")
        or departure.get("scheduledTime", {}).get("utc")
    )
    actual_arrival = (
        arrival.get("runwayTime", {}).get("utc")
        or arrival.get("predictedTime", {}).get("utc")
        or arrival.get("revisedTime", {}).get("utc")
        or arrival.get("scheduledTime", {}).get("utc")
    )

    return {
        "planned_departure": planned_departure,
        "planned_arrival": planned_arrival,
        "actual_departure": actual_departure,
        "actual_arrival": actual_arrival,
    }


def compute_extra_minutes(timings):
    planned_dep_dt = parse_utc_time_to_datetime(timings.get("planned_departure"))
    planned_arr_dt = parse_utc_time_to_datetime(timings.get("planned_arrival"))
    actual_dep_dt = parse_utc_time_to_datetime(timings.get("actual_departure"))
    actual_arr_dt = parse_utc_time_to_datetime(timings.get("actual_arrival"))

    planned_duration = minutes_between(planned_dep_dt, planned_arr_dt)
    actual_duration = minutes_between(actual_dep_dt, actual_arr_dt)

    if planned_duration is None or actual_duration is None:
        return None, planned_duration, actual_duration

    return actual_duration - planned_duration, planned_duration, actual_duration


def lookup_flight_status_by_date(flight_identifier, flight_date):
    history = Get_Flight_history_and_Schedule(flight_identifier, flight_date, flight_date)
    return history


def retrieve_flight_schedule_and_history(flight_identifier):
    return Get_Flight_status(flight_identifier)


def find_extra_minutes_for_flight(flight_number, flight_date, departure_iata, arrival_iata):
    history_records = lookup_flight_status_by_date(flight_number, flight_date)
    matched_record = extract_matching_flight_record(history_records, departure_iata, arrival_iata)

    if matched_record is None:
        return None, None, None, None

    timings = extract_planned_and_actual_timings(matched_record)
    extra_minutes, planned_duration, actual_duration = compute_extra_minutes(timings)

    return extra_minutes, planned_duration, actual_duration, matched_record


def format_result(extra_minutes, planned_duration, actual_duration, matched_record):
    if extra_minutes is None:
        return "Could not determine the extra minutes for the specified flight/date/route."

    flight_no = matched_record.get("number", FLIGHT_NUMBER) if isinstance(matched_record, dict) else FLIGHT_NUMBER
    dep_iata = (
        matched_record.get("departure", {}).get("airport", {}).get("iata", DEPARTURE_AIRPORT_IATA)
        if isinstance(matched_record, dict)
        else DEPARTURE_AIRPORT_IATA
    )
    arr_iata = (
        matched_record.get("arrival", {}).get("airport", {}).get("iata", ARRIVAL_AIRPORT_IATA)
        if isinstance(matched_record, dict)
        else ARRIVAL_AIRPORT_IATA
    )

    return (
        f"Flight {flight_no} from {dep_iata} to {arr_iata} on {FLIGHT_DATE} "
        f"took {extra_minutes} extra minutes.\n"
        f"Planned duration: {planned_duration} minutes\n"
        f"Actual duration: {actual_duration} minutes"
    )


def main():
    extra_minutes, planned_duration, actual_duration, matched_record = find_extra_minutes_for_flight(
        FLIGHT_NUMBER,
        FLIGHT_DATE,
        DEPARTURE_AIRPORT_IATA,
        ARRIVAL_AIRPORT_IATA,
    )
    print(format_result(extra_minutes, planned_duration, actual_duration, matched_record))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

