def search_flight_status(flight_identifier: str):
    try:
        return Get_Flight_status(flight_identifier)
    except Exception:
        raise


def extract_matching_flight_records(flight_status_result, flight_identifier: str):
    if not isinstance(flight_status_result, list):
        return []

    normalized_target = flight_identifier.replace(" ", "").upper()
    matched_records = []

    for record in flight_status_result:
        if not isinstance(record, dict):
            continue

        number = str(record.get("number", "")).replace(" ", "").upper()
        call_sign = str(record.get("callSign", "")).replace(" ", "").upper()

        if normalized_target in number or normalized_target in call_sign:
            matched_records.append(record)

    return matched_records


def extract_arrival_info(flight_record: dict):
    if not isinstance(flight_record, dict):
        return {}

    arrival = flight_record.get("arrival", {})
    if not isinstance(arrival, dict):
        return {}
    return arrival


def get_local_arrival_time(arrival_details: dict):
    if not isinstance(arrival_details, dict):
        return None

    scheduled_time = arrival_details.get("scheduledTime", {})
    if isinstance(scheduled_time, dict):
        local_time = scheduled_time.get("local")
        if local_time:
            return local_time

    revised_time = arrival_details.get("revisedTime", {})
    if isinstance(revised_time, dict):
        local_time = revised_time.get("local")
        if local_time:
            return local_time

    predicted_time = arrival_details.get("predictedTime", {})
    if isinstance(predicted_time, dict):
        local_time = predicted_time.get("local")
        if local_time:
            return local_time

    return None


def find_local_arrival_time(flight_identifier: str):
    status_result = search_flight_status(flight_identifier)
    matching_records = extract_matching_flight_records(status_result, flight_identifier)

    for record in matching_records:
        arrival_info = extract_arrival_info(record)
        local_time = get_local_arrival_time(arrival_info)
        if local_time:
            return local_time

    return None


def main():
    local_arrival_time = find_local_arrival_time(FLIGHT_IDENTIFIER)
    if local_arrival_time:
        print(f"Local arrival time for {FLIGHT_IDENTIFIER} on {FLIGHT_DATE}: {local_arrival_time}")
    else:
        print(f"Local arrival time for {FLIGHT_IDENTIFIER} on {FLIGHT_DATE}: not available")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

