from Tools.Flights_Data_API.Get_Flight_status import Get_Flight_status

import traceback

# Module-level constants pinned from the user requirement and schema-grounded assumptions.
FLIGHT_NUMBER = "UA4425"
ORIGIN_AIRPORT_IATA = "EWR"
DESTINATION_AIRPORT_IATA = "DCA"
TARGET_DATE_LOCAL = "2025-06-29"

# The API schema for Get_Flight_status returns a list of flight records, where each record
# may contain `departure.airport.iata`, `arrival.airport.iata`, `departure.scheduledTime.local`,
# and `arrival.scheduledTime.local`. The user asks for CRS-recorded arrival time; in this schema,
# the closest explicit recorded arrival field is `arrival.scheduledTime.local`.
ARRIVAL_TIME_PATH = ("arrival", "scheduledTime", "local")
DEPARTURE_IATA_PATH = ("departure", "airport", "iata")
ARRIVAL_IATA_PATH = ("arrival", "airport", "iata")
DEPARTURE_DATE_LOCAL_PATH = ("departure", "scheduledTime", "local")
ARRIVAL_DATE_LOCAL_PATH = ("arrival", "scheduledTime", "local")


def safe_get_path(obj, path):
    current = obj
    for key in path:
        if not isinstance(current, dict):
            return None
        current = current.get(key)
    return current


def fetch_flight_records(flight_number):
    try:
        records = Get_Flight_status(flight_number)
        if records is None:
            return []
        if isinstance(records, list):
            return records
        return []
    except Exception:
        raise


def normalize_text(value):
    if value is None:
        return ""
    return str(value).strip().lower()


def extract_local_date(time_str):
    text = normalize_text(time_str)
    if len(text) >= 10:
        return text[:10]
    return ""


def record_matches_route_and_date(record):
    dep_iata = normalize_text(safe_get_path(record, DEPARTURE_IATA_PATH))
    arr_iata = normalize_text(safe_get_path(record, ARRIVAL_IATA_PATH))
    dep_local = safe_get_path(record, DEPARTURE_DATE_LOCAL_PATH)
    arr_local = safe_get_path(record, ARRIVAL_DATE_LOCAL_PATH)

    dep_date = extract_local_date(dep_local)
    arr_date = extract_local_date(arr_local)

    route_match = (
        dep_iata == normalize_text(ORIGIN_AIRPORT_IATA)
        and arr_iata == normalize_text(DESTINATION_AIRPORT_IATA)
    )
    date_match = TARGET_DATE_LOCAL in (dep_date, arr_date)
    return route_match and date_match


def find_matching_flight_record(records):
    for record in records:
        if isinstance(record, dict) and record_matches_route_and_date(record):
            return record
    return None


def get_crs_recorded_arrival_time(flight_record):
    if not isinstance(flight_record, dict):
        return None
    return safe_get_path(flight_record, ARRIVAL_TIME_PATH)


def build_result_message(crs_arrival_time):
    if crs_arrival_time:
        return f"CRS-recorded arrival time for {FLIGHT_NUMBER} from {ORIGIN_AIRPORT_IATA} to {DESTINATION_AIRPORT_IATA} on {TARGET_DATE_LOCAL}: {crs_arrival_time}"
    return f"No matching flight record found for {FLIGHT_NUMBER} from {ORIGIN_AIRPORT_IATA} to {DESTINATION_AIRPORT_IATA} on {TARGET_DATE_LOCAL}."


def main():
    records = fetch_flight_records(FLIGHT_NUMBER)
    matched_record = find_matching_flight_record(records)
    crs_arrival_time = get_crs_recorded_arrival_time(matched_record)
    print(build_result_message(crs_arrival_time))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

