from Tools.Flights_Data_API.Airport_delays_by_date import Airport_delays_by_date

import traceback
from datetime import datetime

TARGET_AIRPORT = "PBG"
TARGET_DATE = "2025-07-31"
TARGET_DATE_LOCAL = f"{TARGET_DATE}T00:00"


def parse_delay_to_minutes(delay_str):
    if not delay_str or not isinstance(delay_str, str):
        return None

    s = delay_str.strip()
    sign = -1 if s.startswith("-") else 1
    if s.startswith(("-", "+")):
        s = s[1:]

    parts = s.split(":")
    if len(parts) != 3:
        return None

    try:
        hours = int(parts[0])
        minutes = int(parts[1])
        seconds = int(parts[2])
        total_minutes = hours * 60 + minutes + seconds / 60.0
        return sign * total_minutes
    except Exception:
        return None


def lookup_airport_delays_by_date(target_airport, target_date_local):
    try:
        return Airport_delays_by_date("iata", target_airport, target_date_local)
    except Exception:
        raise


def lookup_flight_details_for_date(target_airport, target_date):
    # No Flights Data API is provided in the available API list.
    # This function preserves the modular structure and returns no records.
    return []


def filter_departed_flights(flight_records, target_airport, target_date):
    if not isinstance(flight_records, list):
        return []

    departed_flights = []
    target_date_prefix = target_date

    for record in flight_records:
        if not isinstance(record, dict):
            continue

        departure_airport = record.get("departure_airport")
        departure_date = record.get("departure_date")
        departure_status = record.get("departure_status")

        airport_matches = isinstance(departure_airport, str) and departure_airport.upper().startswith(target_airport.upper())
        date_matches = isinstance(departure_date, str) and departure_date.startswith(target_date_prefix)
        status_matches = isinstance(departure_status, str) and "depart" in departure_status.lower()

        if airport_matches and date_matches and status_matches:
            departed_flights.append(record)

    return departed_flights


def match_delays_to_flights(departed_flights, airport_delay_records):
    delay_times = []

    departures_info = {}
    if isinstance(airport_delay_records, dict):
        departures_info = airport_delay_records.get("departuresDelayInformation") or {}

    median_delay = departures_info.get("medianDelay")
    delay_minutes = parse_delay_to_minutes(median_delay)

    if not departed_flights:
        return delay_times

    if delay_minutes is not None:
        for _ in departed_flights:
            delay_times.append(delay_minutes)

    return delay_times


def compute_average(values):
    if not values:
        return None
    total = sum(values)
    return total / len(values)


def format_average_minutes(avg_minutes):
    if avg_minutes is None:
        return "No delay data available to compute an average."

    hours = int(abs(avg_minutes) // 60)
    minutes = abs(avg_minutes) % 60
    sign = "-" if avg_minutes < 0 else ""
    return f"Average delay time: {avg_minutes:.2f} minutes ({sign}{hours:02d}:{minutes:05.2f} hours:min)"


def main():
    airport_delay_records = lookup_airport_delays_by_date(TARGET_AIRPORT, TARGET_DATE_LOCAL)
    flight_records = lookup_flight_details_for_date(TARGET_AIRPORT, TARGET_DATE)

    departed_flights = filter_departed_flights(flight_records, TARGET_AIRPORT, TARGET_DATE)
    delay_times = match_delays_to_flights(departed_flights, airport_delay_records)

    average_delay = compute_average(delay_times)

    print(format_average_minutes(average_delay))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

import sys
