from Tools.Flights_Data_API.Airport_delays_by_date import Airport_delays_by_date

import traceback

# Module-level pinned constants derived from the user requirement and API schema.
AIRPORT_CODE_TYPE = "iata"
AIRPORT_CODE = "SUX"
TARGET_DATE = "2025-07-12T00:00"

def parse_hhmmss_to_minutes(time_str):
    if not time_str or not isinstance(time_str, str):
        return None
    try:
        negative = time_str.startswith("-")
        cleaned = time_str[1:] if negative else time_str
        parts = cleaned.split(":")
        if len(parts) != 3:
            return None
        hours = int(parts[0])
        minutes = int(parts[1])
        seconds = int(parts[2])
        total_minutes = hours * 60 + minutes
        if seconds >= 30:
            total_minutes += 1
        return -total_minutes if negative else total_minutes
    except Exception:
        return None

def format_minutes_as_hhmm(minutes_value):
    if minutes_value is None:
        return "no data"
    sign = "-" if minutes_value < 0 else ""
    total = abs(int(round(minutes_value)))
    hours = total // 60
    minutes = total % 60
    return f"{sign}{hours:02d}:{minutes:02d}:00"

def lookup_airport_delays_by_date(airport_code_type, airport_code, target_date):
    try:
        return Airport_delays_by_date(airport_code_type, airport_code, target_date)
    except Exception:
        raise

def extract_departure_delay_information(delay_records):
    if not isinstance(delay_records, dict):
        return {}
    return delay_records.get("departuresDelayInformation", {}) or {}

def compute_average_delay_from_departure_info(departure_info):
    if not isinstance(departure_info, dict) or not departure_info:
        return None

    num_qualified_total = departure_info.get("numQualifiedTotal", 0)
    median_delay = departure_info.get("medianDelay")

    if num_qualified_total is None:
        num_qualified_total = 0

    # The available API schema provides aggregated delay statistics, not per-flight records.
    # Therefore, the best grounded interpretation for "average delay time" from the API response
    # is to use the departure delay metric exposed in the schema, which is medianDelay.
    delay_minutes = parse_hhmmss_to_minutes(median_delay)
    return delay_minutes

def build_result_message(airport_code, target_date, average_delay_minutes):
    date_only = target_date.split("T")[0] if isinstance(target_date, str) and "T" in target_date else target_date
    if average_delay_minutes is None:
        return f"No departure delay data available for {airport_code} on {date_only}."
    formatted = format_minutes_as_hhmm(average_delay_minutes)
    return f"Average departure delay time for all flights from {airport_code} on {date_only}: {formatted}"

def main():
    delay_records = lookup_airport_delays_by_date(AIRPORT_CODE_TYPE, AIRPORT_CODE, TARGET_DATE)
    departure_info = extract_departure_delay_information(delay_records)
    average_delay_minutes = compute_average_delay_from_departure_info(departure_info)
    message = build_result_message(AIRPORT_CODE, TARGET_DATE, average_delay_minutes)
    print(message)

if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Flights_Data_API.Flight_delays_by_flight_number import Flight_delays_by_flight_number
from Tools.Flights_Data_API.Get_Flight_history_and_Schedule import Get_Flight_history_and_Schedule

import traceback
from datetime import datetime, timedelta

FLIGHT_NUMBER = "WN6679"

# Assumption based on available APIs: use a one-day window to fetch history/schedule data.
DATE_FROM_LOCAL = "2026-01-01"
DATE_TO_LOCAL = "2026-01-02"


def parse_datetime_with_optional_z(value):
    if not value:
        return None
    candidates = [
        "%Y-%m-%d %H:%MZ",
        "%Y-%m-%d %H:%M%z",
        "%Y-%m-%d %H:%M:%S%z",
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%d %H:%M",
    ]
    normalized = value.replace("Z", "+0000")
    normalized = normalized.replace(":", "", 1) if len(normalized) >= 25 and normalized[-6] in ["+", "-"] and normalized[-3] == ":" else normalized
    for fmt in candidates:
        try:
            return datetime.strptime(value, fmt)
        except Exception:
            pass
        try:
            return datetime.strptime(normalized, fmt)
        except Exception:
            pass
    return None


def parse_hhmmss_duration(value):
    if not value:
        return None
    sign = -1 if str(value).startswith("-") else 1
    clean = str(value).replace("-", "")
    parts = clean.split(":")
    if len(parts) != 3:
        return None
    try:
        hours = int(parts[0])
        minutes = int(parts[1])
        seconds = int(parts[2])
        return sign * (hours * 3600 + minutes * 60 + seconds)
    except Exception:
        return None


def seconds_to_readable(total_seconds):
    if total_seconds is None:
        return "N/A"
    sign = "-" if total_seconds < 0 else ""
    total_seconds = abs(int(round(total_seconds)))
    hours = total_seconds // 3600
    minutes = (total_seconds % 3600) // 60
    seconds = total_seconds % 60
    return f"{sign}{hours:02d}:{minutes:02d}:{seconds:02d}"


def lookup_flight_delay_statistics(flight_number):
    try:
        return Flight_delays_by_flight_number(flight_number)
    except Exception:
        return None


def lookup_flight_history_and_schedule(flight_number, date_from_local, date_to_local):
    try:
        return Get_Flight_history_and_Schedule(flight_number, date_from_local, date_to_local)
    except Exception:
        return None


def extract_flight_duration_seconds(record):
    departure = record.get("departure", {})
    arrival = record.get("arrival", {})
    dep_time = (
        departure.get("scheduledTime", {}).get("utc")
        or departure.get("revisedTime", {}).get("utc")
        or departure.get("runwayTime", {}).get("utc")
    )
    arr_time = (
        arrival.get("scheduledTime", {}).get("utc")
        or arrival.get("predictedTime", {}).get("utc")
        or arrival.get("runwayTime", {}).get("utc")
    )

    dep_dt = parse_datetime_with_optional_z(dep_time)
    arr_dt = parse_datetime_with_optional_z(arr_time)
    if not dep_dt or not arr_dt:
        return None

    delta = arr_dt - dep_dt
    return delta.total_seconds()


def derive_average_flight_time(history_schedule):
    if not isinstance(history_schedule, list) or not history_schedule:
        return None

    durations = []
    for record in history_schedule:
        if not isinstance(record, dict):
            continue
        seconds = extract_flight_duration_seconds(record)
        if seconds is not None:
            durations.append(seconds)

    if not durations:
        return None

    average_seconds = sum(durations) / len(durations)
    return average_seconds


def build_report(flight_number, delay_stats, history_schedule):
    average_seconds = derive_average_flight_time(history_schedule)
    average_time_readable = seconds_to_readable(average_seconds)

    lines = []
    lines.append(f"Flight number: {flight_number}")
    if delay_stats and isinstance(delay_stats, dict):
        lines.append(f"Delay statistics found for: {delay_stats.get('number', flight_number)}")
    else:
        lines.append("Delay statistics: unavailable")

    if isinstance(history_schedule, list):
        lines.append(f"History/schedule records retrieved: {len(history_schedule)}")
    else:
        lines.append("History/schedule records: unavailable")

    lines.append(f"Average flight time: {average_time_readable}")
    return "\n".join(lines)


def main():
    delay_statistics = lookup_flight_delay_statistics(FLIGHT_NUMBER)
    history_and_schedule = lookup_flight_history_and_schedule(FLIGHT_NUMBER, DATE_FROM_LOCAL, DATE_TO_LOCAL)
    report = build_report(FLIGHT_NUMBER, delay_statistics, history_and_schedule)
    print(report)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Flights_Data_API.Flight_delays_by_flight_number import Flight_delays_by_flight_number
from Tools.Flights_Data_API.Get_Flight_history_and_Schedule import Get_Flight_history_and_Schedule

import traceback
from datetime import datetime, timedelta, UTC

FLIGHT_NUMBER = "NK2062"


def parse_hhmmss(duration_text):
    if not isinstance(duration_text, str) or not duration_text:
        return None
    try:
        negative = duration_text.startswith("-")
        text = duration_text[1:] if negative else duration_text
        parts = text.split(":")
        if len(parts) != 3:
            return None
        hours, minutes, seconds = map(int, parts)
        total_seconds = hours * 3600 + minutes * 60 + seconds
        return -total_seconds if negative else total_seconds
    except Exception:
        return None


def format_seconds_as_hhmmss(total_seconds):
    if total_seconds is None:
        return "Unknown"
    sign = "-" if total_seconds < 0 else ""
    total_seconds = abs(int(round(total_seconds)))
    hours = total_seconds // 3600
    minutes = (total_seconds % 3600) // 60
    seconds = total_seconds % 60
    return f"{sign}{hours:02d}:{minutes:02d}:{seconds:02d}"


def lookup_flight_delay_metrics(flight_number):
    try:
        return Flight_delays_by_flight_number(flight_number)
    except Exception:
        return None


def lookup_flight_history_and_schedule(flight_number):
    try:
        today = datetime.now(UTC).date()
        date_from = (today - timedelta(days=7)).strftime("%Y-%m-%d")
        date_to = today.strftime("%Y-%m-%d")
        return Get_Flight_history_and_Schedule(flight_number, date_from, date_to)
    except Exception:
        return None


def extract_average_flight_time(delay_metrics, flight_context):
    if not isinstance(delay_metrics, dict):
        delay_metrics = {}
    if not isinstance(flight_context, list):
        flight_context = []

    candidates = []
    for item in flight_context:
        if isinstance(item, dict):
            dep = item.get("departure", {})
            arr = item.get("arrival", {})
            dep_time = (dep.get("scheduledTime") or {}).get("utc")
            arr_time = (arr.get("scheduledTime") or {}).get("utc")
            if dep_time and arr_time:
                candidates.append((dep_time, arr_time))

    if candidates:
        durations = []
        for dep_time, arr_time in candidates:
            try:
                dep_dt = datetime.strptime(dep_time.replace("Z", ""), "%Y-%m-%d %H:%M")
                arr_dt = datetime.strptime(arr_time.replace("Z", ""), "%Y-%m-%d %H:%M")
                delta = arr_dt - dep_dt
                durations.append(delta.total_seconds())
            except Exception:
                continue
        if durations:
            avg_seconds = sum(durations) / len(durations)
            return format_seconds_as_hhmmss(avg_seconds)

    origins = delay_metrics.get("origins", [])
    destinations = delay_metrics.get("destinations", [])
    delays = []

    for group in (origins, destinations):
        if isinstance(group, list):
            for item in group:
                if isinstance(item, dict):
                    median_delay = item.get("medianDelay")
                    seconds = parse_hhmmss(median_delay)
                    if seconds is not None:
                        delays.append(seconds)

    if delays:
        avg_delay_seconds = sum(delays) / len(delays)
        return format_seconds_as_hhmmss(avg_delay_seconds)

    return "Unknown"


def derive_average_flight_time_from_metrics(delay_metrics, flight_context):
    return extract_average_flight_time(delay_metrics, flight_context)


def main():
    delay_metrics = lookup_flight_delay_metrics(FLIGHT_NUMBER)
    flight_context = lookup_flight_history_and_schedule(FLIGHT_NUMBER)
    average_flight_time = derive_average_flight_time_from_metrics(delay_metrics, flight_context)
    print(f"Average flight time of {FLIGHT_NUMBER}: {average_flight_time}")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

