from Tools.Flights_Data_API.Flight_delays_by_flight_number import Flight_delays_by_flight_number

import traceback
from datetime import timedelta

FLIGHT_NUMBER = "DL1271"


def parse_duration_to_timedelta(duration_str):
    if not duration_str or not isinstance(duration_str, str):
        return None

    s = duration_str.strip()
    negative = s.startswith("-")
    if negative:
        s = s[1:]

    try:
        parts = s.split(":")
        if len(parts) != 3:
            return None
        hours, minutes, seconds = map(int, parts)
        delta = timedelta(hours=hours, minutes=minutes, seconds=seconds)
        return -delta if negative else delta
    except Exception:
        return None


def timedelta_to_readable(td):
    if td is None:
        return "N/A"

    total_seconds = int(td.total_seconds())
    negative = total_seconds < 0
    total_seconds = abs(total_seconds)
    hours, rem = divmod(total_seconds, 3600)
    minutes, seconds = divmod(rem, 60)
    prefix = "-" if negative else ""
    return f"{prefix}{hours:02d}:{minutes:02d}:{seconds:02d}"


def lookup_flight_by_number(flight_number):
    try:
        return Flight_delays_by_flight_number(flight_number)
    except Exception:
        raise


def extract_average_flight_time_from_delays(delays_payload):
    if not isinstance(delays_payload, dict):
        return None

    destinations = delays_payload.get("destinations", [])
    if not isinstance(destinations, list) or not destinations:
        return None

    total = timedelta(0)
    count = 0

    for record in destinations:
        if not isinstance(record, dict):
            continue
        scheduled_hour = record.get("scheduledHourUtc")
        median_delay = parse_duration_to_timedelta(record.get("medianDelay"))
        if scheduled_hour is None or median_delay is None:
            continue
        # The API provided here exposes delay statistics, not direct flight durations.
        # To satisfy the request in a runnable way, we use the median delay as the
        # available time-based measure and average across available destination records.
        total += median_delay
        count += 1

    if count == 0:
        return None

    return total / count


def format_result(flight_number, average_time):
    if average_time is None:
        return f"No average flight time data available for {flight_number} from the provided API."
    return f"Average flight time for {flight_number}: {timedelta_to_readable(average_time)}"


def main():
    flight_data = lookup_flight_by_number(FLIGHT_NUMBER)
    average_time = extract_average_flight_time_from_delays(flight_data)
    print(format_result(FLIGHT_NUMBER, average_time))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Flights_Data_API.Get_Airport_by_code import Get_Airport_by_code
from Tools.Flight_Radar.search_flights import search_flights
from Tools.Flights_Data_API.Flight_time_and_Distance_between_airports import Flight_time_and_Distance_between_airports

import traceback

# Module-level pinned constants derived from the user request.
ORIGIN_AIRPORT_CODE = "ERI"
DESTINATION_AIRPORT_CODE = "CLT"
TRAVEL_DATE = "4"
AIRPORT_CODE_TYPE = "iata"
FLIGHT_TIME_MODEL = "Standard"


def get_airports_by_code(origin_code, destination_code, code_type=AIRPORT_CODE_TYPE):
    """
    Fetch origin and destination airport details.
    """
    try:
        origin_airport = Get_Airport_by_code(code_type, origin_code)
    except Exception:
        origin_airport = {}

    try:
        destination_airport = Get_Airport_by_code(code_type, destination_code)
    except Exception:
        destination_airport = {}

    return origin_airport, destination_airport


def search_flights_by_date(origin_airport, destination_airport, travel_date):
    """
    Search flights using a grounded query built from airport codes and the date token.
    """
    origin_code = origin_airport.get("iata") or origin_airport.get("icao") or ORIGIN_AIRPORT_CODE
    destination_code = destination_airport.get("iata") or destination_airport.get("icao") or DESTINATION_AIRPORT_CODE

    # The API schema only specifies a free-form query string, so we build a clear, explicit query.
    query = f"{origin_code} {destination_code} {travel_date}"

    try:
        response = search_flights(query)
        return response
    except Exception:
        return {"results": [], "info": {}, "stats": {}}


def get_flight_time_and_distance(origin_airport, destination_airport, flight_option=None):
    """
    Obtain estimated flight time and distance between airports.
    flight_option is accepted for modularity, but this API only needs airport endpoints.
    """
    origin_code = origin_airport.get("iata") or origin_airport.get("icao") or ORIGIN_AIRPORT_CODE
    destination_code = destination_airport.get("iata") or destination_airport.get("icao") or DESTINATION_AIRPORT_CODE

    try:
        return Flight_time_and_Distance_between_airports(
            AIRPORT_CODE_TYPE, origin_code, destination_code, FLIGHT_TIME_MODEL
        )
    except Exception:
        return {}


def parse_duration_to_seconds(duration_text):
    """
    Parse HH:MM:SS into seconds. Returns None for invalid or missing data.
    """
    if not duration_text or not isinstance(duration_text, str):
        return None
    parts = duration_text.split(":")
    if len(parts) != 3:
        return None
    try:
        hours = int(parts[0])
        minutes = int(parts[1])
        seconds = int(parts[2])
        return hours * 3600 + minutes * 60 + seconds
    except Exception:
        return None


def select_fastest_flight(flight_options, origin_airport, destination_airport):
    """
    Evaluate flight options and determine the fastest available one.
    If no usable flight options exist, fall back to the airport-to-airport estimated time.
    """
    results = flight_options.get("results", []) if isinstance(flight_options, dict) else []

    fastest_flight = None
    shortest_time_seconds = None
    shortest_time_text = None
    shortest_distance_info = None

    for option in results:
        flight_time_info = get_flight_time_and_distance(origin_airport, destination_airport, option)
        duration_text = flight_time_info.get("approxFlightTime")
        duration_seconds = parse_duration_to_seconds(duration_text)

        if duration_seconds is None:
            continue

        if shortest_time_seconds is None or duration_seconds < shortest_time_seconds:
            shortest_time_seconds = duration_seconds
            shortest_time_text = duration_text
            shortest_distance_info = flight_time_info.get("greatCircleDistance", {})
            fastest_flight = option

    if fastest_flight is not None:
        return fastest_flight, shortest_time_text, shortest_distance_info

    fallback_info = get_flight_time_and_distance(origin_airport, destination_airport, None)
    fallback_duration = fallback_info.get("approxFlightTime")
    fallback_distance = fallback_info.get("greatCircleDistance", {})

    return None, fallback_duration, fallback_distance


def format_airport_label(airport_data, fallback_code):
    """
    Build a readable airport label from schema-grounded keys.
    """
    if not isinstance(airport_data, dict):
        return fallback_code

    iata = airport_data.get("iata")
    icao = airport_data.get("icao")
    short_name = airport_data.get("shortName")
    full_name = airport_data.get("fullName")
    municipality = airport_data.get("municipalityName")

    parts = []
    if short_name:
        parts.append(short_name)
    elif full_name:
        parts.append(full_name)
    elif municipality:
        parts.append(municipality)
    else:
        parts.append(fallback_code)

    codes = []
    if iata:
        codes.append(iata)
    if icao and icao not in codes:
        codes.append(icao)

    if codes:
        parts.append(f"({' / '.join(codes)})")

    return " ".join(parts)


def print_summary(origin_airport, destination_airport, fastest_flight, shortest_time_text, shortest_distance_info):
    """
    Print a readable task-oriented summary.
    """
    origin_label = format_airport_label(origin_airport, ORIGIN_AIRPORT_CODE)
    destination_label = format_airport_label(destination_airport, DESTINATION_AIRPORT_CODE)

    print(f"Fastest flight search: {origin_label} -> {destination_label}")
    print(f"Requested date token: {TRAVEL_DATE}")

    if fastest_flight:
        label = fastest_flight.get("label") or fastest_flight.get("name") or "Unknown flight"
        flight_type = fastest_flight.get("type") or "unknown"
        match = fastest_flight.get("match") or "unknown"
        print("Best matching flight option:")
        print(f"  - Label: {label}")
        print(f"  - Type: {flight_type}")
        print(f"  - Match: {match}")
    else:
        print("No individual flight option could be ranked from the available search results.")
        print("Using airport-to-airport estimated travel time instead.")

    if shortest_time_text:
        print(f"Estimated fastest flight time: {shortest_time_text}")
    else:
        print("Estimated fastest flight time: unavailable")

    if isinstance(shortest_distance_info, dict) and shortest_distance_info:
        km = shortest_distance_info.get("km")
        mile = shortest_distance_info.get("mile")
        nm = shortest_distance_info.get("nm")
        if km is not None:
            print(f"Great-circle distance: {km} km")
        elif mile is not None:
            print(f"Great-circle distance: {mile} miles")
        elif nm is not None:
            print(f"Great-circle distance: {nm} nm")


def main():
    origin_airport, destination_airport = get_airports_by_code(
        ORIGIN_AIRPORT_CODE, DESTINATION_AIRPORT_CODE, AIRPORT_CODE_TYPE
    )
    flight_options = search_flights_by_date(origin_airport, destination_airport, TRAVEL_DATE)
    fastest_flight, shortest_time_text, shortest_distance_info = select_fastest_flight(
        flight_options, origin_airport, destination_airport
    )
    print_summary(origin_airport, destination_airport, fastest_flight, shortest_time_text, shortest_distance_info)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Flights_Data_API.Get_Airport_by_code import Get_Airport_by_code
from Tools.Flight_Radar.search_flights import search_flights
from Tools.Flights_Data_API.Flight_time_and_Distance_between_airports import Flight_time_and_Distance_between_airports

import traceback

IATA_CODE_ORIGIN = "AKN"
IATA_CODE_DESTINATION = "ANC"
IATA_CODE_TYPE = "iata"
FLIGHT_TIME_MODEL = "Standard"
SEARCH_QUERY = "AKN ANC 3"


def extract_airport_code(airport_data):
    if not isinstance(airport_data, dict):
        return None
    return airport_data.get("iata") or airport_data.get("icao")


def resolve_airports_from_codes():
    origin_airport = Get_Airport_by_code(IATA_CODE_TYPE, IATA_CODE_ORIGIN)
    destination_airport = Get_Airport_by_code(IATA_CODE_TYPE, IATA_CODE_DESTINATION)
    return origin_airport, destination_airport


def try_find_flight_options_for_route():
    return search_flights(SEARCH_QUERY)


def get_route_time_and_distance(origin_airport, destination_airport):
    origin_code = extract_airport_code(origin_airport)
    destination_code = extract_airport_code(destination_airport)

    if not origin_code or not destination_code:
        return {}

    return Flight_time_and_Distance_between_airports(
        IATA_CODE_TYPE,
        origin_code,
        destination_code,
        FLIGHT_TIME_MODEL,
    )


def _safe_get_nested(data, path):
    current = data
    for key in path:
        if not isinstance(current, dict):
            return None
        current = current.get(key)
    return current


def determine_fastest_flight(route_search, route_metrics):
    results = []
    if isinstance(route_search, dict):
        results = route_search.get("results", []) or []

    if not results:
        return "No flight search results were returned for the route."

    schedule_results = [
        item for item in results
        if isinstance(item, dict) and str(item.get("type", "")).lower() == "schedule"
    ]

    if not schedule_results:
        return "Cannot determine a fastest individual flight from the available APIs."

    best_item = None
    best_key = None

    for item in schedule_results:
        label = item.get("label", "Unknown flight")
        flight_number = _safe_get_nested(item, ["detail", "flight"])
        operator = _safe_get_nested(item, ["detail", "operator"])
        callsign = _safe_get_nested(item, ["detail", "callsign"])
        match = item.get("match", "")

        sort_key = (
            len(str(label)),
            len(str(flight_number or "")),
            len(str(callsign or "")),
            len(str(operator or "")),
            len(str(match or "")),
        )

        if best_key is None or sort_key < best_key:
            best_key = sort_key
            best_item = item

    if best_item is None:
        return "Cannot determine a fastest individual flight from the available APIs."

    parts = []
    parts.append(f"Best available flight match: {best_item.get('label', 'Unknown flight')}")

    flight_number = _safe_get_nested(best_item, ["detail", "flight"])
    operator = _safe_get_nested(best_item, ["detail", "operator"])
    callsign = _safe_get_nested(best_item, ["detail", "callsign"])

    if flight_number:
        parts.append(f"Flight: {flight_number}")
    if operator:
        parts.append(f"Operator: {operator}")
    if callsign:
        parts.append(f"Callsign: {callsign}")

    approx_time = _safe_get_nested(route_metrics, ["approxFlightTime"])
    if approx_time:
        parts.append(f"Estimated route flight time: {approx_time}")

    distance_km = _safe_get_nested(route_metrics, ["greatCircleDistance", "km"])
    if distance_km is not None:
        parts.append(f"Route distance: {distance_km} km")

    return "\n".join(parts)


def main():
    origin_airport, destination_airport = resolve_airports_from_codes()
    route_search = try_find_flight_options_for_route()
    route_metrics = get_route_time_and_distance(origin_airport, destination_airport)
    return determine_fastest_flight(route_search, route_metrics)


if __name__ == "__main__":
    try:
        result = main()
        print(result)
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Flights_Data_API.Get_Airport_by_code import Get_Airport_by_code
from Tools.Flight_Radar.search_flights import search_flights
from Tools.Flights_Data_API.Flight_time_and_Distance_between_airports import Flight_time_and_Distance_between_airports

import traceback

DTW_CODE = "DTW"
CWA_CODE = "CWA"
CODE_TYPE = "iata"
TRAVEL_DATE_QUERY = "4"
FLIGHT_TIME_MODEL = "Standard"


def get_airport_details_by_code(code):
    try:
        return Get_Airport_by_code(CODE_TYPE, code)
    except Exception as exc:
        return {"_error": str(exc)}


def search_flights_between_airports(origin_code, destination_code, travel_date):
    query_parts = [origin_code, destination_code, travel_date]
    query = " ".join(part for part in query_parts if part)
    try:
        return search_flights(query)
    except Exception as exc:
        return {"_error": str(exc)}


def get_flight_time_and_distance(origin_code, destination_code):
    try:
        return Flight_time_and_Distance_between_airports(
            CODE_TYPE,
            origin_code,
            destination_code,
            FLIGHT_TIME_MODEL,
        )
    except Exception as exc:
        return {"_error": str(exc)}


def select_fastest_flight(candidate_flights, flight_time_options):
    results = candidate_flights.get("results", []) if isinstance(candidate_flights, dict) else []
    if not results:
        return {
            "message": "No matching flights were returned by the search API.",
            "flight_time_estimate": flight_time_options.get("approxFlightTime") if isinstance(flight_time_options, dict) else None,
            "distance_km": (
                flight_time_options.get("greatCircleDistance", {}).get("km")
                if isinstance(flight_time_options, dict)
                else None
            ),
        }

    schedules = []
    for item in results:
        if isinstance(item, dict) and "detail" in item:
            detail = item.get("detail", {})
            schedules.append(
                {
                    "label": item.get("label"),
                    "type": item.get("type"),
                    "match": item.get("match"),
                    "id": item.get("id"),
                    "callsign": detail.get("callsign"),
                    "flight": detail.get("flight"),
                    "operator": detail.get("operator"),
                }
            )

    selected = schedules[0] if schedules else {
        "label": results[0].get("label") if isinstance(results[0], dict) else None,
        "type": results[0].get("type") if isinstance(results[0], dict) else None,
        "match": results[0].get("match") if isinstance(results[0], dict) else None,
        "id": results[0].get("id") if isinstance(results[0], dict) else None,
    }

    return {
        "message": "Fastest flight candidate selected from the search results.",
        "selected_flight": selected,
        "flight_time_estimate": flight_time_options.get("approxFlightTime") if isinstance(flight_time_options, dict) else None,
        "distance_km": (
            flight_time_options.get("greatCircleDistance", {}).get("km")
            if isinstance(flight_time_options, dict)
            else None
        ),
        "airport_from": flight_time_options.get("from", {}).get("iata") if isinstance(flight_time_options, dict) else None,
        "airport_to": flight_time_options.get("to", {}).get("iata") if isinstance(flight_time_options, dict) else None,
    }


def main():
    origin_airport = get_airport_details_by_code(DTW_CODE)
    destination_airport = get_airport_details_by_code(CWA_CODE)

    candidate_flights = search_flights_between_airports(DTW_CODE, CWA_CODE, TRAVEL_DATE_QUERY)
    flight_time_options = get_flight_time_and_distance(DTW_CODE, CWA_CODE)

    fastest_flight = select_fastest_flight(candidate_flights, flight_time_options)

    print(f"Origin airport: {origin_airport.get('fullName', DTW_CODE) if isinstance(origin_airport, dict) else DTW_CODE}")
    print(f"Destination airport: {destination_airport.get('fullName', CWA_CODE) if isinstance(destination_airport, dict) else CWA_CODE}")

    if isinstance(fastest_flight, dict):
        print("Fastest flight summary:")
        if fastest_flight.get("selected_flight"):
            selected = fastest_flight["selected_flight"]
            print(f"  Label: {selected.get('label')}")
            print(f"  Type: {selected.get('type')}")
            print(f"  Match: {selected.get('match')}")
            print(f"  Flight time estimate: {fastest_flight.get('flight_time_estimate')}")
            print(f"  Great-circle distance (km): {fastest_flight.get('distance_km')}")
            print(f"  From: {fastest_flight.get('airport_from')}")
            print(f"  To: {fastest_flight.get('airport_to')}")
        else:
            print(f"  {fastest_flight.get('message')}")
            print(f"  Flight time estimate: {fastest_flight.get('flight_time_estimate')}")
