import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Flights_Data_API.Get_Flight_status import Get_Flight_status
from Tools.Flights_Data_API.Flight_time_and_Distance_between_airports import Flight_time_and_Distance_between_airports
from Tools.Flights_Data_API.Flight_time_and_Distance_between_airports import Flight_time_and_Distance_between_airports

import traceback

FLIGHT_ID = "DL2993"
ORIGIN_AIRPORT_CODE = "GRB"
DESTINATION_AIRPORT_CODE = "ATL"
CODE_TYPE = "iata"
FLIGHT_TIME_MODEL = "Standard"


def lookup_flight_details(flight_id: str):
    try:
        return Get_Flight_status(flight_id)
    except Exception as exc:
        raise RuntimeError(f"Failed to lookup flight details for {flight_id}") from exc


def extract_airport_codes_from_flight_details(flight_details):
    if not isinstance(flight_details, list) or not flight_details:
        raise ValueError("Flight details response is empty or invalid")

    first_item = flight_details[0]
    departure = first_item.get("departure", {})
    arrival = first_item.get("arrival", {})
    departure_airport = departure.get("airport", {})
    arrival_airport = arrival.get("airport", {})

    origin_code = departure_airport.get("iata")
    destination_code = arrival_airport.get("iata")

    if not origin_code or not destination_code:
        raise ValueError("Could not extract airport codes from flight details")

    return origin_code, destination_code


def lookup_route_distance(code_type: str, code_from: str, code_to: str, flight_time_model: str = FLIGHT_TIME_MODEL):
    try:
        return Flight_time_and_Distance_between_airports(code_type, code_from, code_to, flight_time_model)
    except Exception as exc:
        raise RuntimeError(f"Failed to lookup route distance from {code_from} to {code_to}") from exc


def extract_distance_miles(route_metrics):
    if not isinstance(route_metrics, dict):
        raise ValueError("Route metrics response is empty or invalid")

    great_circle_distance = route_metrics.get("greatCircleDistance", {})
    distance_miles = great_circle_distance.get("mile")
    if distance_miles is None:
        raise ValueError("Could not extract distance in miles from route metrics")
    return float(distance_miles)


def extract_duration_minutes(flight_details):
    if not isinstance(flight_details, list) or not flight_details:
        raise ValueError("Flight details response is empty or invalid")

    first_item = flight_details[0]
    departure = first_item.get("departure", {})
    arrival = first_item.get("arrival", {})

    departure_time = departure.get("scheduledTime", {})
    arrival_time = arrival.get("scheduledTime", {})

    departure_utc = departure_time.get("utc")
    arrival_utc = arrival_time.get("utc")

    if not departure_utc or not arrival_utc:
        raise ValueError("Could not extract scheduled UTC times from flight details")

    from datetime import datetime

    time_format = "%Y-%m-%d %H:%MZ"
    departure_dt = datetime.strptime(departure_utc, time_format)
    arrival_dt = datetime.strptime(arrival_utc, time_format)

    duration_minutes = (arrival_dt - departure_dt).total_seconds() / 60.0
    if duration_minutes <= 0:
        raise ValueError("Computed non-positive duration from scheduled times")

    return duration_minutes


def compute_average_speed_miles_per_minute(distance_miles: float, duration_minutes: float):
    if duration_minutes <= 0:
        raise ValueError("Duration must be positive to compute average speed")
    return distance_miles / duration_minutes


def main():
    flight_details = lookup_flight_details(FLIGHT_ID)
    origin_code, destination_code = extract_airport_codes_from_flight_details(flight_details)

    route_metrics = lookup_route_distance(CODE_TYPE, origin_code, destination_code, FLIGHT_TIME_MODEL)
    distance_miles = extract_distance_miles(route_metrics)
    duration_minutes = extract_duration_minutes(flight_details)
    average_speed = compute_average_speed_miles_per_minute(distance_miles, duration_minutes)

    print(
        f"Average speed for {FLIGHT_ID} from {origin_code} to {destination_code}: "
        f"{average_speed:.4f} miles per minute"
    )


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

