from Tools.Flights_Data_API.Flight_time_and_Distance_between_airports import Flight_time_and_Distance_between_airports

import traceback

FLIGHT_NUMBER = "AA5272"
CODE_TYPE = "iata"
EXPECTED_ORIGIN_CODE = "GPT"
EXPECTED_DESTINATION_CODE = "CLT"
ROUTE_FLIGHT_TIME_MODEL = "Standard"


def get_flight_details_for_flight_number(flight_number):
    try:
        data = Get_Flight_status(flight_number)
        return data
    except Exception:
        raise


def extract_route_codes(flight_status):
    if not isinstance(flight_status, list) or not flight_status:
        return None, None

    first_record = flight_status[0]
    departure = first_record.get("departure", {})
    arrival = first_record.get("arrival", {})
    origin_code = departure.get("airport", {}).get("iata")
    destination_code = arrival.get("airport", {}).get("iata")
    return origin_code, destination_code


def get_airport_context(airport_code):
    try:
        return Get_Airport_by_code(CODE_TYPE, airport_code)
    except Exception:
        raise


def get_route_time_and_distance(origin_airport_code, destination_airport_code):
    try:
        return Flight_time_and_Distance_between_airports(
            CODE_TYPE,
            origin_airport_code,
            destination_airport_code,
            ROUTE_FLIGHT_TIME_MODEL,
        )
    except Exception:
        raise


def compute_average_speed(distance_miles, time_minutes):
    if time_minutes in (None, 0):
        return None
    return distance_miles / time_minutes


def extract_distance_and_time(route_metrics):
    distance_miles = None
    flight_time_minutes = None

    if isinstance(route_metrics, dict):
        great_circle_distance = route_metrics.get("greatCircleDistance", {})
        approx_flight_time = route_metrics.get("approxFlightTime")

        distance_miles = great_circle_distance.get("mile")

        if isinstance(approx_flight_time, str) and approx_flight_time:
            parts = approx_flight_time.split(":")
            if len(parts) == 3:
                try:
                    hours = int(parts[0])
                    minutes = int(parts[1])
                    seconds = int(parts[2])
                    flight_time_minutes = hours * 60 + minutes + seconds / 60.0
                except ValueError:
                    flight_time_minutes = None

    return distance_miles, flight_time_minutes


def format_result(average_speed):
    if average_speed is None:
        return "Average speed for AA5272 from GPT to CLT could not be calculated."
    return f"Average speed of AA5272 from GPT to CLT: {average_speed:.4f} miles per minute"


def main():
    flight_status = get_flight_details_for_flight_number(FLIGHT_NUMBER)
    origin_code, destination_code = extract_route_codes(flight_status)

    if origin_code is None or destination_code is None:
        print("Could not extract origin and destination airport codes from the flight status response.")
        return

    _ = get_airport_context(origin_code)
    _ = get_airport_context(destination_code)

    route_metrics = get_route_time_and_distance(origin_code, destination_code)
    distance_miles, flight_time_minutes = extract_distance_and_time(route_metrics)
    average_speed = compute_average_speed(distance_miles, flight_time_minutes)

    print(format_result(average_speed))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

