from Tools.Flights_Data_API.Get_Flight_status import Get_Flight_status
from Tools.Flights_Data_API.Get_Airport_by_code import Get_Airport_by_code
from Tools.Flights_Data_API.Flight_time_and_Distance_between_airports import Flight_time_and_Distance_between_airports

import traceback
from datetime import datetime

FLIGHT_ID = "DL4130"
ORIGIN_AIRPORT_CODE_TYPE = "iata"
ORIGIN_AIRPORT_CODE = "HPN"
DESTINATION_AIRPORT_CODE_TYPE = "iata"
DESTINATION_AIRPORT_CODE = "DTW"
FLIGHT_TIME_MODEL = "Standard"


def get_flight_identifier(flight_id):
    try:
        data = Get_Flight_status(flight_id)
        return data
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve flight status for {flight_id}: {exc}") from exc


def validate_airport_codes(origin_code_type, origin_code, destination_code_type, destination_code):
    try:
        origin_airport_data = Get_Airport_by_code(origin_code_type, origin_code)
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve origin airport data for {origin_code}: {exc}") from exc

    try:
        destination_airport_data = Get_Airport_by_code(destination_code_type, destination_code)
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve destination airport data for {destination_code}: {exc}") from exc

    return origin_airport_data, destination_airport_data


def get_flight_route_and_timing(origin_airport_data, destination_airport_data, code_type, flight_time_model):
    try:
        origin_code = origin_airport_data.get("iata") if code_type == "iata" else origin_airport_data.get("icao")
        destination_code = destination_airport_data.get("iata") if code_type == "iata" else destination_airport_data.get("icao")
        if not origin_code or not destination_code:
            raise ValueError("Missing airport code in airport data.")
        route_metrics = Flight_time_and_Distance_between_airports(
            code_type, origin_code, destination_code, flight_time_model
        )
        return route_metrics
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve route metrics between airports: {exc}") from exc


def compute_average_speed(route_metrics):
    great_circle_distance = route_metrics.get("greatCircleDistance", {})
    distance_miles = great_circle_distance.get("mile")
    approx_flight_time = route_metrics.get("approxFlightTime")

    if distance_miles is None:
        raise ValueError("Route metrics missing greatCircleDistance.mile.")
    if not approx_flight_time:
        raise ValueError("Route metrics missing approxFlightTime.")

    try:
        hours_str, minutes_str, seconds_str = approx_flight_time.split(":")
        total_minutes = int(hours_str) * 60 + int(minutes_str) + int(seconds_str) / 60.0
        if total_minutes <= 0:
            raise ValueError("Computed flight time must be positive.")
        return distance_miles / total_minutes
    except Exception as exc:
        raise ValueError(f"Unable to compute average speed from approxFlightTime '{approx_flight_time}': {exc}") from exc


def format_output(speed_miles_per_minute):
    print(f"Average speed of {FLIGHT_ID} from {ORIGIN_AIRPORT_CODE} to {DESTINATION_AIRPORT_CODE}: {speed_miles_per_minute:.4f} miles per minute")


def main():
    flight_data = get_flight_identifier(FLIGHT_ID)
    if not flight_data:
        raise RuntimeError(f"No flight data returned for {FLIGHT_ID}.")

    origin_airport_data, destination_airport_data = validate_airport_codes(
        ORIGIN_AIRPORT_CODE_TYPE,
        ORIGIN_AIRPORT_CODE,
        DESTINATION_AIRPORT_CODE_TYPE,
        DESTINATION_AIRPORT_CODE,
    )

    route_metrics = get_flight_route_and_timing(
        origin_airport_data,
        destination_airport_data,
        ORIGIN_AIRPORT_CODE_TYPE,
        FLIGHT_TIME_MODEL,
    )

    average_speed = compute_average_speed(route_metrics)
    format_output(average_speed)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

