    data = api_response.get("data", [])
    if isinstance(data, list):
        return data
    return []


def build_search_query(business_name, postal_code):
    return f"{business_name} in {postal_code}"


def search_businesses_in_postal_code(postal_code):
    query = build_search_query(BUSINESS_NAME, postal_code)
    response = Search(query)
    return extract_data_list(response)


def select_matching_business(search_results, business_name, postal_code):
    postal_code_str = str(postal_code)
    normalized_name = business_name.lower()

    best_match = None
    for item in search_results:
        if not isinstance(item, dict):
            continue

        name = str(item.get("name", "")).lower()
        address = str(item.get("full_address", ""))
        zipcode = str(item.get("zipcode", ""))

        name_match = normalized_name in name or name in normalized_name
        postal_match = postal_code_str in zipcode or postal_code_str in address

        if name_match and postal_match:
            return item

        if name_match and best_match is None:
            best_match = item

    return best_match


def get_business_address(business_id, region):
    response = Business_Details(business_id, region)
    data_list = extract_data_list(response)
    if not data_list:
        return None

    business = data_list[0]
    if not isinstance(business, dict):
        return None

    address = business.get("full_address")
    if address:
        return address

    return business.get("address")


def get_address_for_seven_eleven_in_postal_code(postal_code):
    search_results = search_businesses_in_postal_code(postal_code)
    matched_business = select_matching_business(search_results, BUSINESS_NAME, postal_code)

    if matched_business is None or not isinstance(matched_business, dict):
        return None

    business_id = matched_business.get("business_id") or matched_business.get("google_id")
    if not business_id:
        return matched_business.get("full_address") or matched_business.get("address")

    address = get_business_address(business_id, REGION)
    if address:
        return address

    return matched_business.get("full_address") or matched_business.get("address")


def main():
    address = get_address_for_seven_eleven_in_postal_code(POSTAL_CODE)
    if address:
        print(address)
    else:
