from Tools.Local_Business_Data.Search import Search
from Tools.Local_Business_Data.Business_Details import Business_Details

import traceback

POSTAL_CODE = "08103"
BUSINESS_NAME = "Domino's Pizza"
REGION = "us"


def extract_businesses_from_search(search_response):
    if not isinstance(search_response, dict):
        return []
    return search_response.get("data", []) or []


def is_dominos_match(business):
    name = str(business.get("name", "") or "").lower()
    address = str(business.get("full_address", "") or "").lower()
    business_type = str(business.get("type", "") or "").lower()
    subtypes = business.get("subtypes", []) or []

    dominos_tokens = ["domino", "domino's"]
    pizza_tokens = ["pizza"]

    name_match = any(token in name for token in dominos_tokens) and any(
        token in name for token in pizza_tokens
    )
    address_match = any(token in address for token in dominos_tokens)
    type_match = "pizza" in business_type or any(
        "pizza" in str(item).lower() for item in subtypes
    )

    return name_match or address_match or type_match


def score_business_for_postal_code(business, postal_code):
    full_address = str(business.get("full_address", "") or "").lower()
    address = str(business.get("address", "") or "").lower()
    zipcode = str(business.get("zipcode", "") or "").strip().lower()

    score = 0
    if postal_code.lower() in full_address:
        score += 3
    if postal_code.lower() in address:
        score += 3
    if zipcode == postal_code.lower():
        score += 5
    if is_dominos_match(business):
        score += 10
    return score


def select_relevant_listing(search_results, postal_code):
    businesses = extract_businesses_from_search(search_results)
    if not businesses:
        return None

    ranked = sorted(
        businesses,
        key=lambda b: score_business_for_postal_code(b, postal_code),
        reverse=True,
    )
    return ranked[0] if ranked else None


def get_business_address(listing):
    if not isinstance(listing, dict):
        return None

    business_id = listing.get("business_id")
    if not business_id:
        return listing.get("full_address") or listing.get("address")

    details_response = Business_Details(business_id, REGION)
    if isinstance(details_response, dict):
        data = details_response.get("data", []) or []
        if data and isinstance(data[0], dict):
            return data[0].get("full_address") or data[0].get("address")
    return listing.get("full_address") or listing.get("address")


def search_dominos_in_postal_area(postal_code):
    query = f"{BUSINESS_NAME} in {postal_code}"
    return Search(query)


def main():
    search_results = search_dominos_in_postal_area(POSTAL_CODE)
    relevant_listing = select_relevant_listing(search_results, POSTAL_CODE)

    if not relevant_listing:
        print("No Domino's Pizza listing found for postal code 08103.")
        return

    address = get_business_address(relevant_listing)
    if address:
        print(f"Domino's Pizza address in postal code {POSTAL_CODE}: {address}")
    else:
        print(f"Domino's Pizza listing found for postal code {POSTAL_CODE}, but no address was available.")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

