def normalize_text(value):
    if value is None:
        return ""
    return str(value).strip().lower()


def select_matching_business_record(search_results):
    data = search_results.get("data", []) if isinstance(search_results, dict) else []
    target = normalize_text(BUSINESS_NAME_TARGET)

    if not data:
        return None

    best_match = None
    for record in data:
        name = normalize_text(record.get("name"))
        full_address = normalize_text(record.get("full_address"))
        city = normalize_text(record.get("city"))
        state = normalize_text(record.get("state"))

        if target in name:
            best_match = record
            break

        if target in full_address:
            best_match = record
            break

        if "francis" in name and "barber" in name:
            best_match = record

        if "pa" in state or "pennsylvania" in full_address:
            if best_match is None:
                best_match = record

        if "pa" in city:
            if best_match is None:
                best_match = record

    return best_match if best_match is not None else data[0]


def fetch_business_details(business_identifier):
    if not business_identifier:
        return {}
    business_id = business_identifier.get("business_id")
    if not business_id:
        return {}
    try:
        return Business_Details(business_id, REGION)
    except Exception as exc:
        raise RuntimeError(f"Business_Details API failed: {exc}") from exc


def extract_city_from_location(business_details):
    data = business_details.get("data", []) if isinstance(business_details, dict) else []
    if not data:
        return "Unknown"

    record = data[0] if isinstance(data[0], dict) else {}
    city = record.get("city")
    if city:
        return city

    full_address = record.get("full_address", "")
    if isinstance(full_address, str) and full_address:
        parts = [part.strip() for part in full_address.split(",")]
        if len(parts) >= 2:
            return parts[-2]

    return "Unknown"


def main():
    search_results = search_business_in_pa()
    business_identifier = select_matching_business_record(search_results)
    business_details = fetch_business_details(business_identifier)

    if not business_details and business_identifier:
        city_name = business_identifier.get("city") or "Unknown"
    else:
        city_name = extract_city_from_location(business_details)

    print(city_name)


