def search_business_by_name():
    try:
        return Search(TARGET_BUSINESS_NAME)
    except Exception as e:
        raise RuntimeError(f"Search failed for '{TARGET_BUSINESS_NAME}': {e}")


def select_target_business(search_results):
    data = search_results.get("data", []) if isinstance(search_results, dict) else []
    if not data:
        return None, None

    target_lower = TARGET_BUSINESS_NAME.lower()
    hint_lower = TARGET_LOCATION_HINT.lower()

    best = None
    for item in data:
        name = str(item.get("name", "")).lower()
        full_address = str(item.get("full_address", "")).lower()
        city = str(item.get("city", "")).lower()

        if target_lower in name:
            if hint_lower in full_address or hint_lower in city:
                return item.get("business_id"), item.get("place_id")
            if best is None:
                best = item

    if best is None:
        best = data[0]

    return best.get("business_id"), best.get("place_id")


def fetch_place_info(business_identifier, location_reference=None):
    if business_identifier:
        try:
            return Place_info(business_identifier)
        except Exception:
            pass

    if location_reference:
        try:
            return Place_info(location_reference)
        except Exception as e:
            raise RuntimeError(f"Place_info failed for both business_id and place_id: {e}")

    raise RuntimeError("No valid business identifier or location reference found.")


def extract_city_from_place_details(place_details):
    data = place_details.get("data", []) if isinstance(place_details, dict) else []
    if not data:
        return None

    item = data[0]

    city = item.get("city")
    if city:
        return city

    full_address = str(item.get("full_address", ""))
    parts = [p.strip() for p in full_address.split(",") if p.strip()]
    if len(parts) >= 2:
        return parts[-2]

    return None


def main():
    search_results = search_business_by_name()
    business_identifier, location_reference = select_target_business(search_results)
    place_details = fetch_place_info(business_identifier, location_reference)
    city = extract_city_from_place_details(place_details)

    if city:
        print(city)
    else:
        print("City not found.")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

