from Tools.Maps_Data.Search import Search
from Tools.Maps_Data.Place_info import Place_info

import traceback

QUERY_BUSINESS_NAME = "Fence USA"
TARGET_BUSINESS_NAME = "Fence USA"


def search_business_by_name(business_name):
    try:
        return Search(business_name)
    except Exception:
        raise


def select_matching_business(search_results, target_name):
    data = search_results.get("data", [])
    if not isinstance(data, list) or not data:
        return None

    target_lower = str(target_name).lower()
    for business in data:
        name = str(business.get("name", ""))
        if target_lower in name.lower():
            return business.get("business_id")

    first_business = data[0] if data else None
    if isinstance(first_business, dict):
        return first_business.get("business_id")
    return None


def get_place_info(business_identifier):
    if not business_identifier:
        return {"data": []}
    try:
        return Place_info(business_identifier)
    except Exception:
        raise


def extract_state_from_place_details(place_details):
    data = place_details.get("data", [])
    if not isinstance(data, list) or not data:
        return None

    place = data[0]
    if not isinstance(place, dict):
        return None

    state_value = place.get("state")
    if state_value:
        return state_value

    full_address = str(place.get("full_address", ""))
    return parse_state_from_address(full_address)


def parse_state_from_address(full_address):
    if not full_address:
        return None

    parts = [part.strip() for part in full_address.split(",") if part.strip()]
    if not parts:
        return None

    for part in reversed(parts):
        if len(part) == 2 and part.isalpha():
            return part.upper()

    return parts[-1] if parts else None


def main():
    search_results = search_business_by_name(QUERY_BUSINESS_NAME)
    business_identifier = select_matching_business(search_results, TARGET_BUSINESS_NAME)
    place_details = get_place_info(business_identifier)
    state_value = extract_state_from_place_details(place_details)
    print(state_value if state_value else "State not found")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

