from Tools.Local_Business_Data.Search import Search
from Tools.Local_Business_Data.Business_Details import Business_Details

import traceback

QUERY_ARBYS_TROY_IL = "Arby's in Troy, IL"
TARGET_NAME_KEYWORD = "arbys"
TARGET_CITY_KEYWORD = "troy"
TARGET_STATE_KEYWORD = "illinois"
TARGET_REGION = "us"


def normalize_text(value):
    return str(value or "").strip().lower()


def extract_data_list(response):
    if not isinstance(response, dict):
        return []
    data = response.get("data", [])
    return data if isinstance(data, list) else []


def is_target_business(record):
    name = normalize_text(record.get("name"))
    city = normalize_text(record.get("city"))
    state = normalize_text(record.get("state"))
    full_address = normalize_text(record.get("full_address"))
    address = normalize_text(record.get("address"))

    name_match = TARGET_NAME_KEYWORD in name
    city_match = TARGET_CITY_KEYWORD in city or TARGET_CITY_KEYWORD in full_address or TARGET_CITY_KEYWORD in address
    state_match = TARGET_STATE_KEYWORD in state or "il" in state or ", il" in full_address or ", il" in address

    return name_match and city_match and state_match


def search_business(query):
    try:
        return Search(query)
    except Exception:
        return {"data": []}


def select_target_business(search_response):
    results = extract_data_list(search_response)
    for record in results:
        if isinstance(record, dict) and is_target_business(record):
            return record
    return results[0] if results and isinstance(results[0], dict) else {}


def get_business_details(business_id, region):
    try:
        return Business_Details(business_id, region)
    except Exception:
        return {"data": []}


def extract_postal_code_from_details(details_response):
    results = extract_data_list(details_response)
    if not results:
        return None

    record = results[0] if isinstance(results[0], dict) else {}
    for key in ("zipcode", "postal_code", "zip"):
        value = record.get(key)
        if value:
            return str(value).strip()

    address = normalize_text(record.get("full_address") or record.get("address"))
    if address:
        parts = address.split()
        for part in reversed(parts):
            if part.isdigit() and len(part) == 5:
                return part
            if len(part) == 10 and part[:5].isdigit() and part[5] == "-":
                return part[:5]
    return None


def main():
    search_response = search_business(QUERY_ARBYS_TROY_IL)
    target_business = select_target_business(search_response)
    business_id = target_business.get("business_id") or target_business.get("google_id") or target_business.get("place_id")

    if business_id:
        details_response = get_business_details(business_id, TARGET_REGION)
        postal_code = extract_postal_code_from_details(details_response)
        if postal_code:
            print(postal_code)
            return

    for record in extract_data_list(search_response):
        if isinstance(record, dict):
            for key in ("zipcode", "postal_code", "zip"):
                value = record.get(key)
                if value:
                    print(str(value).strip())
                    return

    print("Postal code not found")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

