def normalize_text(value):
    if value is None:
        return ""
    return str(value).strip().lower()


def select_matching_business(search_results, business_name, postal_code, city, state):
    data = search_results.get("data", []) if isinstance(search_results, dict) else []
    target_name = normalize_text(business_name)
    target_zip = normalize_text(postal_code)
    target_city = normalize_text(city)
    target_state = normalize_text(state)

    if not data:
        return None

    best_match = None
    for item in data:
        name = normalize_text(item.get("name"))
        zipcode = normalize_text(item.get("zipcode"))
        item_city = normalize_text(item.get("city"))
        item_state = normalize_text(item.get("state"))

        name_match = target_name in name or name in target_name
        location_match = (target_zip in zipcode or zipcode in target_zip) and (
            target_city in item_city or item_city in target_city
        ) and (target_state in item_state or item_state in target_state)

        if name_match and location_match:
            return item

        if name_match:
            best_match = item

    return best_match


def get_business_details(business_id, region):
    try:
        return Business_Details(business_id, region)
    except Exception:
        raise


def extract_star_rating_from_search_item(item):
    if not isinstance(item, dict):
        return None
    rating = item.get("rating")
    if rating is not None:
        return rating
    hotel_stars = item.get("hotel_stars")
    if hotel_stars is not None:
        return hotel_stars
    return None


def extract_business_id(item):
    if not isinstance(item, dict):
        return None
    return item.get("business_id") or item.get("google_id") or item.get("place_id")


def extract_star_rating_from_details(details):
    data = details.get("data", []) if isinstance(details, dict) else []
    if not data:
        return None
    item = data[0] if isinstance(data[0], dict) else {}
    rating = item.get("rating")
    if rating is not None:
        return rating
    hotel_stars = item.get("hotel_stars")
    if hotel_stars is not None:
        return hotel_stars
    return None


def main():
    search_results = search_business(SEARCH_QUERY)
    matched_business = select_matching_business(search_results, BUSINESS_NAME, POSTAL_CODE, CITY, STATE)

    if matched_business is None:
        print("No matching business found.")
        return

    business_id = extract_business_id(matched_business)
    if not business_id:
        star_rating = extract_star_rating_from_search_item(matched_business)
        if star_rating is None:
            print("Star rating not available.")
        else:
            print(f"Star rating for {BUSINESS_NAME}: {star_rating}")
        return

    details = get_business_details(business_id, REGION)
    star_rating = extract_star_rating_from_details(details)

    if star_rating is None:
        star_rating = extract_star_rating_from_search_item(matched_business)

    if star_rating is None:
        print("Star rating not available.")
    else:
        print(f"Star rating for {BUSINESS_NAME}: {star_rating}")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
