from Tools.Local_Business_Data.Search import Search
from Tools.Local_Business_Data.Business_Details import Business_Details
from Tools.Local_Business_Data.Business_Reviews import Business_Reviews

import traceback

# Module-level pinned constants
BUSINESS_NAME_QUERY = "Le Onde Ristorante 19027, Elkins Park, PA"
TARGET_BUSINESS_NAME = "Le Onde Ristorante"
TARGET_LOCATION_HINT = "19027, Elkins Park, PA"
REGION_US = "us"
SEARCH_LIMIT = 10


def search_business_in_area():
    try:
        return Search(BUSINESS_NAME_QUERY)
    except Exception as exc:
        raise RuntimeError(f"Search failed: {exc}") from exc


def normalize_text(value):
    if value is None:
        return ""
    return str(value).strip().lower()


def select_correct_business_entry(search_results):
    data = search_results.get("data", [])
    if not isinstance(data, list):
        data = []

    target_name_norm = normalize_text(TARGET_BUSINESS_NAME)
    target_location_norm = normalize_text(TARGET_LOCATION_HINT)

    for entry in data:
        name = normalize_text(entry.get("name"))
        full_address = normalize_text(entry.get("full_address"))
        address = normalize_text(entry.get("address"))
        city = normalize_text(entry.get("city"))
        state = normalize_text(entry.get("state"))
        zipcode = normalize_text(entry.get("zipcode"))

        location_blob = " ".join([full_address, address, city, state, zipcode])

        if target_name_norm in name and (
            target_location_norm in location_blob or "elkins park" in location_blob or "19027" in location_blob
        ):
            return entry.get("business_id")

    for entry in data:
        name = normalize_text(entry.get("name"))
        if target_name_norm in name:
            return entry.get("business_id")

    return None


def get_business_details(business_identifier):
    if not business_identifier:
        return {}
    try:
        return Business_Details(business_identifier, REGION_US)
    except Exception as exc:
        raise RuntimeError(f"Business_Details failed: {exc}") from exc


def get_business_reviews(business_identifier):
    if not business_identifier:
        return {}
    try:
        return Business_Reviews(business_identifier)
    except Exception as exc:
        raise RuntimeError(f"Business_Reviews failed: {exc}") from exc


def extract_review_count(search_results, business_details, reviews_data):
    for payload in (business_details, search_results):
        data = payload.get("data", [])
        if isinstance(data, list) and data:
            first = data[0]
            review_count = first.get("review_count")
            if review_count is not None:
                return review_count

    data = reviews_data.get("data", [])
    if isinstance(data, list):
        return len(data)

    return 0


def main():
    search_results = search_business_in_area()
    business_identifier = select_correct_business_entry(search_results)

    if business_identifier is None:
        print(f"Could not find a matching business for '{TARGET_BUSINESS_NAME}' in '{TARGET_LOCATION_HINT}'.")
        return

    business_details = get_business_details(business_identifier)
    reviews_data = get_business_reviews(business_identifier)
    review_count = extract_review_count(search_results, business_details, reviews_data)

    print(f"{TARGET_BUSINESS_NAME} received {review_count} reviews in the area with postal code 19027, Elkins Park, PA.")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

