from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Local_Business_Data.Search import Search
from Tools.Local_Business_Data.Business_Details import Business_Details

import traceback

QUERY = "Rural King, 62226, Swansea, IL"
REGION = "us"
TARGET_NAME = "rural king"
TARGET_POSTAL_CODE = "62226"
TARGET_CITY = "swansea"
TARGET_STATE = "illinois"


def normalize_text(value):
    if value is None:
        return ""
    return str(value).strip().lower()


def get_search_results():
    try:
        return Search(QUERY)
    except Exception:
        raise


def extract_data_list(response):
    if not isinstance(response, dict):
        return []
    data = response.get("data", [])
    if isinstance(data, list):
        return data
    return []


def matches_target_business(item):
    name = normalize_text(item.get("name"))
    full_address = normalize_text(item.get("full_address"))
    address = normalize_text(item.get("address"))
    city = normalize_text(item.get("city"))
    state = normalize_text(item.get("state"))
    zipcode = normalize_text(item.get("zipcode"))

    name_match = TARGET_NAME in name
    postal_match = TARGET_POSTAL_CODE in full_address or TARGET_POSTAL_CODE in address or zipcode == TARGET_POSTAL_CODE
    city_match = TARGET_CITY in full_address or city == TARGET_CITY
    state_match = TARGET_STATE in full_address or state == TARGET_STATE

    return name_match and postal_match and city_match and state_match


def select_matching_listing(search_results):
    data = extract_data_list(search_results)
    for item in data:
        if matches_target_business(item):
            business_id = item.get("business_id") or item.get("google_id")
            return business_id, item
    for item in data:
        name = normalize_text(item.get("name"))
        if TARGET_NAME in name:
            business_id = item.get("business_id") or item.get("google_id")
            return business_id, item
    return None, None


def get_business_details(business_id):
    if not business_id:
        return None
    try:
        return Business_Details(business_id, REGION)
    except Exception:
        raise


def extract_star_rating(business_details):
    data = extract_data_list(business_details)
    if not data:
        return None
    return data[0].get("rating")


def format_output(rating, listing):
    if rating is None:
        print("Star rating for Rural King in 62226, Swansea, IL: not found")
        return

    location = ""
    if isinstance(listing, dict):
        location = listing.get("full_address") or listing.get("address") or ""
    if location:
        print(f"Star rating for Rural King in 62226, Swansea, IL ({location}): {rating}")
    else:
        print(f"Star rating for Rural King in 62226, Swansea, IL: {rating}")


def main():
    search_results = get_search_results()
    business_id, listing = select_matching_listing(search_results)

    if not business_id:
        rating = None
    else:
        business_details = get_business_details(business_id)
        rating = extract_star_rating(business_details)

    format_output(rating, listing)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

