from Tools.Local_Business_Data.Search import Search
from Tools.Local_Business_Data.Business_Details import Business_Details

import traceback

POSTAL_CODE = "19153"
CITY = "Philadelphia"
STATE = "PA"
REGION = "us"
BUSINESS_NAME = "Red Mango"
SEARCH_QUERY = f"{BUSINESS_NAME} in {POSTAL_CODE} {CITY}, {STATE}"


def search_business(query):
    try:
        return Search(query)
    except Exception as exc:
        raise RuntimeError(f"Search API call failed for query={query!r}") from exc


def find_best_matching_business(search_response):
    data = search_response.get("data", [])
    if not isinstance(data, list):
        return None

    target_city = CITY.lower()
    target_state = STATE.lower()
    target_zip = POSTAL_CODE.lower()
    target_name = BUSINESS_NAME.lower()

    for item in data:
        if not isinstance(item, dict):
            continue
        name = str(item.get("name", "")).lower()
        full_address = str(item.get("full_address", "")).lower()
        address = str(item.get("address", "")).lower()
        zipcode = str(item.get("zipcode", "")).lower()
        city = str(item.get("city", "")).lower()
        state = str(item.get("state", "")).lower()

        if target_name in name and (
            target_zip in full_address
            or target_zip in address
            or target_zip == zipcode
        ) and (
            target_city in full_address
            or target_city == city
        ) and (
            target_state in full_address
            or target_state == state
        ):
            return item

    for item in data:
        if not isinstance(item, dict):
            continue
        name = str(item.get("name", "")).lower()
        if target_name in name:
            return item

    return data[0] if data else None


def fetch_business_details(business_id):
    try:
        return Business_Details(business_id, REGION)
    except Exception as exc:
        raise RuntimeError(f"Business_Details API call failed for business_id={business_id!r}") from exc


def extract_star_rating(details_response):
    data = details_response.get("data", [])
    if isinstance(data, list) and data:
        first = data[0]
        if isinstance(first, dict):
            return first.get("rating", None)
    return None


def get_red_mango_star_rating():
    search_response = search_business(SEARCH_QUERY)
    matched_business = find_best_matching_business(search_response)

    if not matched_business:
        return None

    business_id = matched_business.get("business_id") or matched_business.get("place_id")
    if not business_id:
        return matched_business.get("rating", None)

    details_response = fetch_business_details(business_id)
    rating = extract_star_rating(details_response)

    if rating is None:
        rating = matched_business.get("rating", None)

    return rating


def main():
    rating = get_red_mango_star_rating()
    if rating is None:
        print(f"No star rating found for {BUSINESS_NAME} in {POSTAL_CODE}, {CITY}, {STATE}.")
    else:
        print(f"Star rating of {BUSINESS_NAME} in {POSTAL_CODE}, {CITY}, {STATE}: {rating}")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

