from Tools.Local_Business_Data.Search import Search
from Tools.Local_Business_Data.Business_Details import Business_Details

import traceback

POSTAL_CODE = "19341"
AREA_NAME = "Exton, PA"
BUSINESS_NAME = "Iron Hill Brewery TapHouse"
SEARCH_QUERY = f"{BUSINESS_NAME} {POSTAL_CODE} {AREA_NAME}"
REGION = "us"


def search_business_in_area(postal_code, area_name, business_name):
    query = f"{business_name} {postal_code} {area_name}"
    try:
        return Search(query)
    except Exception as e:
        raise RuntimeError(f"Search API failed for query='{query}': {e}")


def select_target_business(search_results):
    data = search_results.get("data", []) if isinstance(search_results, dict) else []
    if not data:
        return None

    name_tokens = BUSINESS_NAME.lower().split()
    area_tokens = [POSTAL_CODE.lower()] + AREA_NAME.lower().replace(",", "").split()

    best_match = None
    best_score = -1

    for item in data:
        if not isinstance(item, dict):
            continue
        name = str(item.get("name", "")).lower()
        full_address = str(item.get("full_address", "")).lower()
        address = str(item.get("address", "")).lower()
        city = str(item.get("city", "")).lower()
        zipcode = str(item.get("zipcode", "")).lower()

        score = 0
        if all(token in name for token in name_tokens):
            score += 3
        if any(token in full_address for token in area_tokens):
            score += 2
        if any(token in address for token in area_tokens):
            score += 1
        if POSTAL_CODE.lower() in zipcode:
            score += 2
        if "exton" in full_address or "exton" in city:
            score += 1

        if score > best_score:
            best_score = score
            best_match = item

    return best_match.get("business_id") if isinstance(best_match, dict) else None


def get_business_details(business_identifier):
    if not business_identifier:
        return None
    try:
        return Business_Details(business_identifier, REGION)
    except Exception as e:
        raise RuntimeError(f"Business_Details API failed for business_id='{business_identifier}': {e}")


def extract_review_count(business_details):
    data = business_details.get("data", []) if isinstance(business_details, dict) else []
    if not data:
        return None

    first = data[0] if isinstance(data[0], dict) else {}
    return first.get("review_count")


def main():
    search_results = search_business_in_area(POSTAL_CODE, AREA_NAME, BUSINESS_NAME)
    business_identifier = select_target_business(search_results)

    if not business_identifier:
        print(f"No matching business found for '{BUSINESS_NAME}' in {POSTAL_CODE}, {AREA_NAME}.")
        return

    business_details = get_business_details(business_identifier)
    review_count = extract_review_count(business_details)

    if review_count is None:
        print(f"Review count not available for '{BUSINESS_NAME}'.")
    else:
        print(f"{BUSINESS_NAME} received {review_count} reviews in {POSTAL_CODE}, {AREA_NAME}.")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Local_Business_Data.Search import Search
from Tools.Local_Business_Data.Business_Details import Business_Details

import traceback

# Module-level constants pinned from the user requirement.
TARGET_BUSINESS_NAME = "Westampton Family Diner"
TARGET_AREA_QUERY = "Westampton Family Diner 08060, Mount Holly, NJ"
TARGET_REGION = "us"
TARGET_POSTAL_CODE = "08060"
TARGET_CITY = "Mount Holly"
TARGET_STATE = "NJ"

def search_business_by_area():
    try:
        return Search(TARGET_AREA_QUERY)
    except Exception as exc:
        print(f"Search API error: {exc}", file=sys.stderr)
        return None

def select_matched_business(search_response):
    if not isinstance(search_response, dict):
        return None

    data = search_response.get("data", [])
    if not isinstance(data, list) or not data:
        return None

    target_name = TARGET_BUSINESS_NAME.casefold()
    best_match = None

    for item in data:
        if not isinstance(item, dict):
            continue
        name = str(item.get("name", "")).casefold()
        full_address = str(item.get("full_address", "")).casefold()
        address = str(item.get("address", "")).casefold()
        city = str(item.get("city", "")).casefold()
        state = str(item.get("state", "")).casefold()
        zipcode = str(item.get("zipcode", "")).casefold()

        if target_name in name:
            if TARGET_POSTAL_CODE in full_address or TARGET_POSTAL_CODE in address or zipcode == TARGET_POSTAL_CODE.casefold():
                best_match = item
                break
            if TARGET_CITY.casefold() in city or TARGET_STATE.casefold() in state:
                best_match = item
                break

    if best_match is None:
        best_match = data[0]
    return best_match

def get_business_details(matched_business):
    if not isinstance(matched_business, dict):
        return None

    business_id = matched_business.get("business_id")
    if not business_id:
        business_id = matched_business.get("google_id")
    if not business_id:
        business_id = matched_business.get("place_id")

    if not business_id:
        return None

    try:
        return Business_Details(business_id, TARGET_REGION)
    except Exception as exc:
        print(f"Business_Details API error: {exc}", file=sys.stderr)
        return None

def determine_open_status(details_response):
    if not isinstance(details_response, dict):
        return "Unknown"

    data = details_response.get("data", [])
    if not isinstance(data, list) or not data:
        return "Unknown"

    record = data[0] if isinstance(data[0], dict) else {}
    business_status = record.get("business_status")
    opening_status = record.get("opening_status")
    working_hours = record.get("working_hours", {})

    if isinstance(opening_status, str) and opening_status.strip():
        return opening_status

    if isinstance(business_status, str) and business_status.strip():
        return business_status

    if isinstance(working_hours, dict) and working_hours:
        return "Has working hours listed"

    return "Unknown"

def is_likely_open(status_text):
    if not isinstance(status_text, str):
        return False
    normalized = status_text.casefold()
    return ("open" in normalized) and ("closed" not in normalized)

def build_result_message(search_response, matched_business, details_response, open_status):
    if not matched_business:
        return f"No matching business found for {TARGET_BUSINESS_NAME} near {TARGET_POSTAL_CODE}, {TARGET_CITY}, {TARGET_STATE}."

    matched_name = matched_business.get("name", "Unknown business")
    matched_address = matched_business.get("full_address") or matched_business.get("address") or "Unknown address"

    if details_response and isinstance(details_response, dict):
        data = details_response.get("data", [])
        if isinstance(data, list) and data and isinstance(data[0], dict):
            detail_record = data[0]
            detail_name = detail_record.get("name", matched_name)
            detail_address = detail_record.get("full_address", matched_address)
            status_text = determine_open_status(details_response)
            if is_likely_open(status_text):
                verdict = "likely open"
            elif isinstance(status_text, str) and status_text.casefold() == "closed":
                verdict = "likely closed"
            else:
                verdict = f"status: {status_text}"
            return (
                f"Matched business: {detail_name}\n"
                f"Address: {detail_address}\n"
                f"Current status: {verdict}"
            )

    status_text = determine_open_status(details_response)
    if is_likely_open(status_text):
        verdict = "likely open"
    elif isinstance(status_text, str) and status_text.casefold() == "closed":
        verdict = "likely closed"
    else:
        verdict = f"status: {status_text}"

    return (
        f"Matched business: {matched_name}\n"
        f"Address: {matched_address}\n"
        f"Current status: {verdict}"
    )

def main():
    search_response = search_business_by_area()
    matched_business = select_matched_business(search_response)
    details_response = get_business_details(matched_business)
    open_status = determine_open_status(details_response)
    result_message = build_result_message(search_response, matched_business, details_response, open_status)
    print(result_message)

if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

