import os
import traceback

TARGET_BUSINESS_NAME = "Goodyear Auto Service"
TARGET_QUERY = "Goodyear Auto Service in 34683, Palm Harbor, FL"
TARGET_POSTAL_CODE = "34683"
TARGET_CITY = "Palm Harbor"
TARGET_STATE = "FL"


def find_business_identifier():
    try:
        search_results = Search(TARGET_QUERY)
    except Exception:
        raise

    data = search_results.get("data", [])
    if not data:
        return None

    def score_business(item):
        name = str(item.get("name", "")).lower()
        address = str(item.get("full_address", "")).lower()
        city = str(item.get("city", "")).lower()
        state = str(item.get("state", "")).lower()
        zipcode = str(item.get("zipcode", "")).lower()

        score = 0
        if "goodyear auto service" in name:
            score += 5
        if TARGET_POSTAL_CODE in zipcode or TARGET_POSTAL_CODE in address:
            score += 4
        if TARGET_CITY.lower() in city or TARGET_CITY.lower() in address:
            score += 3
        if TARGET_STATE.lower() in state or TARGET_STATE.lower() in address:
            score += 2
        return score

    best_match = max(data, key=score_business, default=None)
    if not best_match:
        return None

    for key in ("business_id", "google_id", "place_id"):
        if best_match.get(key):
            return best_match.get(key)
    return None


def get_review_count(business_identifier):
    if not business_identifier:
        return None

    review_data = Business_Reviews(business_identifier)
    data = review_data.get("data", [])
    return len(data)


def main():
    business_identifier = find_business_identifier()
    review_count = get_review_count(business_identifier)

    if business_identifier is None:
        print(f"No matching business found for {TARGET_BUSINESS_NAME} in {TARGET_POSTAL_CODE}, {TARGET_CITY}, {TARGET_STATE}.")
    else:
        print(f"Business identifier: {business_identifier}")
        if review_count is None:
            print("Review count could not be determined.")
        else:
            print(f"Number of reviews received: {review_count}")


if __name__ == "__main__":
