import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Maps_Data.Search import Search
from Tools.Maps_Data.Place_info import Place_info
from Tools.Maps_Data.Place_reviews import Place_reviews

import traceback

POSTAL_CODE = "46038"
CITY = "Fishers"
REGION = "IN"
BUSINESS_NAME = "Tequila Sunrise"
COUNTRY_CODE = "us"

APPOINTMENT_REQUIRED_TERMS = [
    "appointment required",
    "appointment only",
    "by appointment",
    "reservations required",
    "reservation required",
    "booking required",
    "schedule an appointment",
    "make an appointment",
]

APPOINTMENT_NOT_REQUIRED_TERMS = [
    "walk-ins welcome",
    "walk in",
    "no appointment needed",
    "no appointment required",
    "no reservations needed",
    "no reservations required",
    "come in anytime",
]


def build_search_query():
    return f"{BUSINESS_NAME} {POSTAL_CODE} {CITY} {REGION}"


def search_business():
    query = build_search_query()
    try:
        return Search(query)
    except Exception:
        return {"data": []}


def extract_candidates(search_results):
    data = search_results.get("data", [])
    if not isinstance(data, list):
        return []
    return data


def score_candidate(candidate):
    name = str(candidate.get("name", "")).lower()
    full_address = str(candidate.get("full_address", "")).lower()
    city = str(candidate.get("city", "")).lower()
    state = str(candidate.get("state", "")).lower()
    types = candidate.get("types", [])
    types_text = " ".join([str(t).lower() for t in types]) if isinstance(types, list) else ""

    score = 0
    if BUSINESS_NAME.lower() in name:
        score += 5
    if CITY.lower() in full_address or CITY.lower() in city:
        score += 3
    if REGION.lower() in full_address or REGION.lower() in state:
        score += 2
    if POSTAL_CODE in full_address:
        score += 2
    if "restaurant" in types_text:
        score += 1
    return score


def select_matching_business(search_results):
    candidates = extract_candidates(search_results)
    if not candidates:
        return None

    scored = sorted(candidates, key=score_candidate, reverse=True)
    best = scored[0]
    business_id = best.get("business_id")
    if business_id:
        return business_id
    return None


def get_place_details(business_id):
    try:
        return Place_info(business_id)
    except Exception:
        return {"data": []}


def get_place_reviews(business_id):
    try:
        return Place_reviews(business_id, COUNTRY_CODE)
    except Exception:
        return {"data": {}}


def normalize_text(value):
    if value is None:
        return ""
    if isinstance(value, list):
        return " ".join(normalize_text(v) for v in value)
    if isinstance(value, dict):
        return " ".join(f"{k} {normalize_text(v)}" for k, v in value.items())
    return str(value).lower()


def detect_appointment_requirement(place_details, reviews):
    details_data = place_details.get("data", [])
    place = details_data[0] if isinstance(details_data, list) and details_data else {}

    text_sources = []

    for key in ["description", "working_hours", "website", "website_full", "full_address", "name", "types", "price_level"]:
        if key in place:
            text_sources.append(normalize_text(place.get(key)))

    reviews_data = reviews.get("data", {})
    if isinstance(reviews_data, dict):
        for key in ["description", "working_hours", "website", "website_full", "full_address", "name", "types", "price_level"]:
            if key in reviews_data:
                text_sources.append(normalize_text(reviews_data.get(key)))
        review_list = reviews_data.get("reviews", [])
        if isinstance(review_list, list):
            for review in review_list[:20]:
                text_sources.append(normalize_text(review.get("review_text")))
                text_sources.append(normalize_text(review.get("business_response_text")))

    combined = " ".join(text_sources)

    for term in APPOINTMENT_REQUIRED_TERMS:
        if term in combined:
            return "appointment_required"

    for term in APPOINTMENT_NOT_REQUIRED_TERMS:
        if term in combined:
            return "appointment_not_required"

    return "appointment_requirement_unknown"


def main():
    search_results = search_business()
    business_id = select_matching_business(search_results)

    if not business_id:
        print("appointment_requirement_unknown")
        return

    place_details = get_place_details(business_id)
    reviews = get_place_reviews(business_id)

    result = detect_appointment_requirement(place_details, reviews)
    print(result)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
