from Tools.Local_Business_Data.Search import Search
from Tools.Local_Business_Data.Business_Details import Business_Details

import traceback

SEARCH_QUERY = "William Whitfield Park, 37211, Nashville, TN"
BUSINESS_REGION = "us"
TARGET_NAME_KEYWORDS = ["william whitfield park"]
TARGET_AREA_KEYWORDS = ["37211", "nashville", "tn"]


def find_place_record(location_query):
    try:
        result = Search(location_query)
        return result
    except Exception as exc:
        raise RuntimeError(f"Search failed for query '{location_query}': {exc}") from exc


def extract_search_data(search_result):
    if not isinstance(search_result, dict):
        return []
    data = search_result.get("data", [])
    if isinstance(data, list):
        return data
    return []


def normalize_text(value):
    if value is None:
        return ""
    return str(value).strip().lower()


def record_matches_target(record):
    name = normalize_text(record.get("name"))
    full_address = normalize_text(record.get("full_address"))
    address = normalize_text(record.get("address"))
    city = normalize_text(record.get("city"))
    state = normalize_text(record.get("state"))
    zipcode = normalize_text(record.get("zipcode"))
    combined = " ".join([name, full_address, address, city, state, zipcode])

    name_match = any(keyword in name for keyword in TARGET_NAME_KEYWORDS)
    area_match = all(keyword in combined for keyword in TARGET_AREA_KEYWORDS)
    return name_match and area_match


def select_target_record(search_result):
    records = extract_search_data(search_result)
    if not records:
        return None

    for record in records:
        if record_matches_target(record):
            return record

    for record in records:
        combined = " ".join(
            [
                normalize_text(record.get("name")),
                normalize_text(record.get("full_address")),
                normalize_text(record.get("address")),
            ]
        )
        if any(keyword in combined for keyword in TARGET_NAME_KEYWORDS) and any(
            keyword in combined for keyword in TARGET_AREA_KEYWORDS
        ):
            return record

    return records[0]


def get_place_details(place_record):
    if not place_record:
        return {}
    business_id = place_record.get("business_id") or place_record.get("google_id")
    if not business_id:
        return {}
    try:
        details = Business_Details(business_id, BUSINESS_REGION)
        return details
    except Exception as exc:
        raise RuntimeError(f"Business details lookup failed for business_id '{business_id}': {exc}") from exc


def extract_details_data(details_result):
    if not isinstance(details_result, dict):
        return []
    data = details_result.get("data", [])
    if isinstance(data, list):
        return data
    return []


def determine_operating_status(details_result):
    records = extract_details_data(details_result)
    if not records:
        return None, None, None

    record = records[0]
    business_status = record.get("business_status")
    opening_status = record.get("opening_status")
    working_hours = record.get("working_hours", {})
    return business_status, opening_status, working_hours


def format_hours_info(working_hours):
    if not isinstance(working_hours, dict) or not working_hours:
        return "Hours information not available."

    ordered_days = [
        "Monday", "Tuesday", "Wednesday", "Thursday",
        "Friday", "Saturday", "Sunday"
    ]
    lines = []
    for day in ordered_days:
        hours = working_hours.get(day)
        if isinstance(hours, list) and hours:
            lines.append(f"{day}: {', '.join(map(str, hours))}")
        elif hours:
            lines.append(f"{day}: {hours}")
    if not lines:
        return "Hours information not available."
    return "\n".join(lines)


def build_query():
    return SEARCH_QUERY


def main():
    query = build_query()
    search_result = find_place_record(query)
    target_record = select_target_record(search_result)

    if not target_record:
        print("William Whitfield Park could not be found for the requested area.")
        return

    details = get_place_details(target_record)
    business_status, opening_status, working_hours = determine_operating_status(details)

    place_name = target_record.get("name", "William Whitfield Park")
    address = target_record.get("full_address") or target_record.get("address") or "Address not available"
    search_status = target_record.get("business_status") or "Unknown"
    detail_status = business_status or opening_status or "Unknown"
    hours_text = format_hours_info(working_hours)

    print(f"Place: {place_name}")
    print(f"Address: {address}")
    print(f"Search status: {search_status}")
    print(f"Current operating status: {detail_status}")
    print("Hours:")
    print(hours_text)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Maps_Data.Search import Search
from Tools.Maps_Data.Place_info import Place_info
from Tools.Maps_Data.Place_reviews import Place_reviews

import traceback

AREA_POSTAL_CODE = "19468"
AREA_CITY = "Limerick"
AREA_STATE = "PA"
BUSINESS_NAME = "Franklin's Classic Steaks & Hoagies"
COUNTRY_CODE = "us"


def build_search_query(business_name, area_postal_code, area_city, area_state):
    return f"{business_name}, {area_postal_code}, {area_city}, {area_state}"


def search_business_in_area(area_postal_code, area_city, area_state, business_name):
    query = build_search_query(business_name, area_postal_code, area_city, area_state)
    return Search(query)


def extract_first_business_id(search_result):
    data = search_result.get("data", [])
    if not isinstance(data, list) or len(data) == 0:
        return None
    first = data[0]
    return first.get("business_id")


def get_business_details(business_id):
    return Place_info(business_id)


def get_business_reviews(business_id, country_code):
    return Place_reviews(business_id, country_code)


def normalize_text(value):
    if value is None:
        return ""
    return str(value).strip().lower()


def infer_appointment_requirement_from_text(text):
    normalized = normalize_text(text)
    if not normalized:
        return None

    appointment_terms = ["appointment", "booking", "reserve", "reservation", "scheduled"]
    no_terms = ["no appointment", "walk-in", "walk in", "without appointment", "no booking", "no reservation"]

    if any(term in normalized for term in no_terms):
        return "No, it appears appointments are not required."
    if any(term in normalized for term in appointment_terms):
        return "Possibly yes, appointment or booking appears mentioned."
    return None


def determine_appointment_requirement(details, reviews):
    details_data = details.get("data", [])
    if isinstance(details_data, list) and len(details_data) > 0:
        detail_item = details_data[0]
        for field in ("description", "details"):
            if field in detail_item:
                inferred = infer_appointment_requirement_from_text(detail_item.get(field))
                if inferred:
                    return inferred
        working_hours = detail_item.get("working_hours")
        if working_hours:
            inferred = infer_appointment_requirement_from_text(working_hours)
            if inferred:
                return inferred

    review_data = reviews.get("data", {})
    if isinstance(review_data, dict):
        for field in ("description", "reviews", "full_address", "name"):
            if field in review_data:
                inferred = infer_appointment_requirement_from_text(review_data.get(field))
                if inferred:
                    return inferred
        reviews_list = review_data.get("reviews", [])
        if isinstance(reviews_list, list):
            for review in reviews_list:
                review_text = review.get("review_text")
                inferred = infer_appointment_requirement_from_text(review_text)
                if inferred:
                    return inferred
                response_text = review.get("business_response_text")
                inferred = infer_appointment_requirement_from_text(response_text)
                if inferred:
                    return inferred

    return "No explicit appointment requirement was found in the available business data."


def format_output(business_name, area_postal_code, area_city, area_state, result_text):
    lines = [
        f"Business: {business_name}",
        f"Area: {area_postal_code}, {area_city}, {area_state}",
        f"Appointment requirement: {result_text}",
    ]
    return "\n".join(lines)


def main():
    search_result = search_business_in_area(
        AREA_POSTAL_CODE,
        AREA_CITY,
        AREA_STATE,
        BUSINESS_NAME,
    )

    business_id = extract_first_business_id(search_result)
    if not business_id:
        output = format_output(
            BUSINESS_NAME,
            AREA_POSTAL_CODE,
            AREA_CITY,
            AREA_STATE,
            "No business match was found for the specified area.",
        )
        print(output)
        return

    details = get_business_details(business_id)
    reviews = get_business_reviews(business_id, COUNTRY_CODE)

    appointment_requirement = determine_appointment_requirement(details, reviews)
    output = format_output(
        BUSINESS_NAME,
        AREA_POSTAL_CODE,
        AREA_CITY,
        AREA_STATE,
        appointment_requirement,
    )
    print(output)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

