PANERA_BREAD_QUERY = "Panera Bread in 33566, Plant City, FL"
TARGET_BUSINESS_NAME = "Panera Bread"
TARGET_POSTAL_CODE = "33566"
TARGET_CITY = "Plant City"
TARGET_STATE = "FL"
TARGET_REGION = "us"


def build_search_query(business_name, postal_code, city, state):
    parts = [business_name, postal_code, city, state]
    return ", ".join([p for p in parts if p])


def call_search(query):
    try:
        return Search(query)
    except Exception:
        raise


def call_business_details(business_id, region):
    try:
        return Business_Details(business_id, region)
    except Exception:
        raise


def get_first_result(data):
    if isinstance(data, list) and data:
        return data[0]
    return None


def select_relevant_business(search_response, target_name):
    data = search_response.get("data", []) if isinstance(search_response, dict) else []
    if not isinstance(data, list) or not data:
        return None

    target_lower = target_name.lower()
    for item in data:
        name = str(item.get("name", "")).lower()
        if target_lower in name:
            return item

    return data[0]


def extract_business_id(business_item):
    if not isinstance(business_item, dict):
        return None
    return business_item.get("business_id") or business_item.get("google_id") or business_item.get("place_id")


def extract_working_hours(details_response):
    data = details_response.get("data", []) if isinstance(details_response, dict) else []
    business = get_first_result(data)
    if not isinstance(business, dict):
        return {}

    working_hours = business.get("working_hours", {})
    if isinstance(working_hours, dict):
        return working_hours
    return {}


def format_working_hours(working_hours):
    if not working_hours:
        return "Hours of operation were not available from the API response."

    day_order = [
        "Monday", "Tuesday", "Wednesday", "Thursday",
        "Friday", "Saturday", "Sunday"
    ]
    lines = []
    for day in day_order:
        hours = working_hours.get(day)
        if isinstance(hours, list) and hours:
            lines.append(f"{day}: {', '.join(map(str, hours))}")
        elif isinstance(hours, str) and hours:
            lines.append(f"{day}: {hours}")
        else:
            lines.append(f"{day}: Hours not available")
    return "\n".join(lines)


def find_panera_bread_hours(postal_code, city, state):
    query = build_search_query(TARGET_BUSINESS_NAME, postal_code, city, state)
    search_response = call_search(query)
    business_item = select_relevant_business(search_response, TARGET_BUSINESS_NAME)

    if not business_item:
        return None, "No matching Panera Bread location was found for the specified area."

    business_id = extract_business_id(business_item)
    if not business_id:
        return None, "A Panera Bread location was found, but no business identifier was available."

    details_response = call_business_details(business_id, TARGET_REGION)
    working_hours = extract_working_hours(details_response)
    return working_hours, None


def main():
    working_hours, error_message = find_panera_bread_hours(
        TARGET_POSTAL_CODE, TARGET_CITY, TARGET_STATE
    )

    if error_message:
        print(error_message)
        return

    print(f"Panera Bread hours in {TARGET_POSTAL_CODE}, {TARGET_CITY}, {TARGET_STATE}:")
    print(format_working_hours(working_hours))


if __name__ == "__main__":
    import sys
    import traceback

    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

