import traceback

# Module-level pinned constants derived from the user requirement.
BUSINESS_QUERY = "Briggs Auction Garnet Valley PA 19060"
TARGET_NAME_HINT = "Briggs Auction"
TARGET_LOCATION_HINTS = ["19060", "Garnet Valley", "PA"]
DEFAULT_REGION = "us"


def search_businesses(query):
    try:
        return Search(query)
    except Exception as exc:
        raise RuntimeError(f"Search API call failed: {exc}") from exc


def pick_relevant_business(search_response):
    data = search_response.get("data", []) if isinstance(search_response, dict) else []
    if not data:
        return None

    def score_item(item):
        score = 0
        name = str(item.get("name", "")).lower()
        full_address = str(item.get("full_address", "")).lower()
        address = str(item.get("address", "")).lower()
        city = str(item.get("city", "")).lower()
        state = str(item.get("state", "")).lower()
        zipcode = str(item.get("zipcode", "")).lower()

        if TARGET_NAME_HINT.lower() in name:
            score += 5
        if "auction" in name:
            score += 2

        for hint in TARGET_LOCATION_HINTS:
            h = hint.lower()
            if h in full_address or h in address or h in city or h in state or h in zipcode:
                score += 3

        return score

    best = max(data, key=score_item)
    return best.get("business_id")


def get_business_details(business_id):
    if not business_id:
        return {}
    try:
        return Business_Details(business_id, DEFAULT_REGION)
    except Exception as exc:
        raise RuntimeError(f"Business_Details API call failed: {exc}") from exc


def extract_hours_of_operation(details_response):
    data = details_response.get("data", []) if isinstance(details_response, dict) else []
    if not data:
        return None, None

    business = data[0] if isinstance(data, list) and data else {}
    working_hours = business.get("working_hours", {})
    opening_status = business.get("opening_status")

    return opening_status, working_hours


def format_hours(working_hours):
    if not working_hours:
        return "Hours of operation were not available from the API response."

    day_order = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
    lines = []
    for day in day_order:
        hours = working_hours.get(day)
        if isinstance(hours, list) and hours:
            lines.append(f"{day}: {', '.join(map(str, hours))}")
        elif hours is not None:
            lines.append(f"{day}: {hours}")
    if not lines:
        return "Hours of operation were not available from the API response."
    return "\n".join(lines)


def main():
    search_response = search_businesses(BUSINESS_QUERY)
    business_id = pick_relevant_business(search_response)
    details_response = get_business_details(business_id)
    opening_status, working_hours = extract_hours_of_operation(details_response)

    print("Briggs Auction hours of operation for Garnet Valley, PA 19060:")
    if opening_status:
        print(f"Status: {opening_status}")
    print(format_hours(working_hours))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Local_Business_Data.Search import Search
from Tools.Local_Business_Data.Business_Details import Business_Details
from Tools.Local_Business_Data.Business_Reviews import Business_Reviews

import traceback
import re

TARGET_NAME = "Philippine Smoked BBQ Grill"
TARGET_AREA = "Wilmington, DE 19805"
SEARCH_QUERY = f"{TARGET_NAME} {TARGET_AREA}"
REGION = "us"
APPOINTMENT_KEYWORDS = [
    "appointment",
    "appointments",
    "reserve",
    "reservation",
    "reservations",
    "booking",
    "book",
    "call ahead",
    "call before",
    "make an appointment",
    "scheduled",
    "schedule",
    "walk-in",
    "walk ins",
    "walk-ins",
]

def safe_get(obj, path, default=None):
    cur = obj
    for key in path:
        if isinstance(cur, dict):
            cur = cur.get(key, default)
        else:
            return default
    return cur

def normalize_text(value):
    if value is None:
        return ""
    return str(value).lower()

def search_business_listings(target_name, target_area):
    query = f"{target_name} {target_area}"
    try:
        return Search(query)
    except Exception:
        raise

def select_likely_business_id(search_results, target_name):
    data = search_results.get("data", []) if isinstance(search_results, dict) else []
    if not data:
        return None

    target_norm = normalize_text(target_name)
    for item in data:
        name = normalize_text(item.get("name"))
        if target_norm in name or name in target_norm:
            return item.get("business_id") or item.get("google_id") or item.get("place_id")

    first = data[0]
    return first.get("business_id") or first.get("google_id") or first.get("place_id")

def retrieve_business_details(business_id):
    if not business_id:
        return None
    return Business_Details(business_id, REGION)

def retrieve_business_reviews(business_id):
    if not business_id:
        return None
    return Business_Reviews(business_id)

def collect_text_from_details(detail_item):
    parts = []
    for key in ["name", "about", "opening_status", "full_address", "address", "business_status", "type"]:
        val = detail_item.get(key)
        if isinstance(val, dict):
            parts.extend([str(v) for v in val.values() if v is not None])
        elif val is not None:
            parts.append(str(val))

    working_hours = detail_item.get("working_hours", {})
    if isinstance(working_hours, dict):
        for day, entries in working_hours.items():
            parts.append(str(day))
            if isinstance(entries, list):
                parts.extend([str(x) for x in entries if x is not None])
            elif entries is not None:
                parts.append(str(entries))

    for key in ["booking_link", "reservations_link", "order_link", "menu_link", "website", "phone_number"]:
        val = detail_item.get(key)
        if val is not None:
            parts.append(str(val))

    return " ".join(parts)

def check_for_appointment_requirement(business_details):
    data = safe_get(business_details, ["data"], [])
    if not data:
        return {"state": "unclear", "evidence": []}

    detail_item = data[0] if isinstance(data, list) and data else {}
    text_blob = normalize_text(collect_text_from_details(detail_item))
    evidence = [kw for kw in APPOINTMENT_KEYWORDS if kw in text_blob]

    if any(k in text_blob for k in ["appointment", "reservation", "booking"]):
        if any(k in text_blob for k in ["required", "necessary", "needed", "must", "call ahead", "call before"]):
            return {"state": "required_or_suggested", "evidence": evidence}
        return {"state": "mentioned", "evidence": evidence}

    return {"state": "unclear", "evidence": evidence}

def inspect_reviews_for_appointment_clues(reviews):
    data = safe_get(reviews, ["data"], [])
    if not data:
        return {"state": "unclear", "evidence": []}

    collected = []
    for review in data:
        text = normalize_text(review.get("review_text"))
        owner_resp = normalize_text(review.get("owner_response_text"))
        blob = f"{text} {owner_resp}"
        if any(kw in blob for kw in APPOINTMENT_KEYWORDS):
            collected.append(review.get("review_text") or review.get("owner_response_text") or "")
    if collected:
        return {"state": "mentioned", "evidence": collected}
    return {"state": "unclear", "evidence": []}

def determine_final_answer(detail_indicator, review_indicator):
    if detail_indicator["state"] == "required_or_suggested":
        return "appointment required"
    if detail_indicator["state"] == "mentioned":
        return "appointment mentioned in business details, but requirement is not explicit"
    if review_indicator["state"] == "mentioned":
        return "appointment likely required or mentioned in public reviews"
    return "appointment requirement not clearly stated"

def format_output(answer, business_name=None, area=None, detail_indicator=None, review_indicator=None):
    lines = []
    title = f"{business_name} in {area}" if business_name and area else "Business inquiry"
    lines.append(title)
    lines.append(f"Answer: {answer}")
    if detail_indicator:
        lines.append(f"Details check: {detail_indicator['state']}")
    if review_indicator:
        lines.append(f"Reviews check: {review_indicator['state']}")
    return "\n".join(lines)

def main():
    search_results = search_business_listings(TARGET_NAME, TARGET_AREA)
    business_id = select_likely_business_id(search_results, TARGET_NAME)
    business_details = retrieve_business_details(business_id)
    detail_indicator = check_for_appointment_requirement(business_details)

    review_indicator = {"state": "unclear", "evidence": []}
    if detail_indicator["state"] == "unclear":
        reviews = retrieve_business_reviews(business_id)
        review_indicator = inspect_reviews_for_appointment_clues(reviews)

    final_answer = determine_final_answer(detail_indicator, review_indicator)
    print(format_output(final_answer, TARGET_NAME, TARGET_AREA, detail_indicator, review_indicator))

if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

