import traceback

TARGET_NAME = "Buddy's Burgers - Kennett Square"
TARGET_CITY = "Kennett Square"
TARGET_STATE = "PA"
TARGET_POSTAL_CODE = "19348"
REGION = "us"


def build_search_query(target_name, target_city, target_state, target_postal_code):
    location_mapping = {
        "postal_code": target_postal_code,
        "city": target_city,
        "state": target_state,
    }
    return f"{target_name} in area with postal code {location_mapping['postal_code']}, {location_mapping['city']}, {location_mapping['state']}"


def search_business_record(target_name, target_city, target_state, target_postal_code):
    query = build_search_query(target_name, target_city, target_state, target_postal_code)
    try:
        response = Search(query)
    except Exception:
        raise

    data = response.get("data", [])
    if not data:
        return None
    return data[0]


def get_business_details(business_id, region):
    try:
        response = Business_Details(business_id, region)
    except Exception:
        raise

    data = response.get("data", [])
    if not data:
        return None
    return data[0]


def extract_categories(business_details):
    if not business_details:
        return []

    categories = []
    if "type" in business_details and business_details["type"]:
        categories.append(business_details["type"])

    subtypes = business_details.get("subtypes", [])
    if isinstance(subtypes, list):
        for subtype in subtypes:
            if subtype and subtype not in categories:
                categories.append(subtype)

    return categories


def print_categories(target_name, categories):
    print(f"Categories for {target_name}:")
    if not categories:
        print("No categories found.")
        return

    for category in categories:
        print(f"- {category}")


def main():
    business_record = search_business_record(
        TARGET_NAME, TARGET_CITY, TARGET_STATE, TARGET_POSTAL_CODE
    )

    if not business_record:
        print(f"No business found for {TARGET_NAME} in {TARGET_POSTAL_CODE}, {TARGET_CITY}, {TARGET_STATE}.")
        return

    business_id = business_record.get("business_id")
    if not business_id:
        print(f"Business record found for {TARGET_NAME}, but no business_id was available.")
        return

    business_details = get_business_details(business_id, REGION)
    if not business_details:
        print(f"No detailed business data found for {TARGET_NAME}.")
        return

    categories = extract_categories(business_details)
    print_categories(TARGET_NAME, categories)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

