# Ground-truth field paths from response_schema
SEARCH_DATA_KEY = "data"
SEARCH_NAME_KEY = "name"
SEARCH_FULL_ADDRESS_KEY = "full_address"
SEARCH_BUSINESS_ID_KEY = "business_id"
