def build_search_query(target_business_name, target_city, target_region, target_postal_code):
    return f"{target_business_name} in {target_city}, {target_region} {target_postal_code}"


def search_business_in_area(target_business_name, target_city, target_region, target_postal_code):
    query = build_search_query(target_business_name, target_city, target_region, target_postal_code)
    try:
        return Search(query)
    except Exception:
        raise


def _text_matches_all(text, terms):
    lowered = (text or "").lower()
    return all(term.lower() in lowered for term in terms if term)


def select_matching_local_listing(search_results):
    data = search_results.get(SEARCH_DATA_KEY, []) if isinstance(search_results, dict) else []
    if not data:
        return None

    target_terms = ["two men and a truck", "st. louis east", "collinsville", "62234"]
    best = None
    best_score = -1

    for item in data:
        name = item.get(SEARCH_NAME_KEY, "")
        full_address = item.get(SEARCH_FULL_ADDRESS_KEY, "")
        score = 0

        if _text_matches_all(name, ["two men and a truck"]):
            score += 4
        if _text_matches_all(name, ["st. louis east", "st louis east"]):
            score += 3
        if _text_matches_all(full_address, ["collinsville"]):
            score += 2
        if _text_matches_all(full_address, ["62234"]):
            score += 2
        if _text_matches_all(full_address, ["il", "illinois"]):
            score += 1
        if _text_matches_all(name + " " + full_address, target_terms):
            score += 5

        if score > best_score:
            best_score = score
            best = item

    return best if best is not None else data[0]


def get_business_categories_from_listing(listing):
    if not listing:
        return []

    business_id = listing.get(SEARCH_BUSINESS_ID_KEY)
    if not business_id:
        return listing.get(SEARCH_SUBTYPES_KEY, []) or []

    try:
        details = Business_Details(business_id, TARGET_REGION.lower())
    except Exception:
        return listing.get(SEARCH_SUBTYPES_KEY, []) or []

    details_data = details.get(DETAILS_DATA_KEY, []) if isinstance(details, dict) else []
    if not details_data:
        return listing.get(SEARCH_SUBTYPES_KEY, []) or []

    profile = details_data[0]
    categories = profile.get(DETAILS_SUBTYPES_KEY, [])
    if not categories:
        categories = profile.get(DETAILS_TYPE_KEY, [])
        if isinstance(categories, str):
            categories = [categories]
        elif not isinstance(categories, list):
            categories = []

    return categories


def format_categories_output(listing, categories):
    name = listing.get(SEARCH_NAME_KEY, TARGET_BUSINESS_NAME) if listing else TARGET_BUSINESS_NAME
    address = listing.get(SEARCH_FULL_ADDRESS_KEY, "N/A") if listing else "N/A"

    if categories:
        categories_text = ", ".join(str(c) for c in categories)
    else:
        categories_text = "No categories found"

    return (
        f"Business: {name}\n"
        f"Location: {address}\n"
        f"Categories: {categories_text}"
    )


def main():
    search_results = search_business_in_area(
        TARGET_BUSINESS_NAME,
        TARGET_CITY,
        TARGET_REGION,
        TARGET_POSTAL_CODE,
    )
    matching_listing = select_matching_local_listing(search_results)
    categories = get_business_categories_from_listing(matching_listing)
    output = format_categories_output(matching_listing, categories)
    print(output)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
