from Tools.Local_Business_Data.Search import Search
from Tools.Local_Business_Data.Business_Details import Business_Details

import traceback

# Module-level constants pinned from the user requirement
TARGET_BUSINESS = "Orvelle Nails & Spa"
TARGET_CITY = "Brentwood"
TARGET_STATE = "TN"
TARGET_POSTAL_CODE = "37027"
TARGET_REGION = "us"

# Schema-grounded key paths from Search response_schema
SEARCH_DATA_KEY = "data"
SEARCH_BUSINESS_ID_KEYS = ("business_id", "place_id", "google_id", "google_mid")
SEARCH_NAME_KEY = "name"
SEARCH_CITY_KEY = "city"
SEARCH_STATE_KEY = "state"
SEARCH_ZIPCODE_KEY = "zipcode"
SEARCH_ADDRESS_KEY = "full_address"

# Schema-grounded key paths from Business_Details response_schema
DETAILS_DATA_KEY = "data"
DETAILS_TYPE_KEY = "type"
DETAILS_SUBTYPES_KEY = "subtypes"


def build_search_query(business_name, city, state, postal_code):
    return f"{business_name} in {city}, {state} {postal_code}"


def search_business_in_area(target_business, target_city, target_state, target_postal_code):
    query = build_search_query(target_business, target_city, target_state, target_postal_code)
    try:
        return Search(query)
    except Exception as exc:
        raise RuntimeError(f"Search API failed for query '{query}': {exc}") from exc


def _safe_get(entry, key, default=None):
    if isinstance(entry, dict):
        return entry.get(key, default)
    return default


def select_matching_business(search_result, target_business, target_city, target_state, target_postal_code):
    data = search_result.get(SEARCH_DATA_KEY, []) if isinstance(search_result, dict) else []
    if not isinstance(data, list) or not data:
        return None

    target_business_lower = target_business.lower()
    target_city_lower = target_city.lower()
    target_state_lower = target_state.lower()
    target_postal_code_str = str(target_postal_code)

    best_entry = None
    best_score = -1

    for entry in data:
        if not isinstance(entry, dict):
            continue

        name = str(_safe_get(entry, SEARCH_NAME_KEY, "")).lower()
        city = str(_safe_get(entry, SEARCH_CITY_KEY, "")).lower()
        state = str(_safe_get(entry, SEARCH_STATE_KEY, "")).lower()
        zipcode = str(_safe_get(entry, SEARCH_ZIPCODE_KEY, ""))
        full_address = str(_safe_get(entry, SEARCH_ADDRESS_KEY, "")).lower()

        score = 0
        if target_business_lower in name:
            score += 4
        if target_city_lower in city or target_city_lower in full_address:
            score += 2
        if target_state_lower in state or target_state_lower in full_address:
            score += 1
        if target_postal_code_str in zipcode or target_postal_code_str in full_address:
            score += 3

        if score > best_score:
            best_score = score
            best_entry = entry

    if best_entry is None:
        best_entry = data[0] if data and isinstance(data[0], dict) else None

    return best_entry


def extract_business_identifier(matching_entry):
    if not isinstance(matching_entry, dict):
        return None

    for key in SEARCH_BUSINESS_ID_KEYS:
        value = matching_entry.get(key)
        if value:
            return value
    return None


def get_business_categories(business_identifier, region):
    if not business_identifier:
        return []
    try:
        return Business_Details(business_identifier, region)
    except Exception as exc:
        raise RuntimeError(f"Business_Details API failed for business_id '{business_identifier}': {exc}") from exc


def extract_categories_from_details(details_result):
    data = details_result.get(DETAILS_DATA_KEY, []) if isinstance(details_result, dict) else []
    if not isinstance(data, list) or not data:
        return []

    first_entry = data[0]
    if not isinstance(first_entry, dict):
        return []

    categories = []

    business_type = first_entry.get(DETAILS_TYPE_KEY)
    if business_type:
        categories.append(business_type)

    subtypes = first_entry.get(DETAILS_SUBTYPES_KEY, [])
    if isinstance(subtypes, list):
        for subtype in subtypes:
            if subtype and subtype not in categories:
                categories.append(subtype)

    return categories


def run():
    search_output = search_business_in_area(
        TARGET_BUSINESS,
        TARGET_CITY,
        TARGET_STATE,
        TARGET_POSTAL_CODE,
    )

    matching_entry = select_matching_business(
        search_output,
        TARGET_BUSINESS,
        TARGET_CITY,
        TARGET_STATE,
        TARGET_POSTAL_CODE,
    )

    business_identifier = extract_business_identifier(matching_entry)
    details_output = get_business_categories(business_identifier, TARGET_REGION)
    categories = extract_categories_from_details(details_output)

    print(f"Business: {TARGET_BUSINESS}")
    print(f"Location: {TARGET_CITY}, {TARGET_STATE} {TARGET_POSTAL_CODE}")
    if categories:
        print("Categories:")
        for category in categories:
            print(f"- {category}")
    else:
        print("Categories: No categories found.")


if __name__ == "__main__":
    try:
        run()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

