from Tools.Forward_and_Reverse_Geocoding.GeocodingSearch import GeocodingSearch

import traceback

POSTAL_CODE = "83704"
LOCALITY = "Boise"
REGION = "ID"
TARGET_NAME = "Ada County"
SEARCH_QUERY = f"{POSTAL_CODE}, {LOCALITY}, {REGION}, USA"


def build_search_criteria(postal_code, locality, region):
    return f"{postal_code}, {locality}, {region}, USA"


def lookup_location_by_postal_area(postal_code, locality, region):
    search_criteria = build_search_criteria(postal_code, locality, region)
    return GeocodingSearch(search_criteria)


def is_administrative_candidate(result):
    if not isinstance(result, dict):
        return False

    result_class = str(result.get("class", "")).lower()
    result_type = str(result.get("type", "")).lower()
    display_name = str(result.get("display_name", "")).lower()
    address = result.get("address", {}) or {}

    county = str(address.get("county", "")).lower()
    state = str(address.get("state", "")).lower()
    city = str(address.get("city", "")).lower()
    town = str(address.get("town", "")).lower()

    name_match = TARGET_NAME.lower() in display_name or TARGET_NAME.lower() in county
    admin_match = "boundary" in result_class or "administrative" in result_type
    geo_match = "idaho" in state or "boise" in city or "boise" in town

    return admin_match and (name_match or geo_match)


def select_ada_county_result(location_results):
    if not isinstance(location_results, list):
        return None

    for result in location_results:
        if is_administrative_candidate(result):
            return result

    for result in location_results:
        if isinstance(result, dict):
            display_name = str(result.get("display_name", "")).lower()
            address = result.get("address", {}) or {}
            county = str(address.get("county", "")).lower()
            if TARGET_NAME.lower() in display_name or TARGET_NAME.lower() in county:
                return result

    return location_results[0] if location_results else None


def get_coordinates_for_location(candidate_location):
    if not isinstance(candidate_location, dict):
        return None
    lat = candidate_location.get("lat")
    lon = candidate_location.get("lon")
    return {"lat": lat, "lon": lon, "display_name": candidate_location.get("display_name", "")}


def format_coordinate_response(coordinates):
    if not isinstance(coordinates, dict):
        return "No coordinates found."

    lat = coordinates.get("lat")
    lon = coordinates.get("lon")
    display_name = coordinates.get("display_name", "Unknown location")

    if lat is None or lon is None:
        return f"Coordinates unavailable for: {display_name}"

    return f"{display_name}\nLatitude: {lat}\nLongitude: {lon}"


def run():
    location_results = lookup_location_by_postal_area(POSTAL_CODE, LOCALITY, REGION)
    ada_county_location = select_ada_county_result(location_results)
    coordinate_data = get_coordinates_for_location(ada_county_location)
    final_answer = format_coordinate_response(coordinate_data)
    print(final_answer)


if __name__ == "__main__":
    try:
        run()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

