from Tools.Local_Business_Data.Search import Search
from Tools.Local_Business_Data.Business_Details import Business_Details

import traceback

POSTAL_CODE = "37203"
CITY = "Nashville"
STATE = "TN"
BUSINESS_NAME = "Nicholson Cleaners"
REGION = "us"
SEARCH_QUERY = f"{BUSINESS_NAME} in area with postal code {POSTAL_CODE}, {CITY}, {STATE}"


def search_business_in_area():
    try:
        return Search(SEARCH_QUERY)
    except Exception:
        raise


def _get_search_data(search_results):
    if not isinstance(search_results, dict):
        return []
    return search_results.get("data", []) or []


def select_matching_business(search_results):
    data = _get_search_data(search_results)
    if not data:
        return None

    business_name_lower = BUSINESS_NAME.lower()
    target_zip_lower = POSTAL_CODE.lower()
    target_city_lower = CITY.lower()
    target_state_lower = STATE.lower()

    best_match = None
    for item in data:
        if not isinstance(item, dict):
            continue

        name = str(item.get("name", "")).lower()
        full_address = str(item.get("full_address", "")).lower()
        address = str(item.get("address", "")).lower()
        city = str(item.get("city", "")).lower()
        zipcode = str(item.get("zipcode", "")).lower()
        state = str(item.get("state", "")).lower()

        name_match = business_name_lower in name
        location_match = (
            target_zip_lower in zipcode
            or target_city_lower in city
            or target_state_lower in state
            or target_zip_lower in full_address
            or target_city_lower in full_address
            or target_state_lower in full_address
            or target_zip_lower in address
        )

        if name_match and location_match:
            return item.get("business_id") or item.get("google_id")

        if name_match and best_match is None:
            best_match = item.get("business_id") or item.get("google_id")

    return best_match


def retrieve_business_coordinates(business_identifier):
    if not business_identifier:
        return None
    try:
        return Business_Details(business_identifier, REGION)
    except Exception:
        raise


def _get_details_data(business_details):
    if not isinstance(business_details, dict):
        return []
    return business_details.get("data", []) or []


def extract_coordinates(business_details):
    data = _get_details_data(business_details)
    if not data:
        return None

    first = data[0] if isinstance(data[0], dict) else {}
    latitude = first.get("latitude")
    longitude = first.get("longitude")

    if latitude is None or longitude is None:
        return None

    return latitude, longitude


def format_coordinates_result(coordinates, business_details=None, search_results=None):
    if coordinates is not None:
        lat, lng = coordinates
        return f"{BUSINESS_NAME} coordinates: latitude {lat}, longitude {lng}"

    candidate = None
    if business_details:
        data = _get_details_data(business_details)
        if data and isinstance(data[0], dict):
            candidate = data[0]
    if candidate is None and search_results:
        data = _get_search_data(search_results)
        if data and isinstance(data[0], dict):
            candidate = data[0]

    if candidate:
        lat = candidate.get("latitude")
        lng = candidate.get("longitude")
        if lat is not None and lng is not None:
            return f"{BUSINESS_NAME} coordinates: latitude {lat}, longitude {lng}"

    return f"Coordinates for {BUSINESS_NAME} in {POSTAL_CODE}, {CITY}, {STATE} were not found."


def main():
    search_results = search_business_in_area()
    business_identifier = select_matching_business(search_results)
    business_details = retrieve_business_coordinates(business_identifier)

    coordinates = extract_coordinates(business_details)
    if coordinates is None and business_identifier is None:
        coordinates = extract_coordinates(search_results)

    print(format_coordinates_result(coordinates, business_details, search_results))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

