from Tools.Local_Business_Data.Search import Search

import traceback

LOCATION_QUERY = "Lumberton, NJ"
BUSINESS_TYPE_QUERY = "brewpub"
SEARCH_QUERY = f"{BUSINESS_TYPE_QUERY} in {LOCATION_QUERY}"


def run_search(query):
    try:
        result = Search(query)
        return result
    except Exception as exc:
        raise RuntimeError(f"Search API call failed for query={query!r}") from exc


def extract_business_list(search_response):
    if not isinstance(search_response, dict):
        return []
    data = search_response.get("data", [])
    if isinstance(data, list):
        return data
    return []


def normalize_text(value):
    if value is None:
        return ""
    return str(value).strip().lower()


def listing_matches_brewpub_and_location(listing, target_location):
    if not isinstance(listing, dict):
        return False

    name = normalize_text(listing.get("name"))
    business_type = normalize_text(listing.get("type"))
    full_address = normalize_text(listing.get("full_address"))
    address = normalize_text(listing.get("address"))
    city = normalize_text(listing.get("city"))
    state = normalize_text(listing.get("state"))
    target = normalize_text(target_location)

    is_brewpub = (
        "brewpub" in name
        or "brewpub" in business_type
        or "brew pub" in name
        or "brew pub" in business_type
    )

    location_matches = (
        target in full_address
        or target in address
        or "lumberton" in city
        or "new jersey" in state
        or state == "nj"
        or "nj" in full_address
        or "nj" in address
    )

    return is_brewpub and location_matches


def filter_brewpubs_in_location(search_results, target_location):
    listings = extract_business_list(search_results)
    matching_listings = []
    for listing in listings:
        if listing_matches_brewpub_and_location(listing, target_location):
            matching_listings.append(listing)
    return matching_listings


def count_listings(listings):
    if not isinstance(listings, list):
        return 0
    total_count = 0
    for _ in listings:
        total_count += 1
    return total_count


def main():
    search_results = run_search(SEARCH_QUERY)
    matching_brewpubs = filter_brewpubs_in_location(search_results, LOCATION_QUERY)
    brewpub_count = count_listings(matching_brewpubs)
    print(f'How many Brewpubs businesses are there in {LOCATION_QUERY}? {brewpub_count}')
    return brewpub_count


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

