from Tools.Local_Business_Data.Search import Search
from Tools.Local_Business_Data.Search import Search

import traceback

WAYNE_PA_QUERY = "Tours in Wayne, PA"
TARGET_CATEGORY = "Tours"
TARGET_LOCATION = "Wayne, PA"


def build_search_query(category, location):
    return f"{category} in {location}"


def safe_get_list(response_dict, key):
    if not isinstance(response_dict, dict):
        return []
    value = response_dict.get(key, [])
    if isinstance(value, list):
        return value
    return []


def normalize_text(value):
    if value is None:
        return ""
    return str(value).strip().lower()


def listing_matches_target(listing):
    # Grounded in response_schema keys: name, full_address, address, city, state, country, type, subtypes
    if not isinstance(listing, dict):
        return False

    name = normalize_text(listing.get("name"))
    full_address = normalize_text(listing.get("full_address"))
    address = normalize_text(listing.get("address"))
    city = normalize_text(listing.get("city"))
    state = normalize_text(listing.get("state"))
    country = normalize_text(listing.get("country"))
    business_type = normalize_text(listing.get("type"))

    subtypes = listing.get("subtypes", [])
    if not isinstance(subtypes, list):
        subtypes = []
    subtypes_normalized = [normalize_text(item) for item in subtypes]

    location_hint = normalize_text(TARGET_LOCATION)
    category_hint = normalize_text(TARGET_CATEGORY)

    location_match = (
        location_hint in full_address
        or location_hint in address
        or ("wayne" in city and ("pa" in state or "pennsylvania" in state))
        or ("wayne" in full_address and ("pa" in full_address or "pennsylvania" in full_address))
    )

    category_match = (
        category_hint in name
        or category_hint in business_type
        or any(category_hint in subtype for subtype in subtypes_normalized)
    )

    return location_match and category_match and country in ("us", "usa", "united states", "")


def build_uniqueness_key(listing):
    # Prefer stable IDs from schema
    for key in ("business_id", "place_id", "google_id", "cid"):
        value = listing.get(key)
        if value:
            return f"{key}:{value}"
    name = normalize_text(listing.get("name"))
    address = normalize_text(listing.get("full_address") or listing.get("address"))
    return f"name_address:{name}|{address}"


def search_tours_businesses_in_wayne_pa():
    query = build_search_query(TARGET_CATEGORY, TARGET_LOCATION)
    return Search(query)


def filter_unique_tours_businesses(search_results):
    data = safe_get_list(search_results, "data")
    unique_businesses = {}
    for listing in data:
        if listing_matches_target(listing):
            key = build_uniqueness_key(listing)
            unique_businesses[key] = listing
    return unique_businesses


def count_unique_businesses(unique_businesses):
    return len(unique_businesses)


def format_output(total_count):
    print(f"Number of Tours businesses in Wayne, PA: {total_count}")


def main():
    search_results = search_tours_businesses_in_wayne_pa()
    unique_businesses = filter_unique_tours_businesses(search_results)
    total_tours_businesses = count_unique_businesses(unique_businesses)
    format_output(total_tours_businesses)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

