        return data
    return []


def count_businesses(listings):
    if not isinstance(listings, list):
        return 0
    return len(listings)


def format_output(area_query, total_businesses):
    return f'Number of businesses found for "{area_query}": {total_businesses}'


def main():
    search_result = search_businesses_in_area(BUSINESS_QUERY)
    business_listings = extract_business_listings(search_result)
    total_businesses = count_businesses(business_listings)
    print(format_output(AREA_QUERY, total_businesses))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

