from Tools.Local_Business_Data.Search_In_Area import Search_In_Area

import traceback

# Module-level constants pinned from the user requirement and reasonable assumptions.
LOCATION_QUERY = "08026 area of Gibbsboro, NJ"
SEARCH_KEYWORD = "business"
LATITUDE = 39.8473
LONGITUDE = -74.9674
ZOOM = 13


def build_location_query(base_location: str) -> str:
    return f"{SEARCH_KEYWORD} in {base_location}"


def search_businesses_in_area(location_query: str):
    # API_calling_code defines Search_In_Area(query, lat, lng, zoom)
    return Search_In_Area(location_query, LATITUDE, LONGITUDE, ZOOM)


def extract_business_list(api_response):
    if not isinstance(api_response, dict):
        return []
    data = api_response.get("data", [])
    if data is None:
        return []
    if not isinstance(data, list):
        return []
    return data


def deduplicate_business_listings(listings):
    unique = []
    seen = set()
    for item in listings:
        if not isinstance(item, dict):
            continue
        business_id = item.get("business_id")
        place_id = item.get("place_id")
        name = item.get("name")
        address = item.get("full_address") or item.get("address")

        key = business_id or place_id or f"{name}|{address}"
        if key in seen:
            continue
        seen.add(key)
        unique.append(item)
    return unique


def count_businesses(listings):
    return len(listings)


def format_result_message(count, location_query):
    return f"Found {count} unique businesses for {location_query}."


def main():
    location_query = build_location_query(LOCATION_QUERY)
    api_response = search_businesses_in_area(location_query)
    listings = extract_business_list(api_response)
    unique_listings = deduplicate_business_listings(listings)
    business_count = count_businesses(unique_listings)
    message = format_result_message(business_count, LOCATION_QUERY)
    print(message)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

