from Tools.Local_Business_Data.Search import Search
from Tools.Local_Business_Data.Business_Details import Business_Details

import traceback

AFFTON_MO_QUERY = "Restaurants in Affton, MO"
BUSINESS_REGION = "us"


def is_restaurant_entry(entry):
    entry_type = str(entry.get("type", "")).lower()
    subtypes = entry.get("subtypes", [])
    subtypes_text = " ".join([str(x).lower() for x in subtypes]) if isinstance(subtypes, list) else str(subtypes).lower()
    return "restaurant" in entry_type or "restaurant" in subtypes_text


def search_restaurants_in_area(query):
    try:
        result = Search(query)
        return result
    except Exception as exc:
        raise RuntimeError(f"Search failed for query={query!r}") from exc


def extract_restaurant_candidates(search_results):
    data = search_results.get("data", [])
    if not isinstance(data, list):
        return []
    return [entry for entry in data if isinstance(entry, dict) and is_restaurant_entry(entry)]


def get_business_details_for_candidates(candidates):
    details = []
    for candidate in candidates:
        business_id = candidate.get("business_id")
        if not business_id:
            continue
        try:
            detail_result = Business_Details(business_id, BUSINESS_REGION)
            detail_data = detail_result.get("data", [])
            if isinstance(detail_data, list) and detail_data:
                details.append(detail_data[0])
        except Exception:
            continue
    return details


def find_highest_rated_business(business_details_list):
    highest = None
    highest_rating = None

    for business in business_details_list:
        if not isinstance(business, dict):
            continue
        rating = business.get("rating")
        if rating is None:
            continue
        try:
            rating_value = float(rating)
        except (TypeError, ValueError):
            continue

        if highest is None or highest_rating is None or rating_value > highest_rating:
            highest = business
            highest_rating = rating_value

    return highest


def print_business_summary(business):
    if not business:
        print("No restaurant business data found for Affton, MO.")
        return

    name = business.get("name", "Unknown")
    rating = business.get("rating", "N/A")
    review_count = business.get("review_count", "N/A")
    address = business.get("full_address") or business.get("address") or "N/A"

    print("Highest-rated restaurant business in Affton, MO:")
    print(f"Name: {name}")
    print(f"Rating: {rating}")
    print(f"Review count: {review_count}")
    print(f"Address: {address}")


def main():
    search_results = search_restaurants_in_area(AFFTON_MO_QUERY)
    restaurant_candidates = extract_restaurant_candidates(search_results)

    if not restaurant_candidates:
        data = search_results.get("data", [])
        if isinstance(data, list):
            restaurant_candidates = [entry for entry in data if isinstance(entry, dict)]

    restaurant_details = get_business_details_for_candidates(restaurant_candidates)

    if not restaurant_details:
        fallback_best = None
        fallback_rating = None
        for entry in restaurant_candidates:
            if not isinstance(entry, dict):
                continue
            rating = entry.get("rating")
            if rating is None:
                continue
            try:
                rating_value = float(rating)
            except (TypeError, ValueError):
                continue
            if fallback_best is None or fallback_rating is None or rating_value > fallback_rating:
                fallback_best = entry
                fallback_rating = rating_value
        return fallback_best

    return find_highest_rated_business(restaurant_details)


if __name__ == "__main__":
    try:
        best_business = main()
        print_business_summary(best_business)
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

