from Tools.Local_Business_Data.Search import Search
from Tools.Local_Business_Data.Business_Details import Business_Details

import traceback

# Module-level constants pinned from the user requirement and pseudocode.
SEARCH_QUERY = "Sandwiches businesses in Garnet Valley, PA"
REGION = "us"
MIN_RATING = None  # Not used for filtering; kept as a module-level constant placeholder.

def search_sandwich_businesses_in_garnet_valley():
    """
    Search for sandwich-related businesses in Garnet Valley, PA.
    Returns the raw API response dict, or an empty result structure on failure to parse.
    """
    try:
        return Search(SEARCH_QUERY)
    except Exception:
        raise

def extract_business_candidates(search_response):
    """
    Extract candidate business records from the Search API response.
    Safely handles empty or missing data.
    """
    if not isinstance(search_response, dict):
        return []

    data = search_response.get("data", [])
    if not isinstance(data, list):
        return []

    candidates = []
    for item in data:
        if isinstance(item, dict):
            business_id = item.get("business_id")
            if business_id:
                candidates.append(item)
    return candidates

def fetch_business_details_for_candidates(candidates):
    """
    Fetch detailed business data for each candidate using Business_Details.
    Returns a list of detail records; empty list if no candidates.
    """
    details_list = []
    for candidate in candidates:
        business_id = candidate.get("business_id")
        if not business_id:
            continue
        try:
            details_response = Business_Details(business_id, REGION)
            details_list.append(details_response)
        except Exception:
            # Skip failed detail lookups and continue with remaining candidates.
            continue
    return details_list

def extract_best_business_record(details_list, fallback_candidates=None):
    """
    Select the business with the highest rating from detail responses.
    If details are unavailable, falls back to search result records.
    Returns a normalized summary dict.
    """
    best_record = None
    best_rating = None

    def consider_record(record):
        nonlocal best_record, best_rating
        if not isinstance(record, dict):
            return
        rating = record.get("rating")
        if rating is None:
            return
        try:
            rating_value = float(rating)
        except (TypeError, ValueError):
            return
        if best_rating is None or rating_value > best_rating:
            best_rating = rating_value
            best_record = record

    if details_list:
        for detail_response in details_list:
            if isinstance(detail_response, dict):
                data = detail_response.get("data", [])
                if isinstance(data, list):
                    for record in data:
                        consider_record(record)

    if best_record is None and fallback_candidates:
        for record in fallback_candidates:
            consider_record(record)

    if best_record is None:
        return {
            "name": None,
            "rating": None,
            "full_address": None,
            "business_id": None,
            "source": "no_data",
        }

    return {
        "name": best_record.get("name"),
        "rating": best_record.get("rating"),
        "full_address": best_record.get("full_address"),
        "business_id": best_record.get("business_id"),
        "source": "business_details" if details_list else "search_results",
    }

def format_result_message(best_business):
    """
    Create a readable, task-oriented output message.
    """
    name = best_business.get("name")
    rating = best_business.get("rating")
    address = best_business.get("full_address")
    source = best_business.get("source")

    if not name:
        return "No sandwich business data was found for Garnet Valley, PA."

    message_lines = [
        f'Highest-rated sandwich business in Garnet Valley, PA: {name}',
        f"Rating: {rating}",
    ]
    if address:
        message_lines.append(f"Address: {address}")
    message_lines.append(f"Source: {source}")
    return "\n".join(message_lines)

def main():
    search_response = search_sandwich_businesses_in_garnet_valley()
    candidates = extract_business_candidates(search_response)
    details_list = fetch_business_details_for_candidates(candidates)
    best_business = extract_best_business_record(details_list, fallback_candidates=candidates)
    print(format_result_message(best_business))

if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

