from Tools.Local_Business_Data.Search import Search
from Tools.Local_Business_Data.Business_Details import Business_Details
from Tools.Local_Business_Data.Business_Reviews import Business_Reviews

import traceback

# Module-level pinned constants
SEARCH_QUERY = "pet stores in Oakville, MO"
REGION = "us"
DETAILS_REGION = "us"
MAX_CANDIDATES_TO_INSPECT = 10


def safe_get(data, path, default=None):
    current = data
    for key in path:
        if isinstance(current, dict):
            current = current.get(key, default)
        elif isinstance(current, list) and isinstance(key, int) and 0 <= key < len(current):
            current = current[key]
        else:
            return default
        if current is default:
            return default
    return current


def search_pet_stores_in_oakville():
    try:
        result = Search(SEARCH_QUERY)
        data = result.get("data", []) if isinstance(result, dict) else []
        return data if isinstance(data, list) else []
    except Exception:
        return []


def get_business_details_for_candidates(candidate_business_list):
    detailed_business_list = []
    for candidate in candidate_business_list[:MAX_CANDIDATES_TO_INSPECT]:
        business_id = candidate.get("business_id")
        if not business_id:
            continue
        try:
            result = Business_Details(business_id, DETAILS_REGION)
            data = result.get("data", []) if isinstance(result, dict) else []
            if isinstance(data, list) and data:
                detailed_business_list.extend(data)
            else:
                detailed_business_list.append(candidate)
        except Exception:
            detailed_business_list.append(candidate)
    return detailed_business_list


def extract_review_count(business):
    review_count = business.get("review_count")
    if isinstance(review_count, (int, float)):
        return review_count

    details_review_count = safe_get(business, ["review_count"], None)
    if isinstance(details_review_count, (int, float)):
        return details_review_count

    return -1


def compare_review_counts(detailed_business_list):
    if not detailed_business_list:
        return None

    top_business = None
    top_review_count = -1

    for business in detailed_business_list:
        review_count = extract_review_count(business)
        if review_count > top_review_count:
            top_review_count = review_count
            top_business = business

    return top_business


def format_business_output(business):
    if not business:
        return "No pet store businesses were found for Oakville, MO."

    name = business.get("name", "Unknown business")
    review_count = business.get("review_count", "Unknown")
    full_address = business.get("full_address") or business.get("address") or "Unknown address"
    business_type = business.get("type", "Unknown type")

    return (
        f"Pet store business with the highest review count in Oakville, MO:\n"
        f"Name: {name}\n"
        f"Type: {business_type}\n"
        f"Review count: {review_count}\n"
        f"Address: {full_address}"
    )


def main():
    candidate_business_list = search_pet_stores_in_oakville()
    detailed_business_list = get_business_details_for_candidates(candidate_business_list)
    top_business = compare_review_counts(detailed_business_list)
    print(format_business_output(top_business))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

