import traceback

LOCATION_QUERY = "Diagnostic Imaging in New Orleans, LA"
CATEGORY_KEYWORDS = ["diagnostic imaging", "imaging"]
TARGET_CITY_KEYWORD = "new orleans"
TARGET_STATE_KEYWORD = "la"
MIN_REVIEW_COUNT = -1


def search_diagnostic_imaging_businesses(location_query):
    try:
        return Search(location_query)
    except Exception as exc:
        raise RuntimeError(f"Search API failed: {exc}") from exc


def extract_candidate_businesses(search_response):
    candidates = []
    data = search_response.get("data", [])
    for item in data:
        name = str(item.get("name", "")).strip()
        full_address = str(item.get("full_address", "")).strip()
        city = str(item.get("city", "")).strip()
        state = str(item.get("state", "")).strip()
        type_value = str(item.get("type", "")).strip()
        subtypes = item.get("subtypes", []) or []

        searchable_text = " ".join(
            [
                name.lower(),
                full_address.lower(),
                city.lower(),
                state.lower(),
                type_value.lower(),
                " ".join(str(s).lower() for s in subtypes),
            ]
        )

        if any(keyword in searchable_text for keyword in CATEGORY_KEYWORDS) and \
           TARGET_CITY_KEYWORD in searchable_text and \
           TARGET_STATE_KEYWORD in searchable_text:
            business_id = item.get("business_id")
            if business_id:
                candidates.append(
                    {
                        "business_id": business_id,
                        "name": name,
                        "full_address": full_address,
                    }
                )

    return candidates


def get_business_details_for_candidates(candidates):
    detailed_businesses = []
    for candidate in candidates:
        try:
            details_response = Business_Details(candidate["business_id"], "us")
            data = details_response.get("data", [])
            details_item = data[0] if data else {}
            review_count = details_item.get("review_count", 0) or 0
            detailed_businesses.append(
                {
                    "business_id": candidate["business_id"],
                    "name": details_item.get("name", candidate["name"]),
                    "full_address": details_item.get("full_address", candidate["full_address"]),
                    "review_count": review_count,
                }
            )
        except Exception:
            continue

    return detailed_businesses


def select_business_with_highest_review_count(detailed_businesses):
    top_business = None
    highest_review_count = MIN_REVIEW_COUNT

    for business in detailed_businesses:
        review_count = business.get("review_count", 0) or 0
        if review_count > highest_review_count:
            highest_review_count = review_count
            top_business = business

    return top_business


def format_result(top_business):
    if not top_business:
        return "No Diagnostic Imaging businesses were found in New Orleans, LA."

    return (
        f"Business with the highest review count in New Orleans, LA among Diagnostic Imaging businesses:\n"
        f"Name: {top_business.get('name', 'Unknown')}\n"
        f"Address: {top_business.get('full_address', 'Unknown')}\n"
        f"Review Count: {top_business.get('review_count', 0)}"
    )


def main():
    search_response = search_diagnostic_imaging_businesses(LOCATION_QUERY)
    candidates = extract_candidate_businesses(search_response)
    detailed_businesses = get_business_details_for_candidates(candidates)
    top_business = select_business_with_highest_review_count(detailed_businesses)
    print(format_result(top_business))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

