# Module-level pinned constants
SEARCH_QUERY = "Bridal businesses in Ardmore, PA"
SEARCH_REGION = "us"
DETAILS_REGION = "us"


def safe_get(d, path, default=None):
    current = d
    for key in path:
        if not isinstance(current, dict) or key not in current:
            return default
        current = current[key]
    return current


def extract_candidates(search_response):
    data = safe_get(search_response, ["data"], [])
    if not isinstance(data, list):
        return []
    candidates = []
    for item in data:
        if isinstance(item, dict):
            candidates.append(item)
    return candidates


def fetch_business_details(business_id, region):
    try:
        response = Business_Details(business_id, region)
        return response
    except Exception:
        return None


def extract_details_list(candidate_business_list):
    detailed_business_list = []
    for candidate in candidate_business_list:
        business_id = candidate.get("business_id")
        if not business_id:
            continue
        details_response = fetch_business_details(business_id, DETAILS_REGION)
        if not details_response:
            continue
        details_data = safe_get(details_response, ["data"], [])
        if isinstance(details_data, list):
            for detail in details_data:
                if isinstance(detail, dict):
                    detailed_business_list.append(detail)
    return detailed_business_list


def get_review_count(business_record):
    review_count = business_record.get("review_count")
    if isinstance(review_count, (int, float)):
        return review_count
    return -1


def select_highest_review_count_business(detailed_business_list):
    top_business = None
    top_review_count = -1

    for business in detailed_business_list:
        current_review_count = get_review_count(business)
        if current_review_count > top_review_count:
            top_review_count = current_review_count
            top_business = business

    return top_business, top_review_count


def search_bridal_businesses_in_area():
    try:
        response = Search(SEARCH_QUERY)
        return response
    except Exception:
        return None


def format_business_output(top_business, top_review_count):
    if not top_business:
        return "No bridal businesses were found in Ardmore, PA."

    name = top_business.get("name", "Unknown business")
    address = top_business.get("full_address") or top_business.get("address") or "Address not available"
    rating = top_business.get("rating", "N/A")
    review_count = top_review_count if top_review_count >= 0 else top_business.get("review_count", "N/A")
    business_type = top_business.get("type", "N/A")

    lines = [
        "Bridal business with the highest review count in Ardmore, PA:",
        f"Name: {name}",
        f"Type: {business_type}",
        f"Address: {address}",
        f"Rating: {rating}",
        f"Review Count: {review_count}",
    ]
    return "\n".join(lines)


def main():
    search_response = search_bridal_businesses_in_area()
    if not search_response:
        print("No bridal businesses were found in Ardmore, PA.")
        return

    candidate_business_list = extract_candidates(search_response)
    detailed_business_list = extract_details_list(candidate_business_list)

    if not detailed_business_list and candidate_business_list:
        detailed_business_list = candidate_business_list

    top_business, top_review_count = select_highest_review_count_business(detailed_business_list)
    output = format_business_output(top_business, top_review_count)
    print(output)


if __name__ == "__main__":
