import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Local_Business_Data.Search import Search
from Tools.Local_Business_Data.Search_Nearby import Search_Nearby
from Tools.Local_Business_Data.Business_Reviews import Business_Reviews
from Tools.Local_Business_Data.Business_Details import Business_Details

import traceback

KOHLS_QUERY = "Kohl's"
NEARBY_QUERY = "business"
REGION = "us"
RADIUS_MILES = 5
MAX_NEARBY_RESULTS = 10


def find_kohls_location():
    try:
        result = Search(KOHLS_QUERY)
        data = result.get("data", []) if isinstance(result, dict) else []
        if not data:
            return None

        first = data[0]
        latitude = first.get("latitude")
        longitude = first.get("longitude")
        business_id = first.get("business_id")
        name = first.get("name", "Kohl's")

        if latitude is None or longitude is None:
            return None

        return {
            "name": name,
            "business_id": business_id,
            "latitude": latitude,
            "longitude": longitude,
        }
    except Exception:
        return None


def search_businesses_within_radius(location_context):
    if not location_context:
        return []

    try:
        result = Search_Nearby(
            NEARBY_QUERY,
            location_context["latitude"],
            location_context["longitude"],
        )
        data = result.get("data", []) if isinstance(result, dict) else []
        if not isinstance(data, list):
            return []
        return data[:MAX_NEARBY_RESULTS]
    except Exception:
        return []


def get_business_review_count(business_id):
    if not business_id:
        return None

    try:
        result = Business_Reviews(business_id)
        data = result.get("data", []) if isinstance(result, dict) else []
        if not data:
            return None
        review_info = data[0]
        return review_info.get("review_count")
    except Exception:
        return None


def collect_review_counts(business_listings):
    review_counts = []
    for business in business_listings:
        if not isinstance(business, dict):
            continue
        business_id = business.get("business_id")
        review_count = get_business_review_count(business_id)
        if isinstance(review_count, (int, float)):
            review_counts.append(review_count)
    return review_counts


def compute_average_review_count(review_counts):
    if not review_counts:
        return None
    total_reviews = sum(review_counts)
    business_total = len(review_counts)
    if business_total == 0:
        return None
    return total_reviews / business_total


def print_result(kohls_location, nearby_businesses, review_counts, average_review_count):
    print("Kohl's location:")
    if kohls_location:
        print(f"  Name: {kohls_location.get('name', 'Kohl\'s')}")
        print(f"  Latitude: {kohls_location.get('latitude')}")
        print(f"  Longitude: {kohls_location.get('longitude')}")
    else:
        print("  Could not locate Kohl's.")

    print()
    print(f"Nearby businesses found: {len(nearby_businesses)}")
    print(f"Businesses with usable review counts: {len(review_counts)}")

    if average_review_count is None:
        print("Average review count: no data available")
    else:
        print(f"Average review count: {average_review_count:.2f}")


def main():
    kohls_location = find_kohls_location()
    nearby_businesses = search_businesses_within_radius(kohls_location)
    review_counts = collect_review_counts(nearby_businesses)
    average_review_count = compute_average_review_count(review_counts)
    print_result(kohls_location, nearby_businesses, review_counts, average_review_count)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
