SEARCH_LIMIT = 50


def search_businesses_in_mccordsville():
    try:
        response = Search(MCCORDSVILLE_QUERY)
        data = response.get("data", [])
        if not isinstance(data, list):
            return []
        return data
    except Exception:
        return []


def get_business_details(business):
    business_id = business.get("business_id")
    if not business_id:
        return None

    try:
        response = Place_info(business_id)
        data = response.get("data", [])
        if not isinstance(data, list) or not data:
            return None
        return data[0]
    except Exception:
        return None


def is_currently_open(working_hours):
    if not working_hours:
        return False

    if isinstance(working_hours, dict):
        from datetime import datetime

        weekday_to_key = {
            0: "Monday",
            1: "Tuesday",
            2: "Wednesday",
            3: "Thursday",
            4: "Friday",
            5: "Saturday",
            6: "Sunday",
        }
        current_day = weekday_to_key[datetime.now().weekday()]
        day_hours = working_hours.get(current_day, [])
        if isinstance(day_hours, list):
            joined = " ".join(str(x).lower() for x in day_hours)
            return ("open" in joined) and ("closed" not in joined)
        return False

    if isinstance(working_hours, list):
        joined = " ".join(str(x).lower() for x in working_hours)
        if "closed" in joined:
            return False
        if "open" in joined:
            return True
        return False

    return False


def count_not_open_businesses(businesses):
    not_open_count = 0

    for business in businesses[:SEARCH_LIMIT]:
        details = get_business_details(business)
        if details is None:
            continue

        working_hours = details.get("working_hours")
        if not is_currently_open(working_hours):
            not_open_count += 1

    return not_open_count


def main():
    businesses = search_businesses_in_mccordsville()
    not_open_count = count_not_open_businesses(businesses)
    print(f"Businesses not open currently in McCordsville: {not_open_count}")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

