def hours_indicate_closed(working_hours):
    if working_hours is None:
        return False

    text = str(working_hours).lower()

    for indicator in BUSINESS_CLOSED_INDICATORS:
        if indicator in text:
            return True

    for indicator in BUSINESS_OPEN_INDICATORS:
        if indicator in text:
            return False

    return False


def is_not_open_currently(business_record):
    if not isinstance(business_record, dict):
        return False

    working_hours = business_record.get("working_hours")
    if hours_indicate_closed(working_hours):
        return True

    description = business_record.get("description", [])
    if isinstance(description, list):
        desc_text = " ".join(str(item) for item in description).lower()
    else:
        desc_text = str(description).lower()

    for indicator in BUSINESS_CLOSED_INDICATORS:
        if indicator in desc_text:
            return True

    return False


def count_businesses_not_open(search_results):
    businesses = extract_business_list(search_results)
    not_open_count = 0

    for business in businesses:
        business_reference = get_business_reference(business)
        place_response = fetch_place_info(business_reference)

        place_list = extract_place_list(place_response)
        if place_list:
            place_record = place_list[0]
            if is_not_open_currently(place_record):
                not_open_count += 1
        else:
            if is_not_open_currently(business):
                not_open_count += 1

    return not_open_count


def main():
    search_results = search_businesses_in_terra_ceia()
    closed_now_count = count_businesses_not_open(search_results)
    print(f"Businesses not open currently in Terra Ceia: {closed_now_count}")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Maps_Data.Search import Search
from Tools.Maps_Data.Place_info import Place_info
from Tools.Maps_Data.Place_info import Place_info

import traceback

SEARCH_QUERY = "Maryland Heights"
OPEN_INDICATORS = ("open", "currently open", "open now", "open today")
CLOSED_INDICATORS = ("closed", "temporarily closed", "permanently closed", "not open")
MAX_BUSINESSES_TO_CHECK = 25


def search_businesses_in_area(query):
    try:
        response = Search(query)
        return response
    except Exception as exc:
        raise RuntimeError(f"Search API failed for query={query!r}") from exc


def extract_listings(search_response):
    data = search_response.get("data", [])
    if not isinstance(data, list):
        return []
    return data


def get_business_ids(listings):
    business_ids = []
    for item in listings:
        if isinstance(item, dict):
            business_id = item.get("business_id")
            if business_id:
                business_ids.append(business_id)
    return business_ids


def fetch_place_info_for_business(business_id):
    try:
        response = Place_info(business_id)
        return response
    except Exception as exc:
        raise RuntimeError(f"Place_info API failed for business_id={business_id!r}") from exc


def extract_place_entries(place_response):
    data = place_response.get("data", [])
    if not isinstance(data, list):
        return []
    return data


def normalize_text(value):
    if value is None:
        return ""
    if isinstance(value, list):
        return " ".join(str(v) for v in value if v is not None).strip().lower()
    return str(value).strip().lower()


def is_not_open_now(business_record):
    if not isinstance(business_record, dict):
        return False

    working_hours = business_record.get("working_hours")
    text_blob = normalize_text(working_hours)

    if not text_blob:
        return False

    if any(indicator in text_blob for indicator in CLOSED_INDICATORS):
        return True

    if any(indicator in text_blob for indicator in OPEN_INDICATORS):
        return False

    return False


def count_not_open_businesses(place_entries):
    count = 0
    for entry in place_entries:
        if is_not_open_now(entry):
            count += 1
    return count


def gather_place_data_for_search_results(search_query):
    search_response = search_businesses_in_area(search_query)
    listings = extract_listings(search_response)
    business_ids = get_business_ids(listings)

    if not business_ids:
        return []

    place_entries = []
    for business_id in business_ids[:MAX_BUSINESSES_TO_CHECK]:
        place_response = fetch_place_info_for_business(business_id)
        entries = extract_place_entries(place_response)
        place_entries.extend(entries)
    return place_entries


def main():
    place_entries = gather_place_data_for_search_results(SEARCH_QUERY)
    not_open_count = count_not_open_businesses(place_entries)
    print(not_open_count)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Maps_Data.Search import Search
from Tools.Maps_Data.Place_info import Place_info
from Tools.Google_Search.Search import Search

import traceback

# Module-level pinned constants
SEARCH_QUERY = "Arts & Entertainment Florissant"
LOCAL_SEARCH_QUERY = "Arts & Entertainment in Florissant"
AVERAGE_LABEL = "Average star rating of Arts & Entertainment businesses in Florissant"
API_RESULT_KEY = "data"


def search_businesses():
    """
    Search for Arts & Entertainment businesses in Florissant.
    Returns a list of business objects (possibly empty).
    """
    try:
        response = Search(SEARCH_QUERY)
        if not isinstance(response, dict):
            return []
        data = response.get(API_RESULT_KEY, [])
        if isinstance(data, list):
            return data
        return []
    except Exception:
        return []


def extract_business_ids(business_listings):
    """
    Extract business identifiers from search results.
    Uses exact schema key: 'business_id'
    """
    business_ids = []
    for business in business_listings or []:
        if isinstance(business, dict):
            business_id = business.get("business_id")
            if business_id:
                business_ids.append(business_id)
    return business_ids


def fetch_ratings_for_businesses(business_ids):
    """
    Fetch ratings for each business id using Place_info.
    Uses exact schema key: 'rating'
    """
    ratings = []
    for business_id in business_ids:
        try:
            response = Place_info(business_id)
            if not isinstance(response, dict):
                continue
            data = response.get(API_RESULT_KEY, [])
            if not isinstance(data, list):
                continue
            for item in data:
                if isinstance(item, dict):
                    rating = item.get("rating")
                    if isinstance(rating, (int, float)):
                        ratings.append(float(rating))
        except Exception:
            continue
    return ratings


def compute_average(values):
    """
    Compute arithmetic mean for a list of numeric values.
    """
    if not values:
        return None
    return sum(values) / len(values)


def format_average_result(average_rating, rating_count):
    """
    Produce readable task-oriented output.
    """
    if average_rating is None:
        return f"{AVERAGE_LABEL}: no data available"
    return (
        f"{AVERAGE_LABEL}: {average_rating:.2f} "
        f"(based on {rating_count} business rating(s))"
    )


def main():
    businesses = search_businesses()
    business_ids = extract_business_ids(businesses)
    ratings = fetch_ratings_for_businesses(business_ids)
    average_rating = compute_average(ratings)
    print(format_average_result(average_rating, len(ratings)))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Local_Business_Data.Search import Search
from Tools.Local_Business_Data.Business_Details import Business_Details
from Tools.Google_Search.Search import Search

import traceback

# Module-level pinned constants
QUERY_BODY_SHOPS_IN_BRENTWOOD = "Body Shops in Brentwood"
REGION_US = "us"
DETAILS_REQUEST_LIMIT = 10  # Assumption for practical processing of search results


def search_body_shops_in_brentwood():
    """
    Perform a location-based search for Body Shops businesses in Brentwood.
    Returns the raw API response dict.
    """
    try:
        return Search(QUERY_BODY_SHOPS_IN_BRENTWOOD)
    except Exception as exc:
        raise RuntimeError(f"Failed to search for body shops in Brentwood: {exc}") from exc


def extract_search_business_items(search_response):
    """
    Extract the business list from the Search API response using exact schema keys.
    Schema path: response['data']
    """
    if not isinstance(search_response, dict):
        return []
    return search_response.get("data", [])


def get_business_details_for_results(search_results):
    """
    Retrieve business details for each search result using exact schema keys.
    Required input path from search results: item['business_id']
    """
    details_list = []
    if not isinstance(search_results, list):
        return details_list

    for business in search_results[:DETAILS_REQUEST_LIMIT]:
        business_id = business.get("business_id")
        if not business_id:
            continue
        try:
            response = Business_Details(business_id, REGION_US)
            details_list.append(response)
        except Exception:
            # Continue processing remaining businesses; missing details are not fatal.
            continue

    return details_list


def extract_business_records(details_list):
    """
    Extract the business records from the Business_Details API response using exact schema keys.
    Schema path: response['data']
    """
    records = []
    if not isinstance(details_list, list):
        return records

    for detail_response in details_list:
        if not isinstance(detail_response, dict):
            continue
        data = detail_response.get("data", [])
        if isinstance(data, list):
            records.extend(data)
    return records


def compute_average_star_rating(business_records):
    """
    Compute average rating from records using exact schema key 'rating'.
    Ignores missing or non-numeric ratings.
    """
    ratings = []
    if not isinstance(business_records, list):
        return None

    for record in business_records:
        if not isinstance(record, dict):
            continue
        rating = record.get("rating")
        if isinstance(rating, (int, float)):
            ratings.append(float(rating))

    if not ratings:
        return None

    return sum(ratings) / len(ratings)


def format_average_rating_message(average_rating, record_count):
    """
    Create readable, task-oriented output.
    """
    if average_rating is None:
        return "No valid star ratings were found for Body Shops businesses in Brentwood."
    return (
        f"Average star rating for Body Shops businesses in Brentwood: "
        f"{average_rating:.2f} based on {record_count} business record(s)."
    )


def main():
    search_response = search_body_shops_in_brentwood()
    search_results = extract_search_business_items(search_response)
    business_details = get_business_details_for_results(search_results)
    business_records = extract_business_records(business_details)
    average_rating = compute_average_star_rating(business_records)
    message = format_average_rating_message(average_rating, len(business_records))
    print(message)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Local_Business_Data.Search import Search
from Tools.Local_Business_Data.Business_Details import Business_Details

import traceback
from collections import Counter

SPRING_HOUSE_QUERY = "businesses in Spring House, PA"
REGION = "us"
MAX_CANDIDATES = 20
MIN_RESULT_COUNT_FOR_OUTPUT = 1


def search_businesses_in_spring_house():
    try:
        return Search(SPRING_HOUSE_QUERY)
    except Exception:
        raise


def extract_candidate_businesses(search_results):
    data = search_results.get("data", [])
    candidates = []
    for item in data[:MAX_CANDIDATES]:
        business_id = item.get("business_id")
        name = item.get("name")
        if business_id:
            candidates.append(
                {
                    "business_id": business_id,
                    "name": name,
                }
            )
    return candidates


def get_business_details_for_candidates(candidates):
    detailed_records = []
    for candidate in candidates:
        business_id = candidate.get("business_id")
        if not business_id:
            continue
        try:
            detail_response = Business_Details(business_id, REGION)
            detailed_records.append(detail_response)
        except Exception:
            continue
    return detailed_records


def extract_postal_code_region(detail_response):
    data = detail_response.get("data", [])
    if not data:
        return None

    record = data[0]
    zipcode = record.get("zipcode")
    if zipcode:
        return str(zipcode)

    full_address = record.get("full_address")
    if full_address and isinstance(full_address, str):
        parts = full_address.strip().split()
        for part in reversed(parts):
            if part.isdigit() and len(part) >= 5:
                return part

    return None


def count_businesses_by_postal_code(detailed_records):
    counts = Counter()
    for record in detailed_records:
        postal_code = extract_postal_code_region(record)
        if postal_code:
            counts[postal_code] += 1
    return counts


def determine_most_common_postal_code(postal_code_counts):
    if not postal_code_counts:
        return None
    most_common = postal_code_counts.most_common(1)
    if not most_common:
        return None
    return most_common[0][0]


def format_output(postal_code, counts):
    if postal_code is None:
        print("No postal code data could be determined for businesses in Spring House, PA.")
        return

    count = counts.get(postal_code, 0)
    print(f"Postal code region with the most businesses in Spring House, PA: {postal_code}")
    print(f"Business count in that postal code region: {count}")


def main():
    search_results = search_businesses_in_spring_house()
    candidates = extract_candidate_businesses(search_results)
    detailed_records = get_business_details_for_candidates(candidates)
    postal_code_counts = count_businesses_by_postal_code(detailed_records)
    winning_postal_code = determine_most_common_postal_code(postal_code_counts)
    format_output(winning_postal_code, postal_code_counts)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise
